def validate_paem_static_docs_replay_configuration(
    method: str,
    self_replay_jsonl: Sequence[str] | None,
    allow_generated_combined_replay: bool,
    disable_anchor_mask: bool = False,
) -> None:
    """Keep generated replay a narrow, explicit combined-source opt-in."""
    if (
        disable_anchor_mask
        and method != PAEM_INTERACTION_AND_STATIC_DOCS_FULL_METHOD
    ):
        raise ValueError(
            "--paem-disable-anchor-mask is valid only for "
            "paem_interaction_and_static_docs_full"
        )
    if disable_anchor_mask and allow_generated_combined_replay:
        raise ValueError(
            "unmasked combined NTP must not enable generated replay"
        )
    if disable_anchor_mask and self_replay_jsonl:
        raise ValueError(
            "unmasked combined NTP must not load a replay anchor"
        )
    if (
        allow_generated_combined_replay
        and method != PAEM_INTERACTION_AND_STATIC_DOCS_FULL_METHOD
    ):
        raise ValueError(
            "--paem-allow-generated-replay-for-combined-source is valid "
            "only for paem_interaction_and_static_docs_full"
        )
    if (
        method in PAEM_STATIC_DOCS_METHODS
        and not self_replay_jsonl
        and not allow_generated_combined_replay
        and not disable_anchor_mask
    ):
        raise ValueError(
            f"{method} requires --self-replay-jsonl so the static and "
            "outcome arms can share an immutable anchor bank; the combined "
            "source producer requires the explicit generated-replay opt-in"
        )
PAEM_METHODS = frozenset(
    {
        *PAEM_CANDIDATE_POLICY_METHODS,
        *PAEM_HARD_ANCHOR_METHODS,
    }
)
