def parse_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    normalized = str(value).strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise argparse.ArgumentTypeError(f"expected a boolean value, got {value!r}")


def parse_anchor_blend_candidates(value: str) -> tuple[float, ...]:
    """Parse a comma/space-separated, sorted set of blend coefficients."""
    try:
        candidates = {
            float(item)
            for item in re.split(r"[\s,]+", str(value).strip())
            if item
        }
    except ValueError as exc:
        raise argparse.ArgumentTypeError(
            f"invalid anchor blend candidate list: {value!r}"
        ) from exc
    if not candidates:
        raise argparse.ArgumentTypeError(
            "anchor blend candidate list must be non-empty"
        )
    if any(candidate < 0.0 or candidate > 1.0 for candidate in candidates):
        raise argparse.ArgumentTypeError(
            "anchor blend candidates must lie in [0, 1]"
        )
    return tuple(sorted(candidates))


