def generate_synthetic_general_rows(
    model: Any,
    weights: Any,
    sample_fn: Callable[..., Any],
    n_rows: int,
    *,
    max_length: int,
    max_new_tokens: int,
    batch_size: int,
    retries: int,
    temperature: float,
    seed: int,
) -> list[dict[str, Any]]:
    if n_rows <= 0:
        return []
    rows: list[dict[str, Any]] = []
    seen_instructions: set[str] = set()
    attempts = 0
    max_attempts = min(
        general_instruction_catalog_capacity(),
        max(n_rows, n_rows * max(1, retries)),
    )
    with tqdm(total=n_rows, desc="generate general synthetic responses") as pbar:
        while len(rows) < n_rows and attempts < max_attempts:
            cur_batch = min(batch_size, max_attempts - attempts)
            prompt_rows = make_general_instruction_rows(
                cur_batch,
                seed,
                start_index=attempts,
            )
            attempts += cur_batch
            completions = sample_completions(
                model,
                weights,
                sample_fn,
                [row["instruction"] for row in prompt_rows],
                max_length=max_length,
                max_new_tokens=max_new_tokens,
                temperature=temperature,
                seed=seed + attempts,
                enforce_token_ceiling=True,
                metadata_out=(generation_metadata := []),
            )
            for row, response, metadata in zip(
                prompt_rows,
                completions,
                generation_metadata,
            ):
                response = response.strip()
                if not response or len(response.split()) < 3:
                    continue
                instruction_key = " ".join(
                    row["instruction"].split()
                ).casefold()
                if instruction_key in seen_instructions:
                    continue
                seen_instructions.add(instruction_key)
                out = dict(row)
                out["response"] = response
                out["synthetic_prompt_method"] = "general_self_response"
                out["synthetic_generation_temperature"] = temperature
                out["synthetic_generation_metadata"] = metadata
                rows.append(out)
                pbar.update(1)
                if len(rows) >= n_rows:
                    break
    if len(rows) < n_rows:
        raise ValueError(
            f"generated only {len(rows)}/{n_rows} general synthetic rows; "
            "increase --synthetic_generation_retries or inspect generation outputs"
        )
    return rows


def make_generation_prompt(
    examples: list[dict[str, Any]],
    topic: str,
    *,
    answer_aware: bool = False,
) -> str:
    example_text = ""
    if examples:
        blocks = []
        for i, ex in enumerate(examples, start=1):
            blocks.append(f"Example {i}:\n{ex['question']}")
        example_text = (
            "Use these examples only to learn the prompt format and task style. "
            "Do not copy their facts, topics, wording, or answer choices.\n\n"
            + "\n\n".join(blocks)
            + "\n\n"
        )
    requirements = [
        "- exactly one question",
        "- exactly four answer choices labeled A, B, C, and D",
        "- use a similar prompt format to the examples if examples are provided",
        "- use a different topic and facts from the examples",
    ]
    if answer_aware:
        requirements.extend(
            [
                "- choose a concrete fact or relationship you are confident is true",
                "- make exactly one answer choice correct",
                "- make the other three choices plausible but clearly incorrect",
                "- after option D, write `Correct answer: X` using A, B, C, or D",
                "- then write `Reason:` followed by one concise sentence",
                "- do not include instructions telling the answerer how to reply",
                "- do not include any other text",
            ]
        )
        final_instruction = (
            "Return only the question, four choices, declared answer, and reason."
        )
    else:
        requirements.extend(
            [
                "- include the final instruction asking the answerer to reply with only A, B, C, or D",
                "- do not include the correct answer, explanation, or any text outside the prompt",
            ]
        )
        final_instruction = "Return only the generated prompt."
    return (
        "Create one new multiple-choice evaluation prompt.\n"
        f"{example_text}"
        f"Topic area for the new prompt: {topic}.\n\n"
        "Requirements:\n"
        + "\n".join(requirements)
        + f"\n\n{final_instruction}"
    )


def _strip_generation_envelope(text: str) -> str:
    text = text.replace("\r\n", "\n").replace("\r", "\n").strip()
    if "</think>" in text:
        text = text.split("</think>")[-1].strip()
    text = re.sub(r"^```(?:text)?\s*", "", text)
    return re.sub(r"\s*```$", "", text).strip()


def _strip_inline_response_instruction(value: str) -> str:
    value = re.split(
        r"(?i)\s+(?:please\s+)?(?:reply|respond|answer)\s+with\s+"
        r"(?:only\s+)?A\s*,\s*B\s*,\s*C\s*,?\s*(?:or|and)\s*D\b",
        value,
        maxsplit=1,
    )[0]
    return re.split(
        r"(?i)\s+do\s+not\s+provide\s+(?:any\s+)?explanation\b",
        value,
        maxsplit=1,
    )[0].strip()


def parse_generated_mcq(
    text: str,
    *,
    strip_inline_instructions: bool = False,
) -> str | None:
    text = _strip_generation_envelope(text)
    if not text:
        return None
    text = re.split(
        r"(?im)^\s*(?:answer|correct answer|explanation|solution)\s*[:\-]",
        text,
        maxsplit=1,
    )[0].strip()

    stem_lines: list[str] = []
    options: dict[str, str] = {}
    current_label: str | None = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if re.match(
            r"(?i)^(?:please reply|do not provide|return only|answer with|respond with)",
            line,
        ):
            current_label = None
            continue
        option_match = re.match(r"^([A-D])[\.\):]\s*(.+)$", line)
        if option_match:
            current_label = option_match.group(1)
            options[current_label] = option_match.group(2).strip()
            continue
        if current_label is not None:
            options[current_label] = f"{options[current_label]} {line}".strip()
        elif not options:
            stem_lines.append(line)

    if set(options) != set("ABCD"):
        return None
    stem = "\n".join(stem_lines)
    stem = re.sub(r"(?im)^\s*(?:generated prompt|prompt)\s*:\s*", "", stem).strip()
    stem = re.sub(r"(?im)^\s*options\s*:\s*$", "", stem).strip()
    stem = re.sub(r"(?is)\n?\s*options\s*:\s*$", "", stem).strip()
    stem = re.sub(r"(?i)^question\s*:\s*", "", stem).strip()
    if not stem:
        return None

    cleaned_options = {}
    for label, value in options.items():
        value = re.sub(r"\s+", " ", value).strip()
        cleaned_options[label] = (
            _strip_inline_response_instruction(value)
            if strip_inline_instructions
            else value
        )
    if any(not value for value in cleaned_options.values()):
        return None
    if len(set(cleaned_options.values())) < 4:
        return None

    return (
        f"Question: {stem}\n"
        "Options:\n"
        f"A: {cleaned_options['A']}\n"
        f"B: {cleaned_options['B']}\n"
        f"C: {cleaned_options['C']}\n"
        f"D: {cleaned_options['D']}\n\n"
        "Please reply with only A, B, C, or D. Do not provide any explanation."
    )


def parse_answer_aware_generated_mcq(
    text: str,
) -> tuple[str, str, str] | None:
    text = _strip_generation_envelope(text)
    answer_match = re.search(
        r"(?im)^\s*(?:correct\s+answer|answer)\s*:\s*([A-D])"
        r"\s*[\.\)]?\s*$",
        text,
    )
    if answer_match is None:
        return None
    suffix = text[answer_match.end() :]
    reason_match = re.search(
        r"(?ims)^\s*(?:reason|rationale|explanation)\s*:\s*(.+?)\s*$",
        suffix,
    )
    if reason_match is None:
        return None
    reason = re.sub(r"\s+", " ", reason_match.group(1)).strip()
    if len(reason.split()) < 3:
        return None
    question = parse_generated_mcq(
        text[: answer_match.start()],
        strip_inline_instructions=True,
    )
    if question is None:
        return None
    return question, answer_match.group(1).upper(), reason


def sample_completions(
    model: Any,
    weights: Any,
    sample_fn: Callable[..., Any],
    prompts: list[str],
    *,
    max_length: int,
    max_new_tokens: int,
    temperature: float,
    seed: int,
    enable_thinking: bool = False,
    enforce_token_ceiling: bool = False,
    metadata_out: list[dict[str, Any]] | None = None,
) -> list[str]:
    if not prompts:
        return []
    tokenizer = model.tokenizer
    encoded: list[list[int]] = []
    prompt_token_counts: list[int] = []
    context_overflows: list[bool] = []
    for prompt in prompts:
        chat_prompt = format_prompt(
            tokenizer,
            prompt,
            enable_thinking=enable_thinking,
        )
        ids = tokenizer(chat_prompt, add_special_tokens=False)["input_ids"]
        prompt_token_counts.append(len(ids))
        context_overflow = bool(ids and len(ids) + 1 >= max_length)
        context_overflows.append(context_overflow)
        if not ids or context_overflow:
            encoded.append([])
        else:
            encoded.append(ids[: max_length - 1])
    if not any(encoded):
        if metadata_out is not None:
            metadata_out.extend(
                {
                    "generated_token_count": 0,
                    "truncated": False,
                    "thinking_complete": not enable_thinking,
                    "thinking_token_count": 0,
                    "prompt_token_count": prompt_token_count,
                    "context_overflow": context_overflow,
                }
                for prompt_token_count, context_overflow in zip(
                    prompt_token_counts,
                    context_overflows,
                )
            )
        return [""] * len(prompts)

    seq_len = min(max_length, max(len(ids) for ids in encoded if ids) + max_new_tokens)
    pad_id = tokenizer.pad_token_id
    tokens = np.full((len(prompts), seq_len), pad_id, dtype=np.int32)
    prompt_lens = []
    for i, ids in enumerate(encoded):
        if ids and len(ids) < seq_len:
            tokens[i, : len(ids)] = ids
            prompt_lens.append(len(ids))
        else:
            prompt_lens.append(0)

    sampled = np.asarray(
        sample_fn(
            jax.random.key(seed),
            model,
            jnp.asarray(tokens, dtype=jnp.int32),
            temperature=temperature,
            weights=weights,
        )
    )
    stop_ids = {tokenizer.eos_token_id, tokenizer.pad_token_id}
    outputs = []
    for row, prompt_len, prompt_token_count, context_overflow in zip(
        sampled,
        prompt_lens,
        prompt_token_counts,
        context_overflows,
    ):
        if prompt_len == 0:
            outputs.append("")
            if metadata_out is not None:
                metadata_out.append(
                    {
                        "generated_token_count": 0,
                        "truncated": False,
                        "thinking_complete": not enable_thinking,
                        "thinking_token_count": 0,
                        "prompt_token_count": prompt_token_count,
                        "context_overflow": context_overflow,
                    }
                )
            continue
        generated = row[prompt_len:]
        # Strict ceilings are opt-in so historical nonthinking generation
        # keeps its prior padded-batch behavior.
        gen = (
            generated[:max_new_tokens]
            if enforce_token_ceiling
            else generated
        )
        generation_capacity = len(gen)
        stop = len(gen)
        stopped_on_special = False
        for idx, token_id in enumerate(gen):
            if int(token_id) in stop_ids:
                stop = idx
                stopped_on_special = True
                break
        completion = tokenizer.decode(
            gen[:stop].tolist(),
            skip_special_tokens=True,
        ).strip()
        outputs.append(completion)
        if metadata_out is not None:
            thinking_complete = (
                "</think>" in completion if enable_thinking else True
            )
            thinking_text = (
                completion.split("</think>", 1)[0]
                if enable_thinking and thinking_complete
                else completion
                if enable_thinking
                else ""
            )
            thinking_token_count = (
                len(
                    tokenizer(
                        thinking_text,
                        add_special_tokens=False,
                    )["input_ids"]
                )
                if thinking_text
                else 0
            )
            metadata_out.append(
                {
                    "generated_token_count": int(stop),
                    "truncated": bool(
                        not stopped_on_special
                        and stop >= generation_capacity
                    ),
                    "thinking_complete": bool(thinking_complete),
                    "thinking_token_count": int(thinking_token_count),
                    "prompt_token_count": prompt_token_count,
                    "context_overflow": context_overflow,
                }
            )
    return outputs


def greedy_task_predictions(
    model: Any,
    weights: Any,
    greedy_fn: Callable[..., Any],
    rows: list[dict[str, Any]],
    *,
    max_length: int,
    max_new_tokens: int,
    batch_size: int,
    seed: int,
    desc: str,
) -> list[str]:
    if batch_size <= 0:
        raise ValueError("generation evaluation batch size must be positive")
    predictions: list[str] = []
    progress = tqdm(total=len(rows), desc=desc)
    for start in range(0, len(rows), batch_size):
        chunk = rows[start : start + batch_size]
        prompts = [
            str(row.get("question") or row.get("instruction") or "")
            for row in chunk
        ]
        predictions.extend(
            sample_completions(
                model,
                weights,
                greedy_fn,
                prompts,
                max_length=max_length,
                max_new_tokens=max_new_tokens,
                temperature=1.0,
                seed=seed + start,
                enable_thinking=False,
                enforce_token_ceiling=True,
            )
        )
        progress.update(len(chunk))
    progress.close()
    return predictions


def generate_synthetic_task_rows(
    model: Any,
    weights: Any,
    sample_fn: Callable[..., Any],
    n_rows: int,
    anchor_batches: list[dict[str, Any]],
    *,
    task_type: str,
    candidate_labels: tuple[str, ...],
    n_examples: int,
    max_length: int,
    max_new_tokens: int,
    batch_size: int,
    retries: int,
    temperature: float,
    seed: int,
    icl_strategy: str,
    icl_max_combinations: int,
    examples_out_jsonl: str,
    trace_out_jsonl: str,
    stats_out: dict[str, float],
) -> list[dict[str, Any]]:
    if not anchor_batches:
        raise ValueError("task-aware synthetic ICL requires real anchors")
    if task_type not in {TASK_CATEGORICAL, TASK_GENERATION}:
        raise ValueError(f"unsupported task_type={task_type!r}")
    answer_cues = {
        str(batch.get("answer_cue") or "").strip()
        for batch in anchor_batches
    }
    if len(answer_cues) != 1 or not next(iter(answer_cues)):
        raise ValueError(
            "task-aware synthetic ICL rows need one shared nonempty answer_cue"
        )
    answer_cue = next(iter(answer_cues))
    k = min(n_examples, len(anchor_batches))
    rng = np.random.default_rng(seed)
    combinations: list[tuple[int, ...]] | None = None
    combination_order: list[int] | None = None
    if icl_strategy == "combinations":
        combination_count = math.comb(len(anchor_batches), k)
        if combination_count > icl_max_combinations:
            raise ValueError(
                "task-aware synthetic ICL would enumerate "
                f"{combination_count} demo sets, above "
                f"--synthetic_icl_max_combinations={icl_max_combinations}"
            )
        combinations = list(itertools.combinations(range(len(anchor_batches)), k))
        combination_order = rng.permutation(len(combinations)).tolist()
    elif icl_strategy != "random":
        raise ValueError(f"unknown synthetic ICL strategy: {icl_strategy}")

    Path(examples_out_jsonl).parent.mkdir(parents=True, exist_ok=True)
    with open(examples_out_jsonl, "w", encoding="utf-8") as handle:
        for index, batch in enumerate(anchor_batches):
            write_jsonl_line(
                handle,
                {
                    "synthetic_icl_demo_id": index,
                    "question": batch["question"],
                    "label": batch["label"],
                    "task_type": task_type,
                },
            )

    def demo_indices(attempt_index: int) -> list[int]:
        if combinations is not None and combination_order is not None:
            return list(
                combinations[
                    combination_order[attempt_index % len(combination_order)]
                ]
            )
        return rng.choice(len(anchor_batches), size=k, replace=False).tolist()

    rows: list[dict[str, Any]] = []
    trace_rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    exposure = np.zeros((len(anchor_batches),), dtype=np.int64)
    attempts = 0
    max_attempts = max(n_rows, n_rows * max(1, retries))
    started = time.perf_counter()
    with tqdm(total=n_rows, desc="generate task-aware synthetic prompts") as progress:
        while len(rows) < n_rows and attempts < max_attempts:
            count = min(batch_size, max_attempts - attempts)
            prompts: list[str] = []
            demo_groups: list[list[int]] = []
            for offset in range(count):
                indices = demo_indices(attempts + offset)
                exposure[indices] += 1
                demos = [anchor_batches[index] for index in indices]
                prompts.append(
                    make_task_icl_generation_prompt(
                        demos,
                        answer_cue=answer_cue,
                    )
                )
                demo_groups.append(indices)
            completions = sample_completions(
                model,
                weights,
                sample_fn,
                prompts,
                max_length=max_length,
                max_new_tokens=max_new_tokens,
                temperature=temperature,
                seed=seed + attempts,
                enable_thinking=False,
                enforce_token_ceiling=True,
            )
            attempts += count
            for completion, indices in zip(completions, demo_groups):
                parsed = parse_task_icl_prompt(completion, answer_cue)
                key = re.sub(r"\s+", " ", parsed or "").strip().lower()
                accepted = bool(parsed and key not in seen)
                trace_rows.append(
                    {
                        "attempt_index": len(trace_rows),
                        "synthetic_icl_demo_ids": indices,
                        "raw_completion": completion,
                        "parsed_question": parsed,
                        "accepted": accepted,
                        "rejection_reason": (
                            "" if accepted else "duplicate" if parsed else "parse_failed"
                        ),
                    }
                )
                if not accepted:
                    continue
                seen.add(key)
                rows.append(
                    {
                        "question": parsed,
                        "label": (
                            candidate_labels[0]
                            if task_type == TASK_CATEGORICAL
                            else ""
                        ),
                        "answer": "" if task_type == TASK_GENERATION else None,
                        "task_type": task_type,
                        "candidate_labels": list(candidate_labels),
                        "answer_cue": answer_cue,
                        "dataset": anchor_batches[0].get("dataset", ""),
                        "synthetic_prompt": True,
                        "synthetic_prompt_id": len(rows),
                        "synthetic_prompt_method": "task_anchor_icl_generate",
                        "synthetic_icl_demo_ids": indices,
                        "synthetic_generation_temperature": temperature,
                    }
                )
                progress.update(1)
                if len(rows) >= n_rows:
                    break
    Path(trace_out_jsonl).parent.mkdir(parents=True, exist_ok=True)
    with open(trace_out_jsonl, "w", encoding="utf-8") as handle:
        for row in trace_rows:
            write_jsonl_line(handle, row)
    if len(rows) < n_rows:
        raise ValueError(
            f"generated only {len(rows)}/{n_rows} task-aware synthetic prompts; "
            f"inspect {trace_out_jsonl}"
        )
    stats_out.update(
        {
            "synthetic/generation_seconds": time.perf_counter() - started,
            "synthetic/generation_attempt_count": float(attempts),
            "synthetic/generation_parse_success_count": float(len(rows)),
            "synthetic/generation_parse_success_rate": float(
                len(rows) / max(attempts, 1)
            ),
            "synthetic/anchor_exposure_min": float(exposure.min()),
            "synthetic/anchor_exposure_max": float(exposure.max()),
            "synthetic/anchor_exposure_std": float(exposure.std()),
        }
    )
    return rows


def make_synthetic_task_reference_batches(
    rows: list[dict[str, Any]],
    tokenizer: Any,
    weights: Any,
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    candidate_labels: tuple[str, ...],
    model: Any,
    greedy_fn: Callable[..., Any],
    max_length: int,
    *,
    task_type: str,
    generation_eval_max_length: int,
    generation_eval_max_new_tokens: int,
    generation_eval_batch_size: int,
    seed: int,
    out_jsonl: str,
    stats_out: dict[str, float],
) -> list[dict[str, Any]]:
    predictions: list[str]
    confidences: list[float] = []
    if task_type == TASK_GENERATION:
        predictions = greedy_task_predictions(
            model,
            weights,
            greedy_fn,
            rows,
            max_length=generation_eval_max_length,
            max_new_tokens=generation_eval_max_new_tokens,
            batch_size=generation_eval_batch_size,
            seed=seed,
            desc="pseudo-label synthetic generation prompts",
        )
    else:
        predictions = []
        for row in tqdm(rows, desc="pseudo-label synthetic categorical prompts"):
            prompt_batch = tokenize_prompt(tokenizer, row["question"], max_length)
            if prompt_batch is None:
                predictions.append("")
                confidences.append(0.0)
                continue
            candidate_logits = np.asarray(
                predict_logits_fn(weights, prompt_batch),
                dtype=np.float32,
            )[cand_ids]
            probabilities = stable_softmax(candidate_logits)
            index = int(np.argmax(candidate_logits))
            predictions.append(candidate_labels[index])
            confidences.append(float(probabilities[index]))

    batches: list[dict[str, Any]] = []
    Path(out_jsonl).parent.mkdir(parents=True, exist_ok=True)
    with open(out_jsonl, "w", encoding="utf-8") as handle:
        for row, prediction in zip(rows, predictions):
            prediction = str(prediction).strip()
            if not prediction:
                continue
            labeled = dict(row)
            labeled["label"] = prediction
            if task_type == TASK_GENERATION:
                labeled["answer"] = prediction
            batch = tokenize_task_row(
                tokenizer,
                labeled,
                max_length,
                task_type,
            )
            if batch is None:
                continue
            batches.append(batch)
            write_jsonl_line(handle, labeled)
    stats_out["synthetic/probe_count"] = float(len(batches))
    stats_out["synthetic/effective_weight_sum"] = float(len(batches))
    if confidences:
        stats_out["synthetic/teacher_conf_mean"] = float(np.mean(confidences))
    print("========== Task Synthetic Reference Summary ==========")
    print(f"Source rows    : {len(rows)}")
    print(f"Kept           : {len(batches)}")
    print(f"Skipped        : {len(rows) - len(batches)}")
    return batches


def generate_synthetic_mcq_rows(
    model: Any,
    weights: Any,
    sample_fn: Callable[..., Any],
    n_rows: int,
    correct_batches: list[dict[str, Any]],
    *,
    use_icl: bool,
    n_examples: int,
    max_length: int,
    max_new_tokens: int,
    batch_size: int,
    retries: int,
    temperature: float,
    seed: int,
    icl_examples_out_jsonl: str | None = None,
    icl_source: str = "correct",
    resample_icl: bool = False,
    icl_strategy: str = "random",
    icl_max_combinations: int = 200000,
    anchor_schedule: str = "random",
    diversity: str = "none",
    icl_embeddings: np.ndarray | None = None,
    stats_out: dict[str, float] | None = None,
    enable_thinking: bool = False,
    answer_aware: bool = False,
    trace_out_jsonl: str | None = None,
) -> list[dict[str, Any]]:
    if n_rows <= 0:
        return []
    if use_icl and not correct_batches:
        raise ValueError("cnl_synth_icl requires at least one mastered/correct example")
    if max_new_tokens <= 0:
        raise ValueError("--synthetic_generation_max_new_tokens must be positive")
    if max_length <= max_new_tokens + 1:
        raise ValueError("--synthetic_generation_max_length must be larger than max_new_tokens")
    if batch_size <= 0:
        raise ValueError("--synthetic_generation_batch_size must be positive")
    if icl_strategy not in ("random", "combinations"):
        raise ValueError("synthetic_icl_strategy must be 'random' or 'combinations'")
    if anchor_schedule not in ("random", "balanced"):
        raise ValueError("synthetic_icl_anchor_schedule must be 'random' or 'balanced'")
    if diversity not in ("none", "embedding_farthest"):
        raise ValueError("synthetic_icl_diversity must be 'none' or 'embedding_farthest'")
    if use_icl and diversity == "embedding_farthest":
        if icl_embeddings is None or len(icl_embeddings) != len(correct_batches):
            raise ValueError("embedding_farthest requires one embedding per ICL source example")

    rng = np.random.default_rng(seed)
    examples: list[dict[str, Any]] = []
    example_indices: list[int] = []
    combination_indices: list[tuple[int, ...]] | None = None
    combination_order: list[int] | None = None
    combination_cursor = 0
    anchor_exposure = np.zeros((len(correct_batches),), dtype=np.int64)
    used_combinations: set[tuple[int, ...]] = set()
    if use_icl:
        k = min(n_examples, len(correct_batches))
        if diversity == "embedding_farthest":
            assert icl_embeddings is not None
            example_indices = choose_farthest_indices(
                list(range(len(correct_batches))), k, rng, icl_embeddings
            )
        else:
            example_indices = rng.choice(len(correct_batches), size=k, replace=False).tolist()
        examples = [correct_batches[i] for i in example_indices]
        if (
            resample_icl
            and anchor_schedule == "random"
            and diversity == "none"
            and icl_strategy == "combinations"
            and k > 0
        ):
            combination_total = math.comb(len(correct_batches), k)
            if combination_total > icl_max_combinations:
                raise ValueError(
                    "synthetic_icl_strategy=combinations would enumerate "
                    f"{combination_total} demo sets, above "
                    f"--synthetic_icl_max_combinations={icl_max_combinations}."
                )
            combination_indices = list(itertools.combinations(range(len(correct_batches)), k))
            combination_order = rng.permutation(len(combination_indices)).tolist()
        if icl_examples_out_jsonl is not None:
            os.makedirs(os.path.dirname(icl_examples_out_jsonl) or ".", exist_ok=True)
            with open(icl_examples_out_jsonl, "w", encoding="utf-8") as f:
                source_examples = correct_batches if resample_icl else examples
                for demo_id, ex in enumerate(source_examples):
                    write_jsonl_line(
                        f,
                        {
                            "synthetic_icl_demo_id": demo_id,
                            "synthetic_icl_source": icl_source,
                            "question": ex["question"],
                            "label": ex["label"],
                        },
                    )

    def choose_examples() -> tuple[list[dict[str, Any]], list[int], int | None]:
        nonlocal combination_cursor
        if not use_icl:
            return [], [], None
        k = min(n_examples, len(correct_batches))
        if anchor_schedule == "balanced" or diversity == "embedding_farthest":
            indices = choose_balanced_demo_indices(
                anchor_exposure,
                k,
                rng,
                embeddings=icl_embeddings if diversity == "embedding_farthest" else None,
                used_combinations=used_combinations,
            )
            return [correct_batches[i] for i in indices], indices, None
        if resample_icl:
            if combination_indices is not None and combination_order is not None:
                combo_position = combination_cursor % len(combination_order)
                combo_index = combination_order[combo_position]
                indices = list(combination_indices[combo_index])
                combination_cursor += 1
                anchor_exposure[indices] += 1
                return [correct_batches[i] for i in indices], indices, combo_index
            if diversity == "embedding_farthest":
                assert icl_embeddings is not None
                indices = choose_farthest_indices(
                    list(range(len(correct_batches))), k, rng, icl_embeddings
                )
            else:
                indices = rng.choice(len(correct_batches), size=k, replace=False).tolist()
            anchor_exposure[indices] += 1
            return [correct_batches[i] for i in indices], indices, None
        anchor_exposure[example_indices] += 1
        return examples, example_indices, None

    topic_order = rng.permutation(len(SYNTHETIC_TOPICS)).tolist()
    rows: list[dict[str, Any]] = []
    seen_questions: set[str] = set()
    trace_rows: list[dict[str, Any]] = []
    generation_started = time.perf_counter()
    parsed_count = 0
    declared_answer_parse_count = 0
    duplicate_count = 0
    context_overflow_count = 0
    incomplete_thinking_count = 0
    truncated_count = 0
    generated_token_counts: list[int] = []
    thinking_token_counts: list[int] = []
    max_attempts = max(n_rows, n_rows * max(1, retries))
    attempts = 0
    with tqdm(total=n_rows, desc="generate synthetic prompts") as pbar:
        while len(rows) < n_rows and attempts < max_attempts:
            cur_batch = min(batch_size, max_attempts - attempts)
            prompts = []
            topics = []
            prompt_demo_ids: list[list[int]] = []
            prompt_combo_indices: list[int | None] = []
            for _ in range(cur_batch):
                if attempts > 0 and attempts % len(topic_order) == 0:
                    topic_order = rng.permutation(len(SYNTHETIC_TOPICS)).tolist()
                topic_idx = topic_order[attempts % len(topic_order)]
                topic = SYNTHETIC_TOPICS[topic_idx]
                prompt_examples, demo_ids, combo_index = choose_examples()
                topics.append(topic)
                prompt_demo_ids.append(demo_ids)
                prompt_combo_indices.append(combo_index)
                prompts.append(
                    make_generation_prompt(
                        prompt_examples,
                        topic,
                        answer_aware=answer_aware,
                    )
                )
                attempts += 1

            completion_metadata: list[dict[str, Any]] = []
            completions = sample_completions(
                model,
                weights,
                sample_fn,
                prompts,
                max_length=max_length,
                max_new_tokens=max_new_tokens,
                temperature=temperature,
                seed=seed + attempts,
                enable_thinking=enable_thinking,
                enforce_token_ceiling=enable_thinking,
                metadata_out=completion_metadata,
            )
            for completion, completion_meta, topic, demo_ids, combo_index in zip(
                completions,
                completion_metadata,
                topics,
                prompt_demo_ids,
                prompt_combo_indices,
            ):
                generated_token_counts.append(
                    int(completion_meta["generated_token_count"])
                )
                thinking_token_counts.append(
                    int(completion_meta["thinking_token_count"])
                )
                context_overflow = bool(
                    completion_meta.get("context_overflow", False)
                )
                context_overflow_count += int(context_overflow)
                truncated_count += int(bool(completion_meta["truncated"]))
                thinking_complete = bool(completion_meta["thinking_complete"])
                declared_answer: str | None = None
                declared_reason: str | None = None
                if enable_thinking and not thinking_complete:
                    incomplete_thinking_count += 1
                    parsed = None
                elif answer_aware:
                    answer_aware_result = (
                        parse_answer_aware_generated_mcq(completion)
                    )
                    if answer_aware_result is None:
                        parsed = None
                    else:
                        parsed, declared_answer, declared_reason = (
                            answer_aware_result
                        )
                        declared_answer_parse_count += 1
                else:
                    parsed = parse_generated_mcq(completion)
                parsed_count += int(parsed is not None)
                trace_row = (
                    {
                        "attempt_index": len(trace_rows),
                        "topic": topic,
                        "synthetic_icl_demo_ids": demo_ids,
                        "synthetic_icl_combination_index": combo_index,
                        "enable_thinking": bool(enable_thinking),
                        "answer_aware": bool(answer_aware),
                        "raw_completion": completion,
                        "parsed_question": parsed,
                        "declared_answer": declared_answer,
                        "declared_reason": declared_reason,
                        **completion_meta,
                    }
                    if trace_out_jsonl is not None
                    else None
                )
                if parsed is None:
                    if trace_row is not None:
                        trace_row["accepted"] = False
                        trace_row["rejection_reason"] = (
                            "context_overflow"
                            if context_overflow
                            else "incomplete_thinking"
                            if enable_thinking and not thinking_complete
                            else "answer_aware_parse_failed"
                            if answer_aware
                            else "parse_failed"
                        )
                        trace_rows.append(trace_row)
                    continue
                key = re.sub(r"\s+", " ", parsed).strip().lower()
                if key in seen_questions:
                    duplicate_count += 1
                    if trace_row is not None:
                        trace_row["accepted"] = False
                        trace_row["rejection_reason"] = "duplicate"
                        trace_rows.append(trace_row)
                    continue
                seen_questions.add(key)
                if trace_row is not None:
                    trace_row["accepted"] = True
                    trace_row["rejection_reason"] = ""
                    trace_rows.append(trace_row)
                generated_row = {
                    "question": parsed,
                    "label": declared_answer or "A",
                    "synthetic_prompt": True,
                    "synthetic_prompt_id": len(rows),
                    "synthetic_prompt_method": (
                        f"{icl_source}_icl_generate"
                        if use_icl and icl_source != "correct"
                        else ("icl_generate" if use_icl else "generate")
                    ),
                    "synthetic_topic": topic,
                    "synthetic_generation_temperature": temperature,
                    "synthetic_icl_examples": min(
                        n_examples,
                        len(correct_batches),
                    )
                    if use_icl
                    else 0,
                    "synthetic_icl_demo_ids": demo_ids,
                    "synthetic_icl_combination_index": combo_index,
                    "synthetic_icl_resampled": (
                        bool(resample_icl) if use_icl else False
                    ),
                }
                if answer_aware:
                    generated_row.update(
                        {
                            "synthetic_generation_answer_aware": True,
                            "synthetic_declared_answer": declared_answer,
                            "synthetic_declared_reason": declared_reason,
                        }
                    )
                if enable_thinking or answer_aware:
                    generated_row.update(
                        {
                            "synthetic_generation_enable_thinking": bool(
                                enable_thinking
                            ),
                            "synthetic_generation_token_count": int(
                                completion_meta[
                                    "generated_token_count"
                                ]
                            ),
                            "synthetic_generation_truncated": bool(
                                completion_meta["truncated"]
                            ),
                            "synthetic_thinking_token_count": int(
                                completion_meta[
                                    "thinking_token_count"
                                ]
                            ),
                            "synthetic_raw_generation": completion,
                        }
                    )
                rows.append(generated_row)
                pbar.update(1)
                if len(rows) >= n_rows:
                    break

    if len(rows) < n_rows:
        if trace_out_jsonl is not None:
            trace_path = Path(trace_out_jsonl)
            trace_path.parent.mkdir(parents=True, exist_ok=True)
            with open(trace_path, "w", encoding="utf-8") as trace_file:
                for trace_row in trace_rows:
                    write_jsonl_line(trace_file, trace_row)
        overflow_detail = (
            f"; {context_overflow_count}/{attempts} prompts exceeded "
            f"--synthetic_generation_max_length={max_length}. Increase the "
            "generation-only context length or shorten the ICL demonstrations"
            if context_overflow_count
            else ""
        )
        raise ValueError(
            f"generated only {len(rows)}/{n_rows} synthetic MCQ prompts"
            f"{overflow_detail}; inspect the synthetic generation trace"
        )
    generation_seconds = time.perf_counter() - generation_started
    if trace_out_jsonl is not None:
        trace_path = Path(trace_out_jsonl)
        trace_path.parent.mkdir(parents=True, exist_ok=True)
        with open(trace_path, "w", encoding="utf-8") as trace_file:
            for trace_row in trace_rows:
                write_jsonl_line(trace_file, trace_row)
    if stats_out is not None:
        stats_out.update(
            {
                "synthetic/generation_seconds": float(generation_seconds),
                "synthetic/generation_attempt_count": float(attempts),
                "synthetic/generation_parse_success_count": float(parsed_count),
                "synthetic/generation_parse_success_rate": float(
                    parsed_count / max(attempts, 1)
                ),
                "synthetic/generation_answer_aware": float(answer_aware),
                "synthetic/generation_declared_answer_parse_count": float(
                    declared_answer_parse_count
                ),
                "synthetic/generation_declared_answer_parse_rate": float(
                    declared_answer_parse_count / max(attempts, 1)
                    if answer_aware
                    else 0.0
                ),
                "synthetic/generation_duplicate_count": float(duplicate_count),
                "synthetic/generation_context_overflow_count": float(
                    context_overflow_count
                ),
                "synthetic/generation_context_overflow_rate": float(
                    context_overflow_count / max(attempts, 1)
                ),
                "synthetic/generation_truncated_count": float(truncated_count),
                "synthetic/generation_truncated_rate": float(
                    truncated_count / max(attempts, 1)
                ),
                "synthetic/generation_incomplete_thinking_count": float(
                    incomplete_thinking_count
                ),
                "synthetic/generation_token_count_mean": float(
                    np.mean(generated_token_counts)
                    if generated_token_counts
                    else 0.0
                ),
                "synthetic/thinking_token_count_mean": float(
                    np.mean(thinking_token_counts)
                    if thinking_token_counts
                    else 0.0
                ),
                "synthetic/generation_enable_thinking": float(
                    enable_thinking
                ),
            }
        )
        if anchor_exposure.size:
            stats_out.update(
                {
                "synthetic/anchor_exposure_min": float(anchor_exposure.min()),
                "synthetic/anchor_exposure_max": float(anchor_exposure.max()),
                "synthetic/anchor_exposure_std": float(anchor_exposure.std()),
                }
            )
    return rows


def make_synthetic_correct_batches(
    rows: list[dict[str, Any]],
    tokenizer: Any,
    weights: Any,
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    max_length: int,
    *,
    label_mode: str,
    temperature: float,
    min_confidence: float,
    seed: int,
    out_jsonl: str,
    choice_permutation_check: bool = False,
    choice_permutation_count: int = 3,
    choice_consistency_mode: str = "filter",
    reliability_mode: str = "none",
    confidence_min: float = 0.50,
    confidence_power: float = 1.0,
    stats_out: dict[str, float] | None = None,
    audit_out_jsonl: str | None = None,
) -> list[dict[str, Any]]:
    if temperature <= 0:
        raise ValueError("--synthetic_temperature must be positive")
    if choice_permutation_count < 1:
        raise ValueError("--synthetic_choice_permutation_count must be positive")
    if choice_consistency_mode not in ("filter", "weight"):
        raise ValueError("synthetic choice consistency mode must be filter or weight")
    if reliability_mode not in ("none", "confidence_filter", "confidence_weight"):
        raise ValueError("unknown synthetic reliability mode")
    if not 0 <= confidence_min < 1:
        raise ValueError("--synthetic_confidence_min must be in [0, 1)")
    if confidence_power < 0:
        raise ValueError("--synthetic_confidence_power must be nonnegative")
    os.makedirs(os.path.dirname(out_jsonl) or ".", exist_ok=True)
    if audit_out_jsonl is not None:
        os.makedirs(os.path.dirname(audit_out_jsonl) or ".", exist_ok=True)
    rng = np.random.default_rng(seed)
    batches = []
    skipped = 0
    low_conf = 0
    inconsistent = 0
    declared_answer_count = 0
    declared_answer_match_count = 0
    declared_answer_mismatch_count = 0
    confidences = []
    margins = []
    consistency_rates = []
    effective_weight_sum = 0.0
    with ExitStack() as stack:
        f = stack.enter_context(open(out_jsonl, "w", encoding="utf-8"))
        audit_file = (
            stack.enter_context(
                open(audit_out_jsonl, "w", encoding="utf-8")
            )
            if audit_out_jsonl is not None
            else None
        )
        for row in tqdm(rows, desc="make synthetic correct"):
            audit_row = dict(row) if audit_file is not None else None
            question = row.get("question")
            if not question:
                skipped += 1
                if audit_row is not None:
                    audit_row.update(
                        {
                            "synthetic_policy_accepted": False,
                            "synthetic_policy_rejection_reason": (
                                "missing_question"
                            ),
                        }
                    )
                    write_jsonl_line(audit_file, audit_row)
                continue
            prompt_batch = tokenize_prompt(tokenizer, question, max_length)
            if prompt_batch is None:
                skipped += 1
                if audit_row is not None:
                    audit_row.update(
                        {
                            "synthetic_policy_accepted": False,
                            "synthetic_policy_rejection_reason": (
                                "tokenization_failed"
                            ),
                        }
                    )
                    write_jsonl_line(audit_file, audit_row)
                continue
            logits = np.asarray(predict_logits_fn(weights, prompt_batch))[cand_ids]
            probs = stable_softmax(logits / temperature)
            policy_idx = int(np.argmax(probs))
            policy_answer = "ABCD"[policy_idx]
            policy_confidence = float(probs[policy_idx])
            if audit_row is not None:
                audit_row.update(
                    {
                        "synthetic_ordinary_policy_answer": policy_answer,
                        "synthetic_ordinary_policy_confidence": (
                            policy_confidence
                        ),
                    }
                )
            declared_answer = row.get("synthetic_declared_answer")
            if declared_answer is not None:
                declared_answer_count += 1
                declared_answer = str(declared_answer).strip().upper()
                if declared_answer not in "ABCD":
                    declared_answer_mismatch_count += 1
                    if audit_row is not None:
                        audit_row.update(
                            {
                                "synthetic_declared_answer_agrees": False,
                                "synthetic_policy_accepted": False,
                                "synthetic_policy_rejection_reason": (
                                    "invalid_declared_answer"
                                ),
                            }
                        )
                        write_jsonl_line(audit_file, audit_row)
                    continue
                declared_idx = "ABCD".index(declared_answer)
                if policy_idx != declared_idx:
                    declared_answer_mismatch_count += 1
                    if audit_row is not None:
                        audit_row.update(
                            {
                                "synthetic_declared_answer_agrees": False,
                                "synthetic_policy_accepted": False,
                                "synthetic_policy_rejection_reason": (
                                    "declared_answer_mismatch"
                                ),
                            }
                        )
                        write_jsonl_line(audit_file, audit_row)
                    continue
                declared_answer_match_count += 1
                if audit_row is not None:
                    audit_row["synthetic_declared_answer_agrees"] = True
                idx = declared_idx
            elif label_mode == "sample":
                idx = int(rng.choice(np.arange(4), p=probs))
            else:
                idx = policy_idx
            confidence = float(probs[idx])
            sorted_probs = np.sort(probs)
            margin = float(sorted_probs[-1] - sorted_probs[-2])
            confidence_floor = max(
                min_confidence,
                confidence_min if reliability_mode == "confidence_filter" else 0.0,
            )
            if confidence < confidence_floor:
                low_conf += 1
                if audit_row is not None:
                    audit_row.update(
                        {
                            "synthetic_selected_answer": "ABCD"[idx],
                            "synthetic_selected_confidence": confidence,
                            "synthetic_confidence_floor": confidence_floor,
                            "synthetic_policy_accepted": False,
                            "synthetic_policy_rejection_reason": (
                                "low_confidence"
                            ),
                        }
                    )
                    write_jsonl_line(audit_file, audit_row)
                continue
            consistency_rate = 1.0
            if choice_permutation_check and choice_permutation_count > 1:
                consistent = 1
                for _ in range(choice_permutation_count - 1):
                    permutation = rng.permutation(4)
                    permuted = permute_mcq_choices(question, permutation)
                    if permuted is None:
                        consistent = 0
                        break
                    permuted_question, semantic_map = permuted
                    permuted_batch = tokenize_prompt(tokenizer, permuted_question, max_length)
                    if permuted_batch is None:
                        continue
                    permuted_logits = np.asarray(predict_logits_fn(weights, permuted_batch))[cand_ids]
                    permuted_idx = int(np.argmax(permuted_logits))
                    consistent += int(int(semantic_map[permuted_idx]) == idx)
                consistency_rate = consistent / float(choice_permutation_count)
                consistency_rates.append(consistency_rate)
                if choice_consistency_mode == "filter" and consistency_rate < 1.0:
                    inconsistent += 1
                    if audit_row is not None:
                        audit_row.update(
                            {
                                "synthetic_selected_answer": "ABCD"[idx],
                                "synthetic_selected_confidence": confidence,
                                "synthetic_choice_consistency": (
                                    consistency_rate
                                ),
                                "synthetic_policy_accepted": False,
                                "synthetic_policy_rejection_reason": (
                                    "choice_inconsistent"
                                ),
                            }
                        )
                        write_jsonl_line(audit_file, audit_row)
                    continue
            else:
                consistency_rates.append(consistency_rate)

            reliability_weight = 1.0
            if reliability_mode == "confidence_weight":
                reliability_weight = max(
                    0.0,
                    min(1.0, (confidence - confidence_min) / max(1.0 - confidence_min, 1e-12)),
                ) ** confidence_power
            consistency_weight = (
                consistency_rate if choice_permutation_check and choice_consistency_mode == "weight" else 1.0
            )
            reference_weight = reliability_weight * consistency_weight
            if reference_weight <= 0:
                low_conf += 1
                if audit_row is not None:
                    audit_row.update(
                        {
                            "synthetic_selected_answer": "ABCD"[idx],
                            "synthetic_selected_confidence": confidence,
                            "synthetic_policy_accepted": False,
                            "synthetic_policy_rejection_reason": (
                                "zero_reference_weight"
                            ),
                        }
                    )
                    write_jsonl_line(audit_file, audit_row)
                continue
            label = "ABCD"[idx]
            synthetic_row = {
                "label": label,
                "question": question,
                "predict_label": label,
                "synthetic": True,
                "synthetic_method": "qwen3_on_policy_pseudo_label",
                "synthetic_label_mode": label_mode,
                "synthetic_confidence": confidence,
                "synthetic_teacher_margin": margin,
                "synthetic_ordinary_policy_answer": policy_answer,
                "synthetic_ordinary_policy_confidence": policy_confidence,
                "synthetic_choice_consistency": consistency_rate,
                "reference_weight": reference_weight,
                "source_label": row.get("label"),
                "source_predict_label": row.get("predict_label"),
            }
            if declared_answer is not None:
                synthetic_row["synthetic_declared_answer_agrees"] = True
            for meta_key in (
                "synthetic_prompt_id",
                "synthetic_prompt_method",
                "synthetic_topic",
                "synthetic_generation_temperature",
                "synthetic_generation_enable_thinking",
                "synthetic_generation_token_count",
                "synthetic_generation_truncated",
                "synthetic_thinking_token_count",
                "synthetic_raw_generation",
                "synthetic_icl_examples",
                "synthetic_icl_demo_ids",
                "synthetic_icl_combination_index",
                "synthetic_icl_resampled",
                "synthetic_generation_answer_aware",
                "synthetic_declared_answer",
                "synthetic_declared_reason",
            ):
                if meta_key in row:
                    synthetic_row[meta_key] = row[meta_key]
            batch = tokenize_row(tokenizer, synthetic_row, max_length)
            if batch is None:
                skipped += 1
                if audit_row is not None:
                    audit_row.update(
                        {
                            "synthetic_selected_answer": label,
                            "synthetic_selected_confidence": confidence,
                            "synthetic_policy_accepted": False,
                            "synthetic_policy_rejection_reason": (
                                "reference_tokenization_failed"
                            ),
                        }
                    )
                    write_jsonl_line(audit_file, audit_row)
                continue
            batches.append(batch)
            write_jsonl_line(f, synthetic_row)
            if audit_row is not None:
                audit_row.update(
                    {
                        "synthetic_selected_answer": label,
                        "synthetic_selected_confidence": confidence,
                        "synthetic_confidence_floor": confidence_floor,
                        "synthetic_choice_consistency": consistency_rate,
                        "synthetic_reference_weight": reference_weight,
                        "synthetic_policy_accepted": True,
                        "synthetic_policy_rejection_reason": "",
                    }
                )
                write_jsonl_line(audit_file, audit_row)
            confidences.append(confidence)
            margins.append(margin)
            effective_weight_sum += reference_weight

    print("========== Synthetic Correct Summary ==========")
    print(f"Source rows    : {len(rows)}")
    print(f"Kept           : {len(batches)}")
    print(f"Skipped        : {skipped}")
    print(f"Low confidence : {low_conf}")
    print(f"Inconsistent   : {inconsistent}")
    if declared_answer_count:
        print(
            "Declared match : "
            f"{declared_answer_match_count}/{declared_answer_count}"
        )
    if stats_out is not None:
        stats_out.update(
            {
                "synthetic/probe_count": float(len(batches)),
                "synthetic/teacher_conf_mean": float(np.mean(confidences)) if confidences else 0.0,
                "synthetic/teacher_margin_mean": float(np.mean(margins)) if margins else 0.0,
                "synthetic/choice_consistency_rate": (
                    float(np.mean(consistency_rates)) if consistency_rates else 0.0
                ),
                "synthetic/effective_weight_sum": float(effective_weight_sum),
                "synthetic/skipped_count": float(skipped),
                "synthetic/low_confidence_count": float(low_conf),
                "synthetic/inconsistent_count": float(inconsistent),
                "synthetic/declared_answer_count": float(
                    declared_answer_count
                ),
                "synthetic/declared_answer_match_count": float(
                    declared_answer_match_count
                ),
                "synthetic/declared_answer_mismatch_count": float(
                    declared_answer_mismatch_count
                ),
                "synthetic/declared_answer_agreement_rate": float(
                    declared_answer_match_count
                    / max(declared_answer_count, 1)
                    if declared_answer_count
                    else 0.0
                ),
                "synthetic/answer_aware_retention_rate": float(
                    len(batches) / max(declared_answer_count, 1)
                    if declared_answer_count
                    else 0.0
                ),
            }
        )
    return batches


def make_synthetic_general_batches(
    rows: list[dict[str, Any]],
    tokenizer: Any,
    max_length: int,
    *,
    out_jsonl: str,
) -> list[dict[str, Any]]:
    os.makedirs(os.path.dirname(out_jsonl) or ".", exist_ok=True)
    batches = []
    skipped = 0
    with open(out_jsonl, "w", encoding="utf-8") as f:
        for row in tqdm(rows, desc="make general synthetic reference"):
            batch = tokenize_lm_row(tokenizer, row, max_length)
            if batch is None:
                skipped += 1
                continue
            batches.append(batch)
            write_jsonl_line(
                f,
                {
                    "instruction": row["instruction"],
                    "response": row["response"],
                    "synthetic": True,
                    "synthetic_method": "qwen3_general_self_response",
                    "synthetic_prompt_id": row.get("synthetic_prompt_id"),
                    "synthetic_prompt_method": row.get("synthetic_prompt_method"),
                    "synthetic_topic": row.get("synthetic_topic"),
                    "synthetic_task_family": row.get("synthetic_task_family"),
                    "synthetic_prompt_framing": row.get(
                        "synthetic_prompt_framing"
                    ),
                    "synthetic_prompt_catalog_index": row.get(
                        "synthetic_prompt_catalog_index"
                    ),
                    "synthetic_generation_temperature": row.get("synthetic_generation_temperature"),
                    "synthetic_generation_metadata": row.get(
                        "synthetic_generation_metadata"
                    ),
                },
            )

    print("========== General Synthetic Reference Summary ==========")
    print(f"Source rows    : {len(rows)}")
    print(f"Kept           : {len(batches)}")
    print(f"Skipped        : {skipped}")
    return batches


def split_rows(
    rows: list[dict[str, Any]],
    tokenizer: Any,
    weights: Any,
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    max_length: int,
    out_correct: str,
    out_wrong: str,
    *,
    task_type: str = TASK_CATEGORICAL,
    candidate_labels: tuple[str, ...] = ("A", "B", "C", "D"),
    model: Any | None = None,
    greedy_fn: Callable[..., Any] | None = None,
    generation_eval_max_length: int = 512,
    generation_eval_max_new_tokens: int = 32,
    generation_eval_batch_size: int = 8,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    os.makedirs(os.path.dirname(out_correct) or ".", exist_ok=True)
    os.makedirs(os.path.dirname(out_wrong) or ".", exist_ok=True)
    partial_correct = f"{out_correct}.partial"
    partial_wrong = f"{out_wrong}.partial"
    correct_batches = []
    wrong_batches = []
    skipped = 0
    prepared: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for row in tqdm(rows, desc="tokenize split rows"):
        batch = tokenize_task_row(tokenizer, row, max_length, task_type)
        if batch is None:
            skipped += 1
            continue
        prepared.append((row, batch))
    if task_type == TASK_GENERATION:
        if model is None or greedy_fn is None:
            raise ValueError("generation splitting requires model and greedy_fn")
        predictions = greedy_task_predictions(
            model,
            weights,
            greedy_fn,
            [batch for _, batch in prepared],
            max_length=generation_eval_max_length,
            max_new_tokens=generation_eval_max_new_tokens,
            batch_size=generation_eval_batch_size,
            seed=0,
            desc="split generation",
        )
    else:
        predictions = [
            predict_candidate_label(
                predict_logits_fn,
                weights,
                batch,
                cand_ids,
                candidate_labels,
            )
            for _, batch in tqdm(prepared, desc="split categorical")
        ]
    with open(partial_correct, "w", encoding="utf-8") as fc, open(
        partial_wrong,
        "w",
        encoding="utf-8",
    ) as fw:
        for (row, batch), pred in zip(prepared, predictions):
            target = str(row["label"])
            is_correct = (
                exact_answer_match(pred, target)
                if task_type == TASK_GENERATION
                else pred == target
            )
            out = {
                key: value
                for key, value in row.items()
                if key not in {"predict_label", "prediction"}
            }
            out.update(
                {
                    "task_type": task_type,
                    "label": target,
                    "question": row["question"],
                    "predict_label": pred,
                }
            )
            if task_type == TASK_CATEGORICAL:
                out["candidate_labels"] = list(candidate_labels)
            else:
                out["answer"] = target
            if is_correct:
                correct_batches.append(batch)
                write_jsonl_line(fc, out)
            else:
                wrong_batches.append(batch)
                write_jsonl_line(fw, out)
    os.replace(partial_correct, out_correct)
    os.replace(partial_wrong, out_wrong)
    print("========== Split Summary ==========")
    print(f"Total   : {len(rows)}")
    print(f"Correct : {len(correct_batches)}")
    print(f"Wrong   : {len(wrong_batches)}")
    print(f"Skipped : {skipped}")
    return correct_batches, wrong_batches


def layer_group_squared_norm(
    tree: Any,
    layer_group_ids: Any,
    group_count: int,
) -> jax.Array:
    """Return one float32 squared L2 norm per parameter-layer group."""
    if group_count <= 0:
        raise ValueError("layer squared norms require at least one group")
    if jax.tree_util.tree_structure(tree) != jax.tree_util.tree_structure(
        layer_group_ids
    ):
        raise ValueError("layer group ids must match the gradient tree")
    totals = jnp.zeros((group_count,), dtype=jnp.float32)
    for leaf, group_id in zip(
        jax.tree_util.tree_leaves(tree),
        jax.tree_util.tree_leaves(layer_group_ids),
        strict=True,
    ):
        group_index = int(group_id)
        if not 0 <= group_index < group_count:
            raise ValueError("layer group id is outside the group range")
        totals = totals.at[group_index].add(
            jnp.sum(jnp.square(jnp.asarray(leaf, dtype=jnp.float32)))
        )
    return totals


def mean_grad_and_loss_correct(
    weights: Any,
    correct_batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    *,
    desc: str = "correct mean-grad",
    batch_size: int = 1,
) -> tuple[Any, float]:
    if not correct_batches:
        raise ValueError("correct set is empty")
    if batch_size <= 0:
        raise ValueError("reference batch size must be positive")
    total_grad = None
    total_loss = 0.0
    total_weight = 0.0
    progress = tqdm(total=len(correct_batches), desc=desc)
    for start in range(0, len(correct_batches), batch_size):
        batches = correct_batches[start : start + batch_size]
        weights_for_batch = [float(batch.get("reference_weight", 1.0)) for batch in batches]
        if any(weight < 0 for weight in weights_for_batch):
            raise ValueError("reference weights must be nonnegative")
        batch_weight = sum(weights_for_batch)
        if batch_weight > 0:
            packed_batch = (
                array_batch(batches[0])
                if batch_size == 1
                else stack_reference_batches(batches)
            )
            loss, grad = loss_grad_fn(weights, packed_batch)
            weighted_grad = scale_tree(grad, batch_weight)
            total_grad = (
                weighted_grad
                if total_grad is None
                else add_trees(total_grad, weighted_grad)
            )
            total_loss += batch_weight * float(loss)
            total_weight += batch_weight
        progress.update(len(batches))
    progress.close()
    if total_grad is None or total_weight <= 0:
        raise RuntimeError("reference gradient accumulation produced no positive weight")
    return divide_tree(total_grad, total_weight), total_loss / total_weight


def mean_grad_and_layer_variance_correct(
    weights: Any,
    correct_batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    layer_squared_norm_fn: Any,
    *,
    desc: str,
    batch_size: int = 1,
) -> tuple[Any, jax.Array, float, int]:
    """Stream a mean gradient and layer-summed variance of that mean.

    Gradient observations are reference microbatches. Their full gradient
    trees are immediately folded into the mean accumulator; only one small
    vector of per-layer second moments is retained. With equally sized
    microbatches this estimates the same variance of the source mean as a
    balanced group estimator without keeping group-gradient replicas alive.
    """
    if not correct_batches:
        raise ValueError("correct set is empty")
    if batch_size <= 0:
        raise ValueError("reference batch size must be positive")

    total_grad = None
    total_loss = 0.0
    total_weight = 0.0
    total_weight_squared = 0.0
    observation_count = 0
    layer_second_moment: np.ndarray | None = None
    progress = tqdm(total=len(correct_batches), desc=desc)
    for start in range(0, len(correct_batches), batch_size):
        batches = correct_batches[start : start + batch_size]
        observation_weights = [
            float(batch.get("reference_weight", 1.0)) for batch in batches
        ]
        if any(weight < 0 for weight in observation_weights):
            raise ValueError("reference weights must be nonnegative")
        batch_weight = sum(observation_weights)
        if batch_weight > 0:
            packed_batch = (
                array_batch(batches[0])
                if len(batches) == 1
                else stack_reference_batches(batches)
            )
            loss, grad = loss_grad_fn(weights, packed_batch)
            layer_squared_norm = np.asarray(
                jax.device_get(layer_squared_norm_fn(grad)),
                dtype=np.float64,
            )
            if layer_second_moment is None:
                layer_second_moment = np.zeros_like(
                    layer_squared_norm,
                    dtype=np.float64,
                )
            layer_second_moment += batch_weight * layer_squared_norm
            weighted_grad = scale_tree(grad, batch_weight)
            total_grad = (
                weighted_grad
                if total_grad is None
                else add_trees(total_grad, weighted_grad)
            )
            total_loss += batch_weight * float(loss)
            total_weight += batch_weight
            total_weight_squared += batch_weight * batch_weight
            observation_count += 1
        progress.update(len(batches))
    progress.close()
    if (
        total_grad is None
        or layer_second_moment is None
        or total_weight <= 0
    ):
        raise RuntimeError("reference gradient accumulation produced no positive weight")
    if observation_count < 2:
        raise RuntimeError(
            "layer variance estimation requires at least two reference "
            "microbatches"
        )

    mean_grad = divide_tree(total_grad, total_weight)
    mean_layer_squared_norm = np.asarray(
        jax.device_get(layer_squared_norm_fn(mean_grad)),
        dtype=np.float64,
    )
    centered_second_moment = np.maximum(
        layer_second_moment - total_weight * mean_layer_squared_norm,
        0.0,
    )
    sample_denominator = (
        total_weight - total_weight_squared / total_weight
    )
    if sample_denominator <= 0:
        raise RuntimeError("layer variance estimator has zero effective sample size")
    mean_variance_scale = total_weight_squared / (total_weight * total_weight)
    variance_of_mean = (
        centered_second_moment
        / sample_denominator
        * mean_variance_scale
    )
    return (
        mean_grad,
        jnp.asarray(variance_of_mean, dtype=jnp.float32),
        total_loss / total_weight,
        observation_count,
    )


def mean_grad_correct(
    weights: Any,
    correct_batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    *,
    batch_size: int = 1,
) -> Any:
    mean_grad, _ = mean_grad_and_loss_correct(
        weights,
        correct_batches,
        loss_grad_fn,
        batch_size=batch_size,
    )
    return mean_grad


def run_fixed_blend_layer_audit(
    args: argparse.Namespace,
    weights: dict[str, Any],
    opt_state: Any,
    optimizer: optax.GradientTransformation,
    loss_grad_fn: Any,
    wrong_batches: list[dict[str, Any]],
    synthetic_reference_grads: dict[str, Any],
    real_reference_grads: dict[str, Any],
    fused_reference_grads: dict[str, Any],
) -> dict[str, Any]:
    """Audit one fixed blend against a deterministic mean injection update."""
    if not wrong_batches:
        raise ValueError("fixed-blend layer audit requires injection batches")
    audit_count = min(
        args.anchor_blend_layer_audit_batches,
        len(wrong_batches),
    )
    rng = np.random.default_rng(
        args.tiny_anchor_seed * 104729 + args.synthetic_seed * 1009
    )
    indices = sorted(
        rng.choice(len(wrong_batches), size=audit_count, replace=False).tolist()
    )
    audit_batches = [wrong_batches[index] for index in indices]
    injection_grad, injection_loss = mean_grad_and_loss_correct(
        weights,
        audit_batches,
        loss_grad_fn,
        desc="fixed-blend layer audit injection mean grad",
        batch_size=args.reference_batch_size,
    )

    preview_update_fn = jax.jit(
        lambda grad, state, current_weights: optimizer.update(
            grad,
            state,
            current_weights,
        )
    )
    candidate_updates, _ = preview_update_fn(
        injection_grad,
        opt_state,
        weights,
    )
    jax.block_until_ready(candidate_updates)
    del injection_grad
    if args.anchor_blend_norm_align:
        aligned_synthetic, aligned_real, _ = prepare_blend_reference_sources(
            synthetic_reference_grads,
            real_reference_grads,
            norm_align_anchor=True,
            eps=args.anchor_shrinkage_eps,
        )
    else:
        aligned_synthetic = synthetic_reference_grads
        aligned_real = real_reference_grads
    tensor_stats_fn = jax.jit(
        lambda update, synthetic, real, fused: (
            fixed_blend_tensor_sufficient_statistics(
                update,
                synthetic,
                real,
                fused,
                real_weight=args.anchor_shrinkage_fixed_real_weight,
            )
        )
    )
    tensor_stats = tensor_stats_fn(
        candidate_updates,
        aligned_synthetic,
        aligned_real,
        fused_reference_grads,
    )
    tensor_stats = jax.device_get(tensor_stats)
    artifact_dir = Path(args.out_dir) / "artifacts" / "gradient_blend_layer_audit"
    summary = write_gradient_blend_audit(
        artifact_dir,
        tensor_stats,
        metadata={
            "model_name": args.model_name,
            "source_jsonl": list(args.source_jsonl),
            "anchor_count": args.tiny_anchor_count,
            "anchor_seed": args.tiny_anchor_seed,
            "synthetic_count_requested": args.synthetic_correct_n,
            "synthetic_seed": args.synthetic_seed,
            "synthetic_reference_paths": list(
                args.synthetic_correct_jsonl or ()
            ),
            "real_weight": args.anchor_shrinkage_fixed_real_weight,
            "norm_align_anchor": args.anchor_blend_norm_align,
            "injection_audit_count": audit_count,
            "injection_audit_indices": indices,
            "injection_mean_loss": injection_loss,
            "mask_stage": args.mask_stage,
        },
    )
    overall = summary["overall"]
    metrics = {
        "blend_layer_audit/injection_count": float(audit_count),
        "blend_layer_audit/injection_mean_loss": float(injection_loss),
        "blend_layer_audit/synthetic_mask_allow_pct": float(
            overall["synthetic_mask_allow_pct"]
        ),
        "blend_layer_audit/real_mask_allow_pct": float(
            overall["real_mask_allow_pct"]
        ),
        "blend_layer_audit/blended_mask_allow_pct": float(
            overall["blended_mask_allow_pct"]
        ),
        "blend_layer_audit/blended_update_energy_kept_pct": float(
            overall["blended_update_energy_kept_pct"]
        ),
        "blend_layer_audit/source_sign_conflict_pct": float(
            overall["source_sign_conflict_pct"]
        ),
        "blend_layer_audit/source_cosine": float(
            overall["source_cosine"]
        ),
        "blend_layer_audit/update_weighted_cancellation_pct": float(
            overall["update_weighted_cancellation_pct"]
        ),
        "blend_layer_audit/effective_real_update_influence_pct": float(
            overall["effective_real_update_influence_pct"]
        ),
        "blend_layer_audit/synthetic_predicted_damage_kept_pct": float(
            overall["synthetic_predicted_damage_kept_pct"]
        ),
        "blend_layer_audit/real_predicted_damage_kept_pct": float(
            overall["real_predicted_damage_kept_pct"]
        ),
        "blend_layer_audit/most_conservative_layer": float(
            summary["most_conservative_transformer_layer"][1:]
        ),
        "blend_layer_audit/most_plastic_layer": float(
            summary["most_plastic_transformer_layer"][1:]
        ),
    }
    print(
        "Fixed-blend layer audit:",
        f"blend allows {overall['blended_mask_allow_pct']:.1f}% coordinates,",
        f"keeps {overall['blended_update_energy_kept_pct']:.1f}% update energy,",
        f"source conflict {overall['source_sign_conflict_pct']:.1f}%,",
        f"heatmap={artifact_dir / 'gradient_blend_layer_heatmap.svg'}",
    )
    return metrics


def mean_memory_activity(
    weights: Any,
    batches: list[dict[str, Any]],
    activity_fn: Any,
    *,
    desc: str,
    use_reference_weights: bool = False,
) -> jax.Array:
    if not batches:
        raise ValueError(f"{desc} set is empty")
    total = None
    total_weight = 0.0
    for batch in tqdm(batches, desc=desc):
        activity = activity_fn(weights, array_batch(batch))
        weight = (
            float(batch.get("reference_weight", 1.0))
            if use_reference_weights
            else 1.0
        )
        weighted = activity * jnp.asarray(weight, dtype=activity.dtype)
        total = weighted if total is None else total + weighted
        total_weight += weight
    if total is None or total_weight <= 0:
        raise RuntimeError("memory activity accumulation produced no positive weight")
    return jax.lax.stop_gradient(total / total_weight)


def collect_entropy_gauge_activity(
    weights: Any,
    batches: list[dict[str, Any]],
    activity_fn: Any,
    *,
    desc: str,
) -> tuple[np.ndarray, np.ndarray]:
    """Collect token-weighted host activity without sorting sharded arrays."""
    if not batches:
        raise ValueError(f"{desc} source is empty")
    channel_sum: np.ndarray | None = None
    token_count = 0
    for batch in tqdm(batches, desc=desc):
        attention_mask = batch.get("attention_mask")
        if attention_mask is None:
            raise ValueError(
                "the first entropy-gauge screen requires categorical batches "
                "with attention masks"
            )
        batch_tokens = int(np.asarray(attention_mask, dtype=np.int64).sum())
        if batch_tokens <= 0:
            continue
        activity = activity_fn(weights, array_batch(batch))
        host_activity = np.asarray(
            jax.device_get(activity),
            dtype=np.float64,
        )
        weighted = host_activity * float(batch_tokens)
        channel_sum = weighted if channel_sum is None else channel_sum + weighted
        token_count += batch_tokens
    if channel_sum is None or token_count <= 0:
        raise RuntimeError(f"{desc} produced no non-padding tokens")
    layer_counts = np.full(channel_sum.shape[0], token_count, dtype=np.int64)
    return (channel_sum / float(token_count)).astype(np.float32), layer_counts


def run_jax_entropy_gauge_probe(
    weights: Any,
    batches: list[dict[str, Any]],
    forward: Any,
) -> tuple[np.ndarray, float, str]:
    if not batches:
        raise ValueError("entropy-gauge verification probe is empty")
    packed = stack_reference_batches(batches)

    @jax.jit
    def probe_fn(current_weights: Any, batch: dict[str, jax.Array]):
        logits = forward(batch["tokens"], current_weights)
        selected = logits.at[
            jnp.arange(logits.shape[0]), batch["last_idx"], :
        ].get(out_sharding=P("data", "model"))
        return selected, loss_from_logits(logits, batch)

    logits, loss = jax.block_until_ready(probe_fn(weights, packed))
    host_logits = np.asarray(jax.device_get(logits), dtype=np.float32)
    predictions = np.asarray(host_logits.argmax(axis=-1), dtype=np.int64)
    prediction_hash = hashlib.sha256(predictions.tobytes()).hexdigest()
    return host_logits, float(np.asarray(jax.device_get(loss))), prediction_hash


def prepare_jax_entropy_gauge(
    args: argparse.Namespace,
    method: str,
    weights: dict[str, Any],
    forward: Any,
    activity_fn: Any,
    synthetic_batches: list[dict[str, Any]],
    real_batches: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, np.ndarray]]:
    """Measure, apply, and verify a one-time TPU SwiGLU gauge."""
    if method != FIXED_ANCHOR_BLEND_METHOD:
        raise ValueError(
            "the entropy-gauge screen requires "
            f"METHOD_NAME={FIXED_ANCHOR_BLEND_METHOD}"
        )
    if args.anchor_blend_rule != "fixed":
        raise ValueError("the entropy-gauge screen requires ANCHOR_BLEND_RULE=fixed")
    if not math.isclose(args.anchor_shrinkage_fixed_real_weight, 0.5):
        raise ValueError("the entropy-gauge screen requires a raw 50:50 source blend")
    if args.anchor_blend_norm_align:
        raise ValueError("the entropy-gauge screen requires ANCHOR_BLEND_NORM_ALIGN=0")
    if args.reference_reduction != "mean":
        raise ValueError("the entropy-gauge screen requires REFERENCE_REDUCTION=mean")
    if not args.entropy_gauge_verify:
        raise ValueError("the entropy-gauge screen requires ENTROPY_GAUGE_VERIFY=1")
    if not synthetic_batches or not real_batches:
        raise ValueError("entropy gauge requires synthetic and real reference sources")
    if activity_fn is None:
        raise ValueError("entropy gauge requires the vendored JAX memory-activity hook")

    config = EntropyGaugeConfig(
        mode=args.entropy_gauge_mode,
        p_percent=args.entropy_gauge_p,
        q=args.entropy_gauge_q,
        eps=args.entropy_gauge_eps,
        max_scale=args.entropy_gauge_max_scale,
        seed=args.entropy_gauge_seed,
        source=args.entropy_gauge_source,
        token_scope=args.entropy_gauge_token_scope,
        verify=args.entropy_gauge_verify,
        verify_atol=args.entropy_gauge_verify_atol,
        verify_rtol=args.entropy_gauge_verify_rtol,
        power_of_two=args.entropy_gauge_power_of_two,
    )
    config.validate()
    if args.require_tpu and not config.power_of_two:
        raise ValueError(
            "TPU entropy gauges require power-of-two scales because the "
            "standard Qwen forward pass uses BF16 matrix weights"
        )

    artifacts_dir = Path(args.out_dir) / "artifacts"
    activity_cache = Path(
        args.entropy_gauge_stats_cache
        or artifacts_dir / "activity_stats.npz"
    ).expanduser()
    scale_cache = Path(
        args.entropy_gauge_scale_cache
        or artifacts_dir / "gauge_scales.npz"
    ).expanduser()
    report_path = artifacts_dir / "gauge_report.json"
    probe_batches = synthetic_batches[:8] + real_batches[:8]
    metadata = {
        "model_name": args.model_name,
        "synthetic_fingerprint": reference_batches_fingerprint(synthetic_batches),
        "real_fingerprint": reference_batches_fingerprint(real_batches),
        "probe_fingerprint": reference_batches_fingerprint(probe_batches),
        "synthetic_count": len(synthetic_batches),
        "real_count": len(real_batches),
        "anchor_seed": args.tiny_anchor_seed,
        "token_scope": config.token_scope,
    }

    activity_started = time.perf_counter()
    cache_reused = activity_cache.is_file()
    if cache_reused:
        (
            layer_names,
            synthetic_activity,
            real_activity,
            synthetic_token_counts,
            real_token_counts,
            _,
        ) = load_activity_cache(activity_cache, metadata)
    else:
        layer_names = qwen3_mlp_layer_names(weights)
        synthetic_activity, synthetic_token_counts = (
            collect_entropy_gauge_activity(
                weights,
                synthetic_batches,
                activity_fn,
                desc="entropy gauge synthetic activity",
            )
        )
        real_activity, real_token_counts = collect_entropy_gauge_activity(
            weights,
            real_batches,
            activity_fn,
            desc="entropy gauge real-anchor activity",
        )
        save_activity_cache(
            activity_cache,
            layer_names,
            synthetic_activity,
            real_activity,
            synthetic_token_counts,
            real_token_counts,
            metadata,
        )
    expected_layers = qwen3_mlp_layer_names(weights)
    if layer_names != expected_layers:
        raise ValueError("entropy-gauge activity cache has the wrong Qwen layer layout")
    activity_seconds = time.perf_counter() - activity_started

    activities = combine_source_activity(
        layer_names,
        synthetic_activity,
        real_activity,
        synthetic_token_counts,
        real_token_counts,
    )
    scales, low_masks, scale_report = build_gauge_scales(activities, config)
    scale_metadata = {
        **metadata,
        "mode": config.mode,
        "p_percent": config.p_percent,
        "q": config.q,
        "max_scale": config.max_scale,
        "seed": config.seed,
        "power_of_two": config.power_of_two,
    }
    save_scale_cache(scale_cache, scales, low_masks, scale_metadata)

    before_logits, before_loss, before_prediction_hash = (
        run_jax_entropy_gauge_probe(weights, probe_batches, forward)
    )
    if config.mode != "none":
        apply_qwen3_swiglu_gauge(weights, scales)
    after_logits, after_loss, after_prediction_hash = run_jax_entropy_gauge_probe(
        weights,
        probe_batches,
        forward,
    )
    verification = verify_probe_outputs(
        before_logits,
        after_logits,
        before_loss,
        after_loss,
        atol=config.verify_atol,
        rtol=config.verify_rtol,
        abort=config.verify,
    )
    if before_prediction_hash != after_prediction_hash:
        raise RuntimeError("entropy gauge changed the fixed probe prediction hash")

    layers = scale_report["layers"]
    before_entropy = float(
        np.mean(
            [layer["before"]["combined"]["normalized_entropy"] for layer in layers.values()]
        )
    )
    after_entropy = float(
        np.mean(
            [layer["after"]["combined"]["normalized_entropy"] for layer in layers.values()]
        )
    )
    all_scales = np.concatenate([scales[name] for name in layer_names])
    scale_hash = hashlib.sha256(all_scales.tobytes()).hexdigest()
    effective_channels_before = float(
        np.mean(
            [layer["before"]["combined"]["effective_channels"] for layer in layers.values()]
        )
    )
    effective_channels_after = float(
        np.mean(
            [layer["after"]["combined"]["effective_channels"] for layer in layers.values()]
        )
    )
    synthetic_entropy_before = float(
        np.mean(
            [layer["before"]["synthetic"]["normalized_entropy"] for layer in layers.values()]
        )
    )
    real_entropy_before = float(
        np.mean(
            [layer["before"]["real"]["normalized_entropy"] for layer in layers.values()]
        )
    )
    top10_mass_before = float(
        np.mean(
            [layer["before"]["combined"]["top10_mass"] for layer in layers.values()]
        )
    )
    top10_mass_after = float(
        np.mean(
            [layer["after"]["combined"]["top10_mass"] for layer in layers.values()]
        )
    )
    clipped_fraction = float(
        np.mean([layer["clipped_fraction"] for layer in layers.values()])
    )
    metrics: dict[str, Any] = {
        "gauge/mode": config.mode,
        "gauge/mode_id": {
            "none": 0,
            "resuscitate": 1,
            "permuted": 2,
            "inverse": 3,
        }[config.mode],
        "gauge/enabled": int(config.mode != "none"),
        "gauge/p_percent": config.p_percent,
        "gauge/q": config.q,
        "gauge/max_scale": config.max_scale,
        "gauge/power_of_two": int(config.power_of_two),
        "gauge/activity_cache_reused": int(cache_reused),
        "gauge/activity_seconds": activity_seconds,
        "gauge/probe_allclose": int(verification.allclose),
        "gauge/probe_prediction_changes": verification.prediction_changes,
        "gauge/probe_max_abs_logit_diff": verification.probe_max_abs_logit_diff,
        "gauge/probe_max_rel_logit_diff": verification.probe_max_rel_logit_diff,
        "gauge/probe_loss_abs_diff": verification.probe_loss_abs_diff,
        "gauge/combined_normalized_entropy_before": before_entropy,
        "gauge/combined_normalized_entropy_after": after_entropy,
        "gauge/combined_normalized_entropy_delta": after_entropy - before_entropy,
        "gauge/scale_mean": float(all_scales.mean()),
        "gauge/scale_min": float(all_scales.min()),
        "gauge/scale_max": float(all_scales.max()),
        "gauge/clipped_fraction": clipped_fraction,
        "entropy/synth_before": synthetic_entropy_before,
        "entropy/real_before": real_entropy_before,
        "entropy/combined_before": before_entropy,
        "entropy/combined_after": after_entropy,
        "entropy/effective_channels_before": effective_channels_before,
        "entropy/effective_channels_after": effective_channels_after,
        "entropy/top10_mass_before": top10_mass_before,
        "entropy/top10_mass_after": top10_mass_after,
    }
    dataset_name = Path(args.out_correct_jsonl).name.split("_correct_", 1)[0]
    paired_metadata = {
        "model_name": args.model_name,
        "dataset": dataset_name,
        "anchor_count": len(real_batches),
        "anchor_seed": args.tiny_anchor_seed,
        "synthetic_seed": args.synthetic_seed,
        "split_hash": hashlib.sha256(
            (
                metadata["synthetic_fingerprint"]
                + metadata["real_fingerprint"]
            ).encode("ascii")
        ).hexdigest(),
        "synthetic_bank_hash": metadata["synthetic_fingerprint"],
        "real_anchor_hash": metadata["real_fingerprint"],
        "probe_hash": metadata["probe_fingerprint"],
        "initial_predictions_hash": before_prediction_hash,
        "batch_order_seed": args.synthetic_seed,
    }
    aggregate = {
        **metrics,
        "entropy/combined_before": before_entropy,
        "entropy/combined_after": after_entropy,
        "entropy/effective_channels_before": effective_channels_before,
        "entropy/effective_channels_after": effective_channels_after,
    }
    report = {
        "format_version": 1,
        "backend": "jax_tpu" if args.require_tpu else "jax",
        "config": scale_report["config"],
        "metadata": paired_metadata,
        "aggregate": aggregate,
        "identity": {
            **metadata,
            "initial_prediction_hash": before_prediction_hash,
            "scale_hash": scale_hash,
        },
        "activity_cache": str(activity_cache),
        "scale_cache": str(scale_cache),
        "verification": verification.__dict__,
        "metrics": metrics,
        "layers": layers,
    }
    write_entropy_gauge_json(report_path, report)
    print(
        "Entropy gauge:",
        f"mode={config.mode} cache={'reused' if cache_reused else 'built'} "
        f"entropy={before_entropy:.6f}->{after_entropy:.6f} "
        f"max_logit_diff={verification.probe_max_abs_logit_diff:.3g}",
    )
    print("Entropy gauge report:", report_path)
    return weights, metrics, low_masks


def summarize_entropy_gauge_update(
    before_weights: dict[str, Any],
    after_weights: dict[str, Any],
    low_masks: dict[str, np.ndarray],
    *,
    eps: float = 1e-30,
) -> dict[str, float]:
    """Split one applied down-projection update by pre-gauge activity."""
    low_sq = jnp.asarray(0.0, dtype=jnp.float32)
    high_sq = jnp.asarray(0.0, dtype=jnp.float32)
    low_changed = jnp.asarray(0.0, dtype=jnp.float32)
    high_changed = jnp.asarray(0.0, dtype=jnp.float32)
    low_count = 0
    high_count = 0
    for layer_name, host_low in low_masks.items():
        key = f"{layer_name}.down_proj.weight"
        delta = after_weights[key] - before_weights[key]
        low = np.asarray(host_low, dtype=np.float32)
        low_selector = jax.device_put(low[None, :], delta.sharding)
        high_selector = jax.device_put((1.0 - low)[None, :], delta.sharding)
        squared = jnp.square(delta.astype(jnp.float32))
        changed = (delta != 0).astype(jnp.float32)
        low_sq = low_sq + jnp.sum(squared * low_selector)
        high_sq = high_sq + jnp.sum(squared * high_selector)
        low_changed = low_changed + jnp.sum(changed * low_selector)
        high_changed = high_changed + jnp.sum(changed * high_selector)
        low_count += int(delta.shape[0]) * int(low.sum())
        high_count += int(delta.shape[0]) * int(low.size - low.sum())
    low_sq, high_sq, low_changed, high_changed = jax.block_until_ready(
        (low_sq, high_sq, low_changed, high_changed)
    )
    low_norm = math.sqrt(float(low_sq))
    high_norm = math.sqrt(float(high_sq))
    return {
        "update/low_activity_down_norm": low_norm,
        "update/high_activity_down_norm": high_norm,
        "update/low_high_down_ratio": low_norm / max(high_norm, eps),
        "mask/low_activity_keep": float(low_changed) / max(low_count, 1),
        "mask/high_activity_keep": float(high_changed) / max(high_count, 1),
    }


def snapshot_entropy_gauge_down_weights(
    weights: dict[str, Any],
    low_masks: dict[str, np.ndarray],
) -> dict[str, Any]:
    """Copy only gauge-diagnostic leaves before a donated train step."""
    snapshot = {
        key: jnp.array(weights[key], copy=True)
        for layer_name in low_masks
        for key in (f"{layer_name}.down_proj.weight",)
    }
    if snapshot:
        jax.block_until_ready(snapshot)
    return snapshot


def write_entropy_gauge_paired_predictions(
    out_dir: str,
    gauge_mode: str,
    final_epoch: int,
) -> Path:
    jsonl_dir = Path(out_dir) / "jsonl"
    before_path = jsonl_dir / "infer_correct_ep0.jsonl"
    after_path = jsonl_dir / f"infer_correct_ep{final_epoch}.jsonl"
    if not before_path.is_file() or not after_path.is_file():
        raise FileNotFoundError(
            "entropy-gauge paired prediction inputs are missing: "
            f"{before_path}, {after_path}"
        )
    before_rows = [
        json.loads(line)
        for line in before_path.read_text(encoding="utf-8").splitlines()
        if line
    ]
    after_rows = [
        json.loads(line)
        for line in after_path.read_text(encoding="utf-8").splitlines()
        if line
    ]
    if len(before_rows) != len(after_rows):
        raise ValueError("entropy-gauge paired prediction row counts differ")
    output_path = Path(out_dir) / "artifacts" / "paired_predictions.jsonl"
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with output_path.open("w", encoding="utf-8") as handle:
        for before, after in zip(before_rows, after_rows):
            identity = (before.get("question"), before.get("label"))
            if identity != (after.get("question"), after.get("label")):
                raise ValueError("entropy-gauge paired prediction identities differ")
            row = {
                "example_id": hashlib.sha256(
                    f"{identity[0]}\0{identity[1]}".encode("utf-8")
                ).hexdigest()[:16],
                "base_correct": int(before.get("predict_label") == before.get("label")),
                "final_correct": int(after.get("predict_label") == after.get("label")),
                "anchor_flag": int(bool(before.get("is_tiny_anchor"))),
                "gauge_mode": gauge_mode,
            }
            write_jsonl_line(handle, row)
    return output_path


def estimate_ffn_value_attribution_scores(
    weights: Any,
    batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    attribution_fn: Any,
    layouts: tuple[FfnMemorySlotLayout, ...],
    *,
    desc: str = "real-anchor FFN value attribution",
) -> tuple[np.ndarray, ...]:
    """Collect one gradient-times-value attribution vector per probe."""
    if not batches:
        raise ValueError("FFN value attribution requires real-anchor probes")
    score_banks = [
        np.empty((len(batches), layout.slot_count), dtype=np.float32)
        for layout in layouts
    ]
    for probe_idx, batch in enumerate(tqdm(batches, desc=desc)):
        _, grad = loss_grad_fn(weights, array_batch(batch))
        layer_scores = jax.device_get(attribution_fn(weights, grad))
        if len(layer_scores) != len(layouts):
            raise ValueError("FFN value attribution hook returned the wrong layer count")
        for layer_idx, (scores, layout) in enumerate(
            zip(layer_scores, layouts, strict=True)
        ):
            scores = np.asarray(scores, dtype=np.float32)
            expected_shape = (1, layout.slot_count)
            if scores.shape != expected_shape:
                raise ValueError(
                    f"layer {layout.layer} attribution has shape {scores.shape}, "
                    f"expected {expected_shape}"
                )
            score_banks[layer_idx][probe_idx] = scores[0]
    return tuple(score_banks)


def estimate_memory_subspace_bases(
    weights: Any,
    batches: list[dict[str, Any]],
    coefficient_fn: Any,
    layouts: tuple[FfnMemorySlotLayout, ...],
    *,
    rank: int,
    oversample: int,
    power_iterations: int,
    batch_size: int,
    seed: int,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Fit one frozen right-address basis per FFN layer from mastered probes."""
    if not batches:
        raise ValueError("memory subspace estimation requires synthetic probes")
    if batch_size <= 0:
        raise ValueError("memory subspace probe batch size must be positive")
    feature_counts = {layout.slot_count for layout in layouts}
    if len(feature_counts) != 1:
        raise ValueError(
            "stacked memory subspace estimation requires one FFN width across layers"
        )
    feature_count = next(iter(feature_counts))
    coefficient_bank = np.empty(
        (len(layouts), len(batches), feature_count),
        dtype=np.float16,
    )

    progress = tqdm(total=len(batches), desc="memory subspace coefficient probes")
    for start in range(0, len(batches), batch_size):
        probe_batches = batches[start : start + batch_size]
        packed = (
            array_batch(probe_batches[0])
            if len(probe_batches) == 1
            else stack_reference_batches(probe_batches)
        )
        coefficients = np.asarray(
            jax.device_get(coefficient_fn(weights, packed)),
            dtype=np.float32,
        )
        expected_shape = (len(layouts), len(probe_batches), feature_count)
        if coefficients.shape != expected_shape:
            raise ValueError(
                f"memory coefficient hook returned {coefficients.shape}, "
                f"expected {expected_shape}"
            )
        probe_weights = np.sqrt(
            np.asarray(
                [max(float(batch.get("reference_weight", 1.0)), 0.0) for batch in probe_batches],
                dtype=np.float32,
            )
        )
        coefficients *= probe_weights[None, :, None]
        coefficient_bank[:, start : start + len(probe_batches), :] = coefficients
        progress.update(len(probe_batches))
    progress.close()

    bases = []
    layer_stats = []
    for layer_idx, layout in enumerate(layouts):
        basis, stats = estimate_right_activation_subspace(
            coefficient_bank[layer_idx],
            rank,
            oversample=oversample,
            power_iterations=power_iterations,
            seed=seed + layout.layer * 1009,
        )
        bases.append(basis)
        layer_stats.append({"layer": layout.layer, **stats})
    del coefficient_bank
    captured = np.asarray(
        [stats["captured_energy_fraction"] for stats in layer_stats],
        dtype=np.float64,
    )
    metadata = {
        "method": "signed decision-token SwiGLU randomized SVD",
        "summary": {
            "layer_count": len(layouts),
            "probe_count": len(batches),
            "feature_count": feature_count,
            "estimated_rank": rank,
            "oversample": oversample,
            "power_iterations": power_iterations,
            "synthetic_energy_captured_mean": float(captured.mean()),
            "synthetic_energy_captured_min": float(captured.min()),
            "synthetic_energy_captured_max": float(captured.max()),
        },
        "layers": layer_stats,
    }
    return np.stack(bases, axis=0), metadata


def collect_prompt_invariant_activation_features(
    weights: Any,
    view_groups: list[dict[str, Any]],
    feature_fn: Any,
    *,
    desc: str,
) -> tuple[dict[str, np.ndarray], dict[str, float]]:
    """Average frozen activation inputs within each semantic prompt family."""
    if not view_groups:
        raise ValueError("prompt-invariant activation families are empty")
    family_features: dict[str, list[np.ndarray]] = {
        "address": [],
        "value": [],
        "attention": [],
    }
    consistency: dict[str, list[float]] = {
        "address": [],
        "value": [],
        "attention": [],
    }
    for group in tqdm(view_groups, desc=desc):
        views = list(group.get("views") or [])
        if not views:
            raise ValueError("prompt-invariant activation family has no views")
        packed = stack_reference_batches([view["batch"] for view in views])
        outputs = jax.device_get(feature_fn(weights, packed))
        family_weight = max(float(group.get("weight", 1.0)), 0.0)
        weight_scale = math.sqrt(family_weight)
        for name, output in zip(
            ("address", "value", "attention"),
            outputs,
            strict=True,
        ):
            values = np.asarray(output, dtype=np.float32)
            if values.ndim != 3 or values.shape[1] != len(views):
                raise ValueError(
                    f"{name} activation hook returned {values.shape}, expected "
                    f"[layer, {len(views)}, feature]"
                )
            family_mean = values.mean(axis=1)
            family_norm = np.linalg.norm(family_mean, axis=-1, keepdims=True)
            normalized_mean = family_mean / np.maximum(family_norm, 1e-12)
            family_features[name].append(
                (weight_scale * normalized_mean).astype(np.float16)
            )
            view_norm = np.linalg.norm(values, axis=-1, keepdims=True)
            normalized_views = values / np.maximum(view_norm, 1e-12)
            consistency[name].append(
                float(
                    np.mean(
                        np.sum(
                            normalized_views * normalized_mean[:, None, :],
                            axis=-1,
                        )
                    )
                )
            )
    banks = {
        name: np.stack(values, axis=1)
        for name, values in family_features.items()
    }
    stats = {
        "family_count": float(len(view_groups)),
        "view_count": float(
            sum(len(group.get("views") or []) for group in view_groups)
        ),
        **{
            f"{name}_view_to_family_cosine_mean": float(np.mean(values))
            for name, values in consistency.items()
        },
    }
    return banks, stats


def collect_batched_ffn_activities(
    weights: Any,
    batches: list[dict[str, Any]],
    activity_fn: Any,
    *,
    batch_size: int,
    desc: str,
) -> np.ndarray:
    """Collect per-example absolute FFN coefficients as [example, layer, slot]."""
    if not batches:
        raise ValueError(f"{desc} requires at least one batch")
    if batch_size <= 0:
        raise ValueError("FFN activity batch size must be positive")
    collected: list[np.ndarray] = []
    progress = tqdm(total=len(batches), desc=desc)
    for start in range(0, len(batches), batch_size):
        chunk = batches[start : start + batch_size]
        packed = (
            array_batch(chunk[0])
            if len(chunk) == 1
            else stack_reference_batches(chunk)
        )
        activity = np.asarray(
            jax.device_get(activity_fn(weights, packed)),
            dtype=np.float32,
        )
        if activity.ndim != 3 or activity.shape[1] != len(chunk):
            raise ValueError(
                f"FFN activity hook returned {activity.shape}, expected "
                f"[layer, {len(chunk)}, slot]"
            )
        collected.append(np.transpose(activity, (1, 0, 2)))
        progress.update(len(chunk))
    progress.close()
    return np.concatenate(collected, axis=0)


def collect_prompt_invariant_ffn_family_activities(
    weights: Any,
    view_groups: list[dict[str, Any]],
    activity_fn: Any,
    *,
    batch_size: int,
) -> tuple[np.ndarray, dict[str, float]]:
    """Conservatively reduce FFN activity across every retained prompt view."""
    if not view_groups:
        raise ValueError("causal routing anchor families are empty")
    flat_batches: list[dict[str, Any]] = []
    family_slices: list[slice] = []
    for group in view_groups:
        views = list(group.get("views") or [])
        if not views:
            raise ValueError("causal routing anchor family has no prompt views")
        start = len(flat_batches)
        flat_batches.extend(view["batch"] for view in views)
        family_slices.append(slice(start, len(flat_batches)))
    activities = collect_batched_ffn_activities(
        weights,
        flat_batches,
        activity_fn,
        batch_size=batch_size,
        desc="real prompt-invariant FFN activities",
    )
    family_activities = np.stack(
        [
            np.min(activities[family_slice], axis=0)
            for family_slice in family_slices
        ],
        axis=0,
    )
    view_means = np.stack(
        [
            np.mean(activities[family_slice], axis=0)
            for family_slice in family_slices
        ],
        axis=0,
    )
    stability = family_activities / np.maximum(view_means, 1e-12)
    stats = {
        "causal_routing/anchor_family_count": float(len(family_slices)),
        "causal_routing/anchor_view_count": float(len(flat_batches)),
        "causal_routing/prompt_activity_stability_mean": float(
            np.mean(stability)
        ),
        "causal_routing/prompt_activity_stability_p10": float(
            np.quantile(stability, 0.1)
        ),
    }
    return family_activities, stats


def evaluate_causal_routing_interventions(
    weights: Any,
    view_groups: list[dict[str, Any]],
    margin_fn: Any,
    intervention_scales: np.ndarray,
    *,
    pattern_batch_size: int,
    audit_batch_size: int,
) -> tuple[np.ndarray, np.ndarray, dict[str, float]]:
    """Measure robust family-margin drops under direct FFN interventions."""
    if not view_groups:
        raise ValueError("causal routing intervention audit has no families")
    scales = np.asarray(intervention_scales, dtype=np.float32)
    if scales.ndim != 3:
        raise ValueError(
            "causal routing intervention scales need [pattern, layer, slot]"
        )
    if pattern_batch_size <= 0 or audit_batch_size <= 0:
        raise ValueError("causal routing intervention batch sizes must be positive")

    flat_batches: list[dict[str, Any]] = []
    family_slices: list[slice] = []
    for group in view_groups:
        views = list(group.get("views") or [])
        if not views:
            raise ValueError("causal routing anchor family has no retained views")
        start = len(flat_batches)
        flat_batches.extend(view["batch"] for view in views)
        family_slices.append(slice(start, len(flat_batches)))

    def evaluate_scale_bank(scale_bank: np.ndarray, desc: str) -> np.ndarray:
        output = np.empty(
            (scale_bank.shape[0], len(flat_batches)),
            dtype=np.float32,
        )
        total = scale_bank.shape[0] * len(flat_batches)
        progress = tqdm(total=total, desc=desc)
        for pattern_start in range(
            0,
            scale_bank.shape[0],
            pattern_batch_size,
        ):
            pattern_chunk = scale_bank[
                pattern_start : pattern_start + pattern_batch_size
            ]
            for view_start in range(0, len(flat_batches), audit_batch_size):
                view_chunk = flat_batches[
                    view_start : view_start + audit_batch_size
                ]
                packed = (
                    array_batch(view_chunk[0])
                    if len(view_chunk) == 1
                    else stack_reference_batches(view_chunk)
                )
                margins = np.asarray(
                    jax.device_get(
                        margin_fn(
                            weights,
                            packed,
                            jnp.asarray(pattern_chunk, dtype=jnp.float32),
                        )
                    ),
                    dtype=np.float32,
                )
                expected = (len(pattern_chunk), len(view_chunk))
                if margins.shape != expected:
                    raise ValueError(
                        f"causal margin hook returned {margins.shape}, "
                        f"expected {expected}"
                    )
                output[
                    pattern_start : pattern_start + len(pattern_chunk),
                    view_start : view_start + len(view_chunk),
                ] = margins
                progress.update(len(pattern_chunk) * len(view_chunk))
        progress.close()
        return output

    baseline_scales = np.ones((1, *scales.shape[1:]), dtype=np.float32)
    baseline_view_margins = evaluate_scale_bank(
        baseline_scales,
        "causal routing baseline margins",
    )[0]
    intervened_view_margins = evaluate_scale_bank(
        scales,
        "causal routing ablation margins",
    )
    baseline_family_margins = np.asarray(
        [
            np.min(baseline_view_margins[family_slice])
            for family_slice in family_slices
        ],
        dtype=np.float32,
    )
    intervened_family_margins = np.stack(
        [
            np.min(intervened_view_margins[:, family_slice], axis=1)
            for family_slice in family_slices
        ],
        axis=1,
    )
    family_margin_drops = (
        baseline_family_margins[None, :] - intervened_family_margins
    )
    stats = {
        "causal_routing/baseline_family_margin_mean": float(
            np.mean(baseline_family_margins)
        ),
        "causal_routing/baseline_family_margin_min": float(
            np.min(baseline_family_margins)
        ),
        "causal_routing/intervened_family_margin_mean": float(
            np.mean(intervened_family_margins)
        ),
        "causal_routing/intervened_family_margin_min": float(
            np.min(intervened_family_margins)
        ),
    }
    return family_margin_drops, baseline_family_margins, stats


def estimate_prompt_invariant_activation_bases(
    synthetic_features: dict[str, np.ndarray],
    real_features: dict[str, np.ndarray],
    *,
    rank: int,
    oversample: int,
    power_iterations: int,
    seed: int,
) -> tuple[dict[str, np.ndarray], dict[str, Any]]:
    """Fit real-first, mutually orthogonal activation input subspaces."""
    expected = {"address", "value", "attention"}
    if set(synthetic_features) != expected or set(real_features) != expected:
        raise ValueError("prompt-invariant activation feature bank is incomplete")
    if rank <= 0:
        raise ValueError("activation-nullspace rank must be positive")
    layer_count = synthetic_features["address"].shape[0]
    if any(bank.shape[0] != layer_count for bank in synthetic_features.values()):
        raise ValueError("synthetic activation banks have inconsistent layers")
    if any(bank.shape[0] != layer_count for bank in real_features.values()):
        raise ValueError("real activation banks have inconsistent layers")
    if rank > min(
        synthetic_features["address"].shape[1],
        real_features["address"].shape[1],
    ):
        raise ValueError(
            "activation-nullspace rank exceeds the number of synthetic or real "
            "semantic families"
        )

    bases: dict[str, list[np.ndarray]] = {
        "real_address": [],
        "synthetic_address": [],
        "real_value": [],
        "synthetic_value": [],
        "real_attention": [],
        "synthetic_attention": [],
    }
    layer_metadata = []
    for layer in range(layer_count):
        layer_stats: dict[str, Any] = {"layer": layer}
        for family_index, family in enumerate(("address", "value", "attention")):
            real_matrix = np.asarray(real_features[family][layer], dtype=np.float32)
            synthetic_matrix = np.asarray(
                synthetic_features[family][layer],
                dtype=np.float32,
            )
            real_basis, real_stats = estimate_right_activation_subspace(
                real_matrix,
                rank,
                oversample=oversample,
                power_iterations=power_iterations,
                seed=seed + layer * 1009 + family_index * 104729,
            )
            synthetic_residual = synthetic_matrix - (
                synthetic_matrix @ real_basis
            ) @ real_basis.T
            synthetic_basis, synthetic_stats = estimate_right_activation_subspace(
                synthetic_residual,
                rank,
                oversample=oversample,
                power_iterations=power_iterations,
                seed=seed + layer * 2029 + family_index * 130363,
            )
            bases[f"real_{family}"].append(real_basis)
            bases[f"synthetic_{family}"].append(synthetic_basis)
            layer_stats[family] = {
                "real": real_stats,
                "synthetic_residual": synthetic_stats,
                "real_synthetic_overlap_fro": float(
                    np.linalg.norm(real_basis.T @ synthetic_basis, ord="fro")
                ),
            }
        layer_metadata.append(layer_stats)
    stacked = {
        key: np.stack(values, axis=0).astype(np.float32, copy=False)
        for key, values in bases.items()
    }
    metadata = {
        "method": "real-first prompt-invariant activation input nullspace",
        "summary": {
            "layer_count": layer_count,
            "rank_per_source": rank,
            "real_family_count": int(real_features["address"].shape[1]),
            "synthetic_family_count": int(
                synthetic_features["address"].shape[1]
            ),
            "real_priority": True,
            "synthetic_residualized_against_real": True,
            "family_reduction": "mean_then_l2_normalize",
        },
        "layers": layer_metadata,
    }
    return stacked, metadata


def build_causal_group_calibration_batch(
    synthetic_view_groups: list[dict[str, Any]],
    real_view_groups: list[dict[str, Any]],
    *,
    synthetic_count: int,
    real_count: int,
    epoch: int,
    seed: int,
) -> dict[str, jax.Array]:
    """Build a source-balanced, rotating prompt-invariant calibration batch."""
    if synthetic_count <= 0 or real_count <= 0:
        raise ValueError("causal calibration source counts must be positive")
    synthetic = select_prompt_family_epoch_batches(
        synthetic_view_groups,
        epoch,
        seed,
    )
    real = select_prompt_family_epoch_batches(
        real_view_groups,
        epoch,
        seed + 104729,
    )
    rng = np.random.default_rng(seed + epoch * 1009)
    synthetic = [
        synthetic[index]
        for index in rng.permutation(len(synthetic))[
            : min(synthetic_count, len(synthetic))
        ]
    ]
    real = [
        real[index]
        for index in rng.permutation(len(real))[: min(real_count, len(real))]
    ]
    if not synthetic or not real:
        raise RuntimeError("causal calibration retained an empty source")
    for batch in synthetic:
        batch["reference_weight"] = 0.5 / len(synthetic)
    for batch in real:
        batch["reference_weight"] = 0.5 / len(real)
    return stack_reference_batches([*synthetic, *real])


def balanced_group_assignments(n_items: int, groups: int, seed: int | None) -> list[int]:
    if n_items <= 0:
        raise ValueError("group assignment requires at least one item")
    groups = min(groups, n_items)
    if groups <= 0:
        raise ValueError("group count must be positive")
    if seed is None:
        return [idx % groups for idx in range(n_items)]
    permutation = np.random.default_rng(seed).permutation(n_items)
    assignments = [0 for _ in range(n_items)]
    for rank, item_idx in enumerate(permutation.tolist()):
        assignments[item_idx] = rank % groups
    return assignments


def lineage_group_assignments(
    batches: list[dict[str, Any]],
    *,
    groups: int,
    anchor_count: int,
    seed: int,
    source: str,
) -> list[int]:
    """Assign real anchors and their synthetic descendants to shared buckets."""
    if source not in {"real", "synthetic"}:
        raise ValueError("lineage assignment source must be real or synthetic")
    if not batches:
        raise ValueError("lineage assignment requires at least one batch")
    groups = min(groups, anchor_count, len(batches))
    if groups <= 0:
        raise ValueError("lineage assignment requires positive groups and anchors")
    anchor_order = np.random.default_rng(seed).permutation(anchor_count)
    anchor_to_group = {
        int(anchor_idx): int(rank % groups)
        for rank, anchor_idx in enumerate(anchor_order.tolist())
    }
    if source == "real":
        assignments = []
        for batch_index, batch in enumerate(batches):
            anchor_idx = int(batch.get("base_example_index", batch_index))
            if anchor_idx not in anchor_to_group:
                raise ValueError(
                    f"real prompt view references unknown anchor {anchor_idx}"
                )
            assignments.append(anchor_to_group[anchor_idx])
        return assignments

    assignments = []
    loads = [0 for _ in range(groups)]
    for batch_index, batch in enumerate(batches):
        parent_ids = [
            int(parent)
            for parent in (batch.get("parent_anchor_ids") or [])
            if int(parent) in anchor_to_group
        ]
        if not parent_ids:
            raise ValueError(
                "lineage-expanded veto requires synthetic_icl_demo_ids; "
                f"synthetic batch {batch_index} has no valid parent anchors"
            )
        candidates = sorted({anchor_to_group[parent] for parent in parent_ids})
        group_idx = min(candidates, key=lambda idx: (loads[idx], idx))
        assignments.append(group_idx)
        loads[group_idx] += 1
    missing = [idx for idx, count in enumerate(loads) if count == 0]
    if missing:
        raise ValueError(
            "synthetic lineage assignment left empty groups: "
            f"{missing}; parent-anchor coverage is insufficient"
        )
    return assignments


def grouped_grad_correct(
    weights: Any,
    batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    *,
    groups: int,
    desc: str,
    group_seed: int | None = None,
    group_assignments: list[int] | None = None,
    batch_size: int = 1,
) -> tuple[Any, list[Any], float]:
    """Return an exact weighted mean gradient plus deterministic group means."""
    if not batches:
        raise ValueError("reference set is empty")
    if batch_size <= 0:
        raise ValueError("reference batch size must be positive")
    groups = min(groups, len(batches))
    if group_assignments is None:
        assignments = balanced_group_assignments(
            len(batches),
            groups,
            group_seed,
        )
    else:
        if len(group_assignments) != len(batches):
            raise ValueError(
                "explicit group assignments must match the reference set"
            )
        if any(group < 0 or group >= groups for group in group_assignments):
            raise ValueError("explicit group assignment is outside group range")
        if set(group_assignments) != set(range(groups)):
            raise ValueError("explicit group assignments must populate every group")
        assignments = list(group_assignments)
    group_totals: list[Any | None] = [None for _ in range(groups)]
    group_weights = [0.0 for _ in range(groups)]
    total_grad = None
    total_loss = 0.0
    total_weight = 0.0
    pending: list[list[dict[str, Any]]] = [[] for _ in range(groups)]
    progress = tqdm(total=len(batches), desc=desc)

    def accumulate(group_idx: int, grouped_batches: list[dict[str, Any]]) -> None:
        nonlocal total_grad, total_loss, total_weight
        reference_weights = [
            float(batch.get("reference_weight", 1.0)) for batch in grouped_batches
        ]
        if any(weight < 0 for weight in reference_weights):
            raise ValueError("reference weights must be nonnegative")
        batch_weight = sum(reference_weights)
        if batch_weight <= 0:
            progress.update(len(grouped_batches))
            return
        packed_batch = (
            array_batch(grouped_batches[0])
            if len(grouped_batches) == 1
            else stack_reference_batches(grouped_batches)
        )
        loss, grad = loss_grad_fn(weights, packed_batch)
        weighted_grad = scale_tree(grad, batch_weight)
        total_loss += batch_weight * float(loss)
        total_weight += batch_weight
        total_grad = (
            weighted_grad
            if total_grad is None
            else add_trees(total_grad, weighted_grad)
        )
        group_totals[group_idx] = (
            weighted_grad
            if group_totals[group_idx] is None
            else add_trees(group_totals[group_idx], weighted_grad)
        )
        group_weights[group_idx] += batch_weight
        progress.update(len(grouped_batches))

    for batch_idx, batch in enumerate(batches):
        group_idx = assignments[batch_idx]
        pending[group_idx].append(batch)
        if len(pending[group_idx]) == batch_size:
            accumulate(group_idx, pending[group_idx])
            pending[group_idx] = []
    for group_idx, grouped_batches in enumerate(pending):
        if grouped_batches:
            accumulate(group_idx, grouped_batches)
    progress.close()
    if total_grad is None or total_weight <= 0:
        raise RuntimeError("reference gradient accumulation produced no positive weight")
    group_means = [
        divide_tree(group_total, group_weight)
        for group_total, group_weight in zip(group_totals, group_weights)
        if group_total is not None and group_weight > 0
    ]
    return (
        divide_tree(total_grad, total_weight),
        group_means,
        total_loss / total_weight,
    )


def mean_grad_and_fisher_correct(
    weights: Any,
    batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    *,
    desc: str,
) -> tuple[Any, Any, float]:
    """Return weighted ``E[g]`` and exact per-example ``E[g ** 2]``.

    Each call to ``loss_grad_fn`` receives exactly one example. This is
    necessary because squaring a minibatch-mean gradient is not an empirical
    Fisher estimate.
    """
    if not batches:
        raise ValueError("Fisher reference set is empty")
    total_grad = None
    total_grad_sq = None
    total_loss = 0.0
    total_weight = 0.0
    for batch in tqdm(batches, desc=desc):
        reference_weight = float(batch.get("reference_weight", 1.0))
        if reference_weight < 0:
            raise ValueError("reference weights must be nonnegative")
        if reference_weight == 0:
            continue
        loss, grad = loss_grad_fn(weights, array_batch(batch))
        weighted_grad = scale_tree(grad, reference_weight)
        weighted_grad_sq = jax.tree_util.tree_map(
            lambda value: (
                jnp.square(jnp.asarray(value, dtype=jnp.float32))
                * jnp.asarray(reference_weight, dtype=jnp.float32)
            ),
            grad,
        )
        total_grad = (
            weighted_grad
            if total_grad is None
            else add_trees(total_grad, weighted_grad)
        )
        total_grad_sq = (
            weighted_grad_sq
            if total_grad_sq is None
            else add_trees(total_grad_sq, weighted_grad_sq)
        )
        total_loss += reference_weight * float(loss)
        total_weight += reference_weight
    if total_grad is None or total_grad_sq is None or total_weight <= 0:
        raise RuntimeError(
            "Fisher reference accumulation produced no positive weight"
        )
    return (
        divide_tree(total_grad, total_weight),
        divide_tree(total_grad_sq, total_weight),
        total_loss / total_weight,
    )


def grouped_grad_and_fisher_correct(
    weights: Any,
    batches: list[dict[str, Any]],
    loss_grad_fn: Any,
    *,
    groups: int,
    desc: str,
    group_seed: int | None = None,
    group_assignments: list[int] | None = None,
    curvature_group_reduction: str = "mean",
) -> tuple[Any, list[Any], Any, float]:
    """Return grouped mean gradients and reduced per-example Fisher.

    Groups are processed sequentially so only one group-Fisher accumulator is
    live in addition to the reduced Fisher and the CVaR group gradients.
    """
    if not batches:
        raise ValueError("Fisher reference set is empty")
    if curvature_group_reduction not in {"mean", "max"}:
        raise ValueError("curvature group reduction must be mean or max")
    groups = min(groups, len(batches))
    if group_assignments is None:
        assignments = balanced_group_assignments(
            len(batches),
            groups,
            group_seed,
        )
    else:
        if len(group_assignments) != len(batches):
            raise ValueError(
                "explicit group assignments must match the reference set"
            )
        if any(group < 0 or group >= groups for group in group_assignments):
            raise ValueError("explicit group assignment is outside group range")
        if set(group_assignments) != set(range(groups)):
            raise ValueError(
                "explicit group assignments must populate every group"
            )
        assignments = list(group_assignments)

    grouped_batches: list[list[dict[str, Any]]] = [
        [] for _ in range(groups)
    ]
    for batch, group_idx in zip(batches, assignments):
        grouped_batches[group_idx].append(batch)

    group_means = []
    reduced_fisher = None
    total_grad = None
    total_loss = 0.0
    total_weight = 0.0
    progress = tqdm(total=len(batches), desc=desc)
    for group in grouped_batches:
        group_grad = None
        group_grad_sq = None
        group_loss = 0.0
        group_weight = 0.0
        for batch in group:
            reference_weight = float(batch.get("reference_weight", 1.0))
            if reference_weight < 0:
                raise ValueError("reference weights must be nonnegative")
            if reference_weight == 0:
                progress.update(1)
                continue
            loss, grad = loss_grad_fn(weights, array_batch(batch))
            weighted_grad = scale_tree(grad, reference_weight)
            weighted_grad_sq = jax.tree_util.tree_map(
                lambda value: (
                    jnp.square(jnp.asarray(value, dtype=jnp.float32))
                    * jnp.asarray(reference_weight, dtype=jnp.float32)
                ),
                grad,
            )
            group_grad = (
                weighted_grad
                if group_grad is None
                else add_trees(group_grad, weighted_grad)
            )
            group_grad_sq = (
                weighted_grad_sq
                if group_grad_sq is None
                else add_trees(group_grad_sq, weighted_grad_sq)
            )
            group_loss += reference_weight * float(loss)
            group_weight += reference_weight
            progress.update(1)
        if group_grad is None or group_grad_sq is None or group_weight <= 0:
            progress.close()
            raise RuntimeError(
                "Fisher reference group produced no positive weight"
            )
        group_mean = divide_tree(group_grad, group_weight)
        group_fisher = divide_tree(group_grad_sq, group_weight)
        group_means.append(group_mean)
        total_grad = (
            group_grad
            if total_grad is None
            else add_trees(total_grad, group_grad)
        )
        total_loss += group_loss
        total_weight += group_weight
        if reduced_fisher is None:
            reduced_fisher = group_fisher
        elif curvature_group_reduction == "mean":
            reduced_fisher = add_trees(reduced_fisher, group_fisher)
        else:
            reduced_fisher = jax.tree_util.tree_map(
                jnp.maximum,
                reduced_fisher,
                group_fisher,
            )
    progress.close()
    if total_grad is None or reduced_fisher is None or total_weight <= 0:
        raise RuntimeError("Fisher reference accumulation failed")
    if curvature_group_reduction == "mean":
        reduced_fisher = divide_tree(reduced_fisher, len(group_means))
    return (
        divide_tree(total_grad, total_weight),
        group_means,
        reduced_fisher,
        total_loss / total_weight,
    )


def mean_reference_loss(
    weights: Any,
    batches: list[dict[str, Any]],
    loss_fn: Any,
    *,
    desc: str,
) -> float:
    """Evaluate a weighted reference mean without constructing gradients."""
    if not batches:
        return 0.0
    total_loss = 0.0
    total_weight = 0.0
    for batch in tqdm(
        batches,
        desc=desc,
        leave=False,
        disable=not desc,
    ):
        reference_weight = float(batch.get("reference_weight", 1.0))
        if reference_weight < 0:
            raise ValueError("reference weights must be nonnegative")
        if reference_weight == 0:
            continue
        total_loss += reference_weight * float(
            loss_fn(weights, array_batch(batch))
        )
        total_weight += reference_weight
    if total_weight <= 0:
        raise RuntimeError("reference loss produced no positive weight")
    return total_loss / total_weight


def _average_ranks(values: np.ndarray) -> np.ndarray:
    order = np.argsort(values, kind="mergesort")
    ranks = np.empty(len(values), dtype=np.float64)
    start = 0
    while start < len(values):
        end = start + 1
        while end < len(values) and values[order[end]] == values[order[start]]:
            end += 1
        ranks[order[start:end]] = 0.5 * (start + end - 1)
        start = end
    return ranks


def _spearman(values_a: np.ndarray, values_b: np.ndarray) -> float:
    if len(values_a) < 2:
        return 0.0
    ranks_a = _average_ranks(values_a)
    ranks_b = _average_ranks(values_b)
    if np.std(ranks_a) == 0 or np.std(ranks_b) == 0:
        return 0.0
    return float(np.corrcoef(ranks_a, ranks_b)[0, 1])


def summarize_quadratic_prediction_audit(
    rows: list[dict[str, float]],
) -> dict[str, float]:
    """Summarize finite-step prediction quality against anchor loss changes."""
    if not rows:
        raise ValueError("quadratic prediction audit produced no rows")
    first = np.asarray(
        [row["first_order_prediction"] for row in rows],
        dtype=np.float64,
    )
    quadratic = np.asarray(
        [row["quadratic_prediction"] for row in rows],
        dtype=np.float64,
    )
    actual_anchor = np.asarray(
        [row["actual_anchor_loss_change"] for row in rows],
        dtype=np.float64,
    )
    first_false_safe = (first <= 0) & (actual_anchor > 0)
    quadratic_false_safe = (quadratic <= 0) & (actual_anchor > 0)
    first_false_safe_count = int(np.sum(first_false_safe))
    caught = first_false_safe & (quadratic > 0)
    return {
        "prediction/first_order_mae": float(
            np.mean(np.abs(first - actual_anchor))
        ),
        "prediction/quadratic_mae": float(
            np.mean(np.abs(quadratic - actual_anchor))
        ),
        "prediction/first_order_spearman": _spearman(
            first,
            actual_anchor,
        ),
        "prediction/quadratic_spearman": _spearman(
            quadratic,
            actual_anchor,
        ),
        "prediction/first_order_sign_accuracy": float(
            np.mean((first > 0) == (actual_anchor > 0))
        ),
        "prediction/quadratic_sign_accuracy": float(
            np.mean((quadratic > 0) == (actual_anchor > 0))
        ),
        "prediction/first_order_false_safe_rate": float(
            np.mean(first_false_safe)
        ),
        "prediction/quadratic_false_safe_rate": float(
            np.mean(quadratic_false_safe)
        ),
        "prediction/quadratic_false_safe_recall": (
            float(np.sum(caught) / first_false_safe_count)
            if first_false_safe_count
            else 0.0
        ),
        "prediction/actual_anchor_loss_change": float(
            np.mean(actual_anchor)
        ),
        "prediction/actual_nonanchor_loss_change": float(
            np.mean(
                [
                    row["actual_nonanchor_loss_change"]
                    for row in rows
                ]
            )
        ),
        "prediction/actual_fullmastered_loss_change": float(
            np.mean(
                [
                    row["actual_fullmastered_loss_change"]
                    for row in rows
                ]
            )
        ),
    }


def current_target_exempt_lambda(args: argparse.Namespace, step_count: int) -> float:
    lam = float(args.target_exempt_lambda)
    if args.target_exempt_lambda_schedule == "constant":
        return lam
    if args.target_exempt_lambda_schedule == "linear_warmup":
        if args.target_exempt_lambda_warmup_steps <= 0:
            return lam
        return lam * min(
            1.0,
            float(max(step_count, 0)) / float(args.target_exempt_lambda_warmup_steps),
        )
    raise ValueError(f"unknown target-exempt lambda schedule: {args.target_exempt_lambda_schedule}")


def audit_opd_teacher(
    student_weights: Any,
    injection_batches: list[dict[str, Any]],
    teacher_batches: list[dict[str, Any]],
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    *,
    teacher_weights: Any | None = None,
    teacher_mode: str,
    answer_conditioned_mix: float,
    gold_tilt_beta: float,
) -> dict[str, float]:
    """Audit whether the nearby candidate teacher is corrective and policy-near."""
    if len(injection_batches) != len(teacher_batches):
        raise ValueError("OPD teacher audit batches must align with injection rows")
    if teacher_weights is None:
        teacher_weights = student_weights
    student_correct = 0
    conditioned_correct = 0
    correct = 0
    student_gold_probabilities = []
    conditioned_gold_probabilities = []
    gold_probabilities = []
    conditioned_policy_kls = []
    policy_kls = []
    for injection_batch, teacher_batch in tqdm(
        zip(injection_batches, teacher_batches),
        total=len(injection_batches),
        desc="audit OPD candidate teacher",
    ):
        student_logits = np.asarray(
            predict_logits_fn(student_weights, array_batch(injection_batch)),
            dtype=np.float32,
        )[cand_ids]
        target_index = "ABCD".index(injection_batch["label"])
        if teacher_mode == "answer_conditioned":
            conditioned_logits = np.asarray(
                predict_logits_fn(
                    teacher_weights,
                    array_batch(teacher_batch),
                ),
                dtype=np.float32,
            )[cand_ids]
            teacher_logits = student_logits + answer_conditioned_mix * (
                conditioned_logits - student_logits
            )
        elif teacher_mode == "gold_tilt":
            teacher_logits = student_logits.copy()
            teacher_logits[target_index] += gold_tilt_beta
            conditioned_logits = teacher_logits
        else:
            raise ValueError(f"unknown OPD teacher mode: {teacher_mode}")
        student_probabilities = stable_softmax(student_logits)
        conditioned_probabilities = stable_softmax(conditioned_logits)
        teacher_probabilities = stable_softmax(teacher_logits)
        student_correct += int(
            int(np.argmax(student_logits)) == target_index
        )
        conditioned_correct += int(
            int(np.argmax(conditioned_logits)) == target_index
        )
        correct += int(int(np.argmax(teacher_logits)) == target_index)
        student_gold_probabilities.append(
            float(student_probabilities[target_index])
        )
        conditioned_gold_probabilities.append(
            float(conditioned_probabilities[target_index])
        )
        gold_probabilities.append(float(teacher_probabilities[target_index]))
        conditioned_policy_kls.append(
            float(
                np.sum(
                    conditioned_probabilities
                    * (
                        np.log(
                            np.maximum(conditioned_probabilities, 1e-30)
                        )
                        - np.log(
                            np.maximum(student_probabilities, 1e-30)
                        )
                    )
                )
            )
        )
        policy_kls.append(
            float(
                np.sum(
                    teacher_probabilities
                    * (
                        np.log(np.maximum(teacher_probabilities, 1e-30))
                        - np.log(np.maximum(student_probabilities, 1e-30))
                    )
                )
            )
        )
    count = max(len(injection_batches), 1)
    return {
        "opd/teacher_audit_student_accuracy": student_correct / count,
        "opd/teacher_audit_student_gold_probability": float(
            np.mean(student_gold_probabilities)
            if student_gold_probabilities
            else 0.0
        ),
        "opd/teacher_audit_conditioned_accuracy": (
            conditioned_correct / count
        ),
        "opd/teacher_audit_conditioned_gold_probability": float(
            np.mean(conditioned_gold_probabilities)
            if conditioned_gold_probabilities
            else 0.0
        ),
        "opd/teacher_audit_conditioned_forward_kl": float(
            np.mean(conditioned_policy_kls)
            if conditioned_policy_kls
            else 0.0
        ),
        "opd/teacher_audit_accuracy": correct / count,
        "opd/teacher_audit_gold_probability": float(
            np.mean(gold_probabilities) if gold_probabilities else 0.0
        ),
        "opd/teacher_audit_forward_kl": float(
            np.mean(policy_kls) if policy_kls else 0.0
        ),
        "opd/teacher_audit_count": float(len(injection_batches)),
    }


def select_residual_injection_batches(
    weights: Any,
    injection_batches: list[dict[str, Any]],
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    *,
    artifact_path: str | Path,
    desc: str = "score residual injection set",
    metric_prefix: str = "sdft",
) -> tuple[list[dict[str, Any]], list[int], dict[str, float]]:
    """Keep original injection prompts the current policy still gets wrong."""
    residual_batches: list[dict[str, Any]] = []
    residual_indices: list[int] = []
    gold_probabilities: list[float] = []
    artifact_path = Path(artifact_path)
    artifact_path.parent.mkdir(parents=True, exist_ok=True)
    with open(artifact_path, "w", encoding="utf-8") as artifact_file:
        for index, batch in enumerate(tqdm(injection_batches, desc=desc)):
            candidate_logits = np.asarray(
                predict_logits_fn(weights, array_batch(batch)),
                dtype=np.float32,
            )[cand_ids]
            target_index = "ABCD".index(batch["label"])
            prediction_index = int(np.argmax(candidate_logits))
            probabilities = stable_softmax(candidate_logits)
            is_residual = prediction_index != target_index
            gold_probabilities.append(float(probabilities[target_index]))
            if is_residual:
                residual_batches.append(batch)
                residual_indices.append(index)
            write_jsonl_line(
                artifact_file,
                {
                    "base_example_index": index,
                    "question": batch.get("question", ""),
                    "label": batch["label"],
                    "prediction": "ABCD"[prediction_index],
                    "gold_probability": float(
                        probabilities[target_index]
                    ),
                    "residual": bool(is_residual),
                },
            )
    count = len(injection_batches)
    residual_count = len(residual_batches)
    return residual_batches, residual_indices, {
        f"{metric_prefix}/residual_count": float(residual_count),
        f"{metric_prefix}/residual_fraction": float(
            residual_count / max(count, 1)
        ),
        f"{metric_prefix}/supported_count": float(count - residual_count),
        f"{metric_prefix}/supported_fraction": float(
            (count - residual_count) / max(count, 1)
        ),
        f"{metric_prefix}/original_gold_probability_mean": float(
            np.mean(gold_probabilities) if gold_probabilities else 0.0
        ),
    }


def infer_batches(
    weights: Any,
    batches: list[dict[str, Any]],
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    path: str,
    desc: str,
    *,
    task_type: str = TASK_CATEGORICAL,
    candidate_labels: tuple[str, ...] = ("A", "B", "C", "D"),
    model: Any | None = None,
    greedy_fn: Callable[..., Any] | None = None,
    generation_eval_max_length: int = 512,
    generation_eval_max_new_tokens: int = 32,
    generation_eval_batch_size: int = 8,
    eval_loss_fn: Any | None = None,
) -> tuple[int, float, float]:
    ok = 0
    losses = []
    margins = []
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if task_type == TASK_GENERATION:
        if model is None or greedy_fn is None:
            raise ValueError("generation evaluation requires model and greedy_fn")
        predictions = greedy_task_predictions(
            model,
            weights,
            greedy_fn,
            batches,
            max_length=generation_eval_max_length,
            max_new_tokens=generation_eval_max_new_tokens,
            batch_size=generation_eval_batch_size,
            seed=0,
            desc=desc,
        )
    else:
        predictions = [None] * len(batches)
    with open(path, "w", encoding="utf-8") as f:
        iterator = zip(batches, predictions)
        if task_type == TASK_CATEGORICAL:
            iterator = tqdm(iterator, total=len(batches), desc=desc)
        for batch, generation_prediction in iterator:
            if task_type == TASK_GENERATION:
                pred = str(generation_prediction)
                target = str(batch["label"])
                ok += int(exact_answer_match(pred, target))
                loss = (
                    float(eval_loss_fn(weights, array_batch(batch)))
                    if eval_loss_fn is not None
                    else 0.0
                )
                margin = 0.0
                losses.append(loss)
                margins.append(margin)
                write_jsonl_line(
                    f,
                    {
                        "label": target,
                        "question": batch["question"],
                        "predict_label": pred,
                        "exact_match": bool(exact_answer_match(pred, target)),
                        "teacher_forced_loss": loss,
                    },
                )
                continue
            candidate_logits = np.asarray(
                predict_logits_fn(weights, array_batch(batch)),
                dtype=np.float32,
            )[cand_ids]
            predicted_index = int(np.argmax(candidate_logits))
            target_index = candidate_labels.index(batch["label"])
            pred = candidate_labels[predicted_index]
            ok += int(pred == batch["label"])
            probabilities = stable_softmax(candidate_logits)
            loss = -math.log(max(float(probabilities[target_index]), 1e-30))
            other_logits = np.delete(candidate_logits, target_index)
            margin = float(candidate_logits[target_index] - np.max(other_logits))
            losses.append(loss)
            margins.append(margin)
            write_jsonl_line(
                f,
                {
                    "label": batch["label"],
                    "question": batch["question"],
                    "predict_label": pred,
                    "candidate_ce_loss": loss,
                    "answer_margin": margin,
                },
            )
    return (
        ok,
        float(np.mean(losses) if losses else 0.0),
        float(np.mean(margins) if margins else 0.0),
    )


def infer_correct_batches(
    weights: Any,
    batches: list[dict[str, Any]],
    predict_logits_fn: Any,
    cand_ids: np.ndarray,
    path: str,
    desc: str,
    anchor_batch_ids: set[int],
    *,
    task_type: str = TASK_CATEGORICAL,
    candidate_labels: tuple[str, ...] = ("A", "B", "C", "D"),
    model: Any | None = None,
    greedy_fn: Callable[..., Any] | None = None,
    generation_eval_max_length: int = 512,
    generation_eval_max_new_tokens: int = 32,
    generation_eval_batch_size: int = 8,
) -> tuple[int, int, int, int, int]:
    """Evaluate all mastered rows and the real-anchor/non-anchor partitions in one pass."""
    all_ok = 0
    anchor_ok = 0
    non_anchor_ok = 0
    n_anchor = 0
    n_non_anchor = 0
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if task_type == TASK_GENERATION:
        if model is None or greedy_fn is None:
            raise ValueError("generation evaluation requires model and greedy_fn")
        predictions = greedy_task_predictions(
            model,
            weights,
            greedy_fn,
            batches,
            max_length=generation_eval_max_length,
            max_new_tokens=generation_eval_max_new_tokens,
            batch_size=generation_eval_batch_size,
            seed=0,
            desc=desc,
        )
    else:
        predictions = [None] * len(batches)
    with open(path, "w", encoding="utf-8") as f:
        iterator = zip(batches, predictions)
        if task_type == TASK_CATEGORICAL:
            iterator = tqdm(iterator, total=len(batches), desc=desc)
        for batch, generation_prediction in iterator:
            pred = (
                str(generation_prediction)
                if task_type == TASK_GENERATION
                else predict_candidate_label(
                    predict_logits_fn,
                    weights,
                    batch,
                    cand_ids,
                    candidate_labels,
                )
            )
            is_correct = int(
                exact_answer_match(pred, batch["label"])
                if task_type == TASK_GENERATION
                else pred == batch["label"]
            )
            is_anchor = id(batch) in anchor_batch_ids
            all_ok += is_correct
            if is_anchor:
                anchor_ok += is_correct
                n_anchor += 1
            else:
                non_anchor_ok += is_correct
                n_non_anchor += 1
            write_jsonl_line(
                f,
                {
                    "label": batch["label"],
                    "question": batch["question"],
                    "predict_label": pred,
                    "is_tiny_anchor": is_anchor,
                },
            )
    return all_ok, anchor_ok, non_anchor_ok, n_anchor, n_non_anchor


def configure_wandb_mode(mode: str | None) -> None:
    if mode:
        os.environ["WANDB_MODE"] = mode
    elif os.environ.get("WANDB_MODE") == "":
        os.environ.pop("WANDB_MODE", None)


def effective_method(args: argparse.Namespace) -> str:
    if args.method_name:
        return args.method_name
    if not args.use_freeze:
        return "sft"
    return "cnl_synth" if args.synthetic_correct_jsonl else "cnl"


