    if method == "cnl_anchor_icl_memory_route_ema":
        args.memory_collision_enabled = args.memory_route_gate == "collision"
        args.memory_routing_enabled = True
    if method == PROMPT_INVARIANT_FREE_ROUTE_METHOD:
        args.reference_reduction = "mean"
