    candidate_ids_jax = jnp.asarray(cand_ids, dtype=jnp.int32)
    causal_routing_activity_fn = None
    causal_routing_margin_fn = None
    if use_causal_activation_routing:
        causal_routing_activity_fn = jax.jit(
            lambda current_weights, batch: jnp.transpose(
                model.forward_with_circuit_components(
                    batch["tokens"],
                    current_weights,
                    batch["attention_mask"],
                    batch["last_idx"],
                )[1],
                (1, 0, 2),
            )
        )

        def causal_routing_margins(
            current_weights: Any,
            batch: dict[str, jax.Array],
            scale_bank: jax.Array,
        ) -> jax.Array:
            pattern_count = scale_bank.shape[0]
            example_count = batch["tokens"].shape[0]
            tokens = jnp.tile(batch["tokens"], (pattern_count, 1))
            last_idx = jnp.tile(batch["last_idx"], pattern_count)
            label_id = jnp.tile(batch["label_id"], pattern_count)
            mlp_scales = jnp.repeat(
                scale_bank,
                example_count,
                axis=0,
            )
            attention_scales = jnp.ones(
                (
                    pattern_count * example_count,
                    len(memory_layouts),
                    model.config["num_attention_heads"],
                ),
                dtype=jnp.float32,
            )
            logits = model.forward_with_circuit_scales(
                tokens,
                current_weights,
                last_idx,
                mlp_scales,
                attention_scales,
            )
            last_logits = logits.at[
                jnp.arange(logits.shape[0]), last_idx, :
            ].get(out_sharding=P("data", "model"))
            candidate_logits = last_logits.astype(jnp.float32).at[
                :, candidate_ids_jax
            ].get(out_sharding=P("data", None))
            target_index = jnp.argmax(
                candidate_ids_jax[None, :] == label_id[:, None],
                axis=-1,
            )
            margins = answer_margin(candidate_logits, target_index)
            return margins.reshape((pattern_count, example_count))

        causal_routing_margin_fn = jax.jit(causal_routing_margins)

    teacher_reference_loss_grad_fn = None
    teacher_reference_loss_fn = None
    ffn_teacher_reference_loss_grad_fn = None
    ffn_anchor_reference_loss_grad_fn = None
    if use_teacher_reference:
        teacher_reference_loss_fn = jax.jit(
            lambda w, batch: candidate_ce_loss_for_batch(
                forward,
                w,
                batch,
                candidate_ids_jax,
            )
        )
        teacher_reference_loss_grad_fn = jax.jit(
            jax.value_and_grad(
                lambda w, batch: candidate_ce_loss_for_batch(
                    forward,
                    w,
                    batch,
                    candidate_ids_jax,
                )
            )
        )
        if use_ffn_only_neuron_aligned_soft_cpl:
            ffn_paths = frozenset(ffn_parameter_paths(memory_layouts))

            def split_reference_weights(
                full_weights: dict[str, jax.Array],
            ) -> tuple[dict[str, jax.Array], dict[str, jax.Array]]:
                return (
                    select_ffn_parameters(full_weights, memory_layouts),
                    {
                        path: value
                        for path, value in full_weights.items()
                        if path not in ffn_paths
                    },
                )

            ffn_teacher_reference_core = jax.jit(
                jax.value_and_grad(
                    lambda ffn_weights, non_ffn_weights, batch: (
                        candidate_ce_loss_for_batch(
                            forward,
                            merge_ffn_parameters(
                                non_ffn_weights,
                                ffn_weights,
                            ),
                            batch,
                            candidate_ids_jax,
                        )
                    )
                )
            )
            ffn_anchor_reference_core = jax.jit(
                jax.value_and_grad(
                    lambda ffn_weights, non_ffn_weights, batch: (
                        loss_for_batch(
                            forward,
                            merge_ffn_parameters(
                                non_ffn_weights,
                                ffn_weights,
                            ),
                            batch,
                        )
                    )
                )
            )

            def ffn_teacher_reference_loss_grad_fn(
                full_weights: dict[str, jax.Array],
                batch: dict[str, jax.Array],
            ) -> tuple[jax.Array, dict[str, jax.Array]]:
                ffn_weights, non_ffn_weights = split_reference_weights(
                    full_weights
                )
                return ffn_teacher_reference_core(
                    ffn_weights,
                    non_ffn_weights,
                    batch,
                )

            def ffn_anchor_reference_loss_grad_fn(
                full_weights: dict[str, jax.Array],
                batch: dict[str, jax.Array],
            ) -> tuple[jax.Array, dict[str, jax.Array]]:
                ffn_weights, non_ffn_weights = split_reference_weights(
                    full_weights
                )
                return ffn_anchor_reference_core(
                    ffn_weights,
                    non_ffn_weights,
                    batch,
                )
    functional_trust_loss_grad_fn = None
    if use_any_functional_trust:
        functional_policy_loss = (
            frozen_teacher_candidate_reverse_kl_loss_for_batch
            if use_opd_mastered_policy
            and args.opd_mastered_policy_direction == "reverse"
            else frozen_teacher_candidate_kl_loss_for_batch
        )
        functional_policy_temperature = (
            args.opd_mastered_policy_temperature
            if use_opd_mastered_policy
            else args.functional_trust_region_temperature
        )
        functional_trust_loss_grad_fn = jax.jit(
            jax.value_and_grad(
                lambda w, batch: functional_policy_loss(
                    forward,
                    w,
                    batch,
                    candidate_ids_jax,
                    temperature=functional_policy_temperature,
                )
            )
        )
    functional_constraint_loss_grad_fn = None
    if use_functional_constraint_subspace:
        functional_constraint_loss_grad_fn = jax.jit(
            jax.value_and_grad(
                lambda w, batch: candidate_ce_loss_for_batch(
                    forward,
                    w,
                    batch,
                    candidate_ids_jax,
                )
            )
        )
    margin_budget_loss_grad_fn = None
    if use_margin_budget_projection:
        margin_budget_loss_grad_fn = jax.jit(
            jax.value_and_grad(
                lambda w, batch: candidate_margin_risk_for_batch(
                    forward,
                    w,
                    batch,
                    candidate_ids_jax,
                )
            )
        )

    functional_constraint_basis: tuple[Any, ...] = ()
    functional_constraint_gram_pinv = jnp.zeros(
        (0, 0),
        dtype=jnp.float32,
    )
    functional_subspace_build_stats: dict[str, float] = {}
    if use_functional_constraint_subspace:
        assert functional_constraint_loss_grad_fn is not None
        if not functional_constraint_batches:
            raise RuntimeError(
                "functional constraint subspace has no verified anchor views"
            )
        build_started = time.perf_counter()
        (
            functional_constraint_mean_grad,
            functional_constraint_group_grads,
            functional_constraint_reference_loss,
        ) = grouped_grad_correct(
            weights,
            functional_constraint_batches,
            functional_constraint_loss_grad_fn,
            groups=min(
                args.functional_subspace_groups,
                len(invariant_anchor_view_groups),
            ),
            desc="build prompt-invariant real-anchor functional subspace",
            group_assignments=functional_constraint_assignments,
            batch_size=args.reference_batch_size,
        )
        jax.block_until_ready(functional_constraint_group_grads)
        (
            functional_constraint_basis,
            functional_constraint_gram_pinv,
            functional_constraint_metadata,
        ) = prepare_functional_constraint_subspace(
            functional_constraint_group_grads,
            rcond=args.functional_subspace_rcond,
            eps=args.functional_subspace_eps,
        )
        jax.block_until_ready(
            (
                functional_constraint_basis,
                functional_constraint_gram_pinv,
            )
        )
        build_seconds = time.perf_counter() - build_started
        functional_subspace_build_stats = {
            "functional_subspace/requested_group_count": (
                functional_constraint_balance_stats[
                    "requested_group_count"
                ]
            ),
            "functional_subspace/effective_rank": float(
                functional_constraint_metadata["effective_rank"]
            ),
            "functional_subspace/dropped_zero_group_count": float(
                functional_constraint_metadata[
                    "dropped_zero_group_count"
                ]
            ),
            "functional_subspace/reference_family_count": (
                functional_constraint_balance_stats[
                    "reference_family_count"
                ]
            ),
            "functional_subspace/reference_view_count": (
                functional_constraint_balance_stats[
                    "reference_view_count"
                ]
            ),
            "functional_subspace/reference_loss": float(
                functional_constraint_reference_loss
            ),
            "functional_subspace/build_seconds": float(build_seconds),
            "functional_subspace/gram_eigenvalue_min": float(
                functional_constraint_metadata[
                    "gram_eigenvalue_min"
                ]
            ),
            "functional_subspace/gram_eigenvalue_max": float(
                functional_constraint_metadata[
                    "gram_eigenvalue_max"
                ]
            ),
            "functional_subspace/gram_condition": float(
                functional_constraint_metadata["gram_condition"]
            ),
            "functional_subspace/group_gradient_norm_min": float(
                functional_constraint_metadata[
                    "group_gradient_norm_min"
                ]
            ),
            "functional_subspace/group_gradient_norm_max": float(
                functional_constraint_metadata[
                    "group_gradient_norm_max"
                ]
            ),
            "functional_subspace/basis_refresh_count": 1.0,
        }
        functional_subspace_artifact = {
            "method": method,
            "reference_source": "real_anchors_only",
            "prompt_views": "frozen_teacher_verified",
            "family_reduction": "equal_weight_mean_across_retained_views",
            "grouping": "balanced_disjoint_anchor_families",
            "operator": "global_additive_update_nullspace_projection",
            "synthetic_reference": False,
            "cvar": False,
            "real_anchor_coordinate_veto": False,
            "mask_ema": False,
            "cross_view_count": args.cross_view_count,
            "strength": args.functional_subspace_strength,
            "max_projection_ratio": (
                args.functional_subspace_max_projection_ratio
            ),
            "reference_loss": float(
                functional_constraint_reference_loss
            ),
            "build_seconds": build_seconds,
            "balance": functional_constraint_balance_stats,
            "subspace": functional_constraint_metadata,
        }
        functional_subspace_path = (
            Path(args.out_dir)
            / "artifacts"
            / "prompt_invariant_functional_constraint_subspace.json"
        )
        functional_subspace_path.parent.mkdir(parents=True, exist_ok=True)
        functional_subspace_path.write_text(
            json.dumps(
                functional_subspace_artifact,
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
        del (
            functional_constraint_mean_grad,
            functional_constraint_group_grads,
        )
        print(
            "Prompt-invariant functional subspace:",
            f"families={len(invariant_anchor_view_groups)} "
            f"views={len(functional_constraint_batches)} "
            f"rank={functional_constraint_metadata['effective_rank']}/"
            f"{functional_constraint_metadata['active_group_count']} "
            f"seconds={build_seconds:.1f}",
        )
    margin_budget_basis: tuple[Any, ...] = ()
    margin_budget_coefficients = jnp.zeros((0, 0), dtype=jnp.float32)
    margin_budget_budgets = jnp.zeros((0,), dtype=jnp.float32)
    margin_budget_family_floors: dict[str, float] = {}
    margin_budget_build_stats: dict[str, float] = {}
    if use_margin_budget_projection:
        assert margin_budget_loss_grad_fn is not None
        if not invariant_anchor_view_groups:
            raise RuntimeError(
                "margin-budget projection has no verified anchor families"
            )
        family_batches: list[dict[str, jax.Array]] = []
        family_ids: list[str] = []
        initial_margins: list[float] = []
        for family in invariant_anchor_view_groups:
            views = list(family.get("views") or [])
            if not views:
                raise RuntimeError(
                    "margin-budget anchor family has no retained views"
                )
            weighted_views: list[dict[str, Any]] = []
            view_margins: list[float] = []
            for view in views:
                batch = dict(view["batch"])
                batch["reference_weight"] = 1.0 / len(views)
                weighted_views.append(batch)
                if "teacher_margin" in view:
                    view_margins.append(float(view["teacher_margin"]))
                else:
                    logits = np.asarray(
                        predict_logits_fn(weights, array_batch(batch)),
                        dtype=np.float32,
                    )[cand_ids]
                    target_index = int(view["view_target_index"])
                    view_margins.append(
                        float(
                            logits[target_index]
                            - np.max(np.delete(logits, target_index))
                        )
                    )
            family_batches.append(stack_reference_batches(weighted_views))
            family_ids.append(str(family["base_example_id"]))
            initial_margins.append(max(min(view_margins), 0.0))

        build_started = time.perf_counter()
        build_progress = tqdm(
            total=2 * len(family_batches),
            desc="build prompt-invariant real-anchor margin budgets",
        )

        def margin_gradient_for_family(family_index: int) -> Any:
            _, gradient = margin_budget_loss_grad_fn(
                weights,
                family_batches[family_index],
            )
            build_progress.update(1)
            return gradient

        try:
            (
                margin_budget_basis,
                margin_budget_coefficients,
                margin_budget_budgets,
                margin_budget_metadata,
            ) = prepare_margin_budget_subspace(
                margin_gradient_for_family,
                initial_margins=initial_margins,
                family_ids=family_ids,
                max_rank=args.margin_budget_rank,
                retain_fraction=args.margin_budget_retain_fraction,
                absolute_floor=args.margin_budget_absolute_floor,
                seed=args.tiny_anchor_seed,
                eps=args.margin_budget_eps,
            )
        finally:
            build_progress.close()
        jax.block_until_ready(
            (
                margin_budget_basis,
                margin_budget_coefficients,
                margin_budget_budgets,
            )
        )
        build_seconds = time.perf_counter() - build_started
        margin_budget_family_floors = dict(
            zip(
                margin_budget_metadata["family_ids"],
                margin_budget_metadata["margin_floors"],
            )
        )
        margin_budget_build_stats = {
            "margin_budget/reference_family_count": float(
                margin_budget_metadata["family_count"]
            ),
            "margin_budget/reference_view_count": float(
                sum(
                    len(family.get("views") or [])
                    for family in invariant_anchor_view_groups
                )
            ),
            "margin_budget/effective_rank": float(
                margin_budget_metadata["effective_rank"]
            ),
            "margin_budget/build_seconds": float(build_seconds),
            "margin_budget/gradient_evaluation_count": float(
                margin_budget_metadata["gradient_evaluation_count"]
            ),
            "margin_budget/initial_margin_mean": float(
                np.mean(initial_margins)
            ),
            "margin_budget/initial_margin_min": float(
                np.min(initial_margins)
            ),
            "margin_budget/budget_mean": float(
                np.mean(margin_budget_metadata["margin_budgets"])
            ),
            "margin_budget/budget_min": float(
                np.min(margin_budget_metadata["margin_budgets"])
            ),
            "margin_budget/captured_fraction_mean": float(
                margin_budget_metadata["captured_fraction_mean"]
            ),
            "margin_budget/captured_fraction_min": float(
                margin_budget_metadata["captured_fraction_min"]
            ),
            "margin_budget/captured_fraction_p10": float(
                margin_budget_metadata["captured_fraction_p10"]
            ),
        }
        margin_budget_artifact = {
            "method": method,
            "reference_source": "real_anchors_only",
            "prompt_views": "frozen_teacher_verified",
            "family_reduction": "mean_margin_risk_across_retained_views",
            "operator": "one_sided_cumulative_margin_budget",
            "compression": "two_pass_balanced_signed_hash_range_finder",
            "synthetic_reference": False,
            "cvar": False,
            "real_anchor_coordinate_veto": False,
            "mask_ema": False,
            "cross_view_count": args.cross_view_count,
            "projection_passes": args.margin_budget_projection_passes,
            "max_correction_ratio": (
                args.margin_budget_max_correction_ratio
            ),
            "build_seconds": build_seconds,
            "subspace": margin_budget_metadata,
        }
        margin_budget_path = (
            Path(args.out_dir)
            / "artifacts"
            / "prompt_invariant_margin_budget.json"
        )
        margin_budget_path.parent.mkdir(parents=True, exist_ok=True)
        margin_budget_path.write_text(
            json.dumps(
                margin_budget_artifact,
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
        del family_batches
        print(
            "Prompt-invariant margin budgets:",
            f"families={len(invariant_anchor_view_groups)} "
            f"rank={margin_budget_metadata['effective_rank']}/"
            f"{margin_budget_metadata['requested_rank']} "
            f"coverage="
            f"{margin_budget_metadata['captured_fraction_mean']:.3f} "
            f"seconds={build_seconds:.1f}",
        )
    causal_routing_neuron_gates = jnp.ones(
        (
            len(memory_layouts),
            memory_layouts[0].slot_count if memory_layouts else 0,
        ),
        dtype=jnp.float32,
    )
    causal_routing_build_stats: dict[str, float] = {}
    if use_causal_activation_routing:
        assert causal_routing_activity_fn is not None
        assert causal_routing_margin_fn is not None
        if not invariant_anchor_view_groups:
            raise RuntimeError(
                "causal activation routing has no verified anchor families"
            )
        if not memory_layouts:
            raise RuntimeError("causal activation routing has no FFN layout")
        ffn_widths = {layout.slot_count for layout in memory_layouts}
        if len(ffn_widths) != 1:
            raise ValueError(
                "causal activation routing requires a constant FFN width"
            )
        ffn_width = next(iter(ffn_widths))
        build_started = time.perf_counter()
        injection_probe_batches = select_circuit_probe_batches(
            wrong_batches,
            min(args.causal_routing_injection_count, len(wrong_batches)),
            args.synthetic_seed + args.tiny_anchor_seed * 1009,
        )
        injection_activities = collect_batched_ffn_activities(
            weights,
            injection_probe_batches,
            causal_routing_activity_fn,
            batch_size=args.causal_routing_audit_batch_size,
            desc="injection FFN activities",
        )
        injection_activity = np.quantile(
            injection_activities,
            args.causal_routing_injection_quantile,
            axis=0,
        )
        (
            anchor_family_activities,
            anchor_activity_stats,
        ) = collect_prompt_invariant_ffn_family_activities(
            weights,
            invariant_anchor_view_groups,
            causal_routing_activity_fn,
            batch_size=args.causal_routing_audit_batch_size,
        )
        (
            causal_candidate_indices,
            causal_candidate_strata,
            candidate_metadata,
        ) = select_causal_routing_candidates(
            injection_activity,
            anchor_family_activities,
            candidates_per_layer=(
                args.causal_routing_candidates_per_layer
            ),
            free_fraction=args.causal_routing_free_fraction,
            anchor_quantile=args.causal_routing_anchor_quantile,
        )
        causal_patterns = make_balanced_causal_ablation_patterns(
            len(causal_candidate_indices),
            args.causal_routing_pattern_count,
            args.synthetic_seed + args.tiny_anchor_seed * 2029,
        )
        causal_intervention_scales = materialize_causal_ablation_scales(
            causal_patterns,
            causal_candidate_indices,
            layer_count=len(memory_layouts),
            ffn_width=ffn_width,
            ablation_strength=args.causal_routing_ablation_strength,
        )
        (
            causal_family_margin_drops,
            causal_baseline_family_margins,
            causal_intervention_stats,
        ) = evaluate_causal_routing_interventions(
            weights,
            invariant_anchor_view_groups,
            causal_routing_margin_fn,
            causal_intervention_scales,
            pattern_batch_size=args.causal_routing_pattern_batch_size,
            audit_batch_size=args.causal_routing_audit_batch_size,
        )
        (
            causal_effects,
            causal_effect_stats,
        ) = estimate_prompt_invariant_causal_effects(
            causal_patterns,
            causal_family_margin_drops,
            confidence_z=args.causal_routing_confidence_z,
        )
        (
            causal_routing_neuron_gates_host,
            causal_gate_metadata,
        ) = build_causal_neuron_gates(
            causal_candidate_indices,
            causal_effects,
            layer_count=len(memory_layouts),
            ffn_width=ffn_width,
            min_gate=args.causal_routing_min_gate,
            strength=args.causal_routing_strength,
            min_family_fraction=(
                args.causal_routing_min_family_fraction
            ),
            min_effect=args.causal_routing_min_effect,
            scale_quantile=(
                args.causal_routing_effect_scale_quantile
            ),
        )
        gate_weight_sharding = weights[
            memory_layouts[0].gate_path
        ].sharding
        if isinstance(gate_weight_sharding, NamedSharding):
            causal_gate_sharding = NamedSharding(
                gate_weight_sharding.mesh,
                P(None, "model"),
            )
            causal_routing_neuron_gates = jax.device_put(
                causal_routing_neuron_gates_host,
                causal_gate_sharding,
            )
        else:
            causal_routing_neuron_gates = jnp.asarray(
                causal_routing_neuron_gates_host,
                dtype=jnp.float32,
            )
        jax.block_until_ready(causal_routing_neuron_gates)
        build_seconds = time.perf_counter() - build_started
        causal_routing_build_stats = {
            **anchor_activity_stats,
            **causal_intervention_stats,
            **causal_effect_stats,
            "causal_routing/injection_probe_count": float(
                len(injection_probe_batches)
            ),
            "causal_routing/candidate_count": float(
                len(causal_candidate_indices)
            ),
            "causal_routing/pattern_count": float(len(causal_patterns)),
            "causal_routing/protected_candidate_count": float(
                causal_gate_metadata["protected_candidate_count"]
            ),
            "causal_routing/protected_candidate_fraction": float(
                causal_gate_metadata["protected_candidate_fraction"]
            ),
            "causal_routing/candidate_gate_mean": float(
                causal_gate_metadata["candidate_gate_mean"]
            ),
            "causal_routing/candidate_gate_min": float(
                causal_gate_metadata["candidate_gate_min"]
            ),
            "causal_routing/whole_ffn_gate_mean": float(
                causal_gate_metadata["whole_ffn_gate_mean"]
            ),
            "causal_routing/build_seconds": float(build_seconds),
            "causal_routing/mastered_gradient_evaluation_count": 0.0,
        }
        causal_artifact_dir = Path(args.out_dir) / "artifacts"
        causal_artifact_dir.mkdir(parents=True, exist_ok=True)
        causal_arrays_path = (
            causal_artifact_dir / "causal_activation_routing_arrays.npz"
        )
        np.savez_compressed(
            causal_arrays_path,
            injection_activity=injection_activity,
            anchor_family_activities=anchor_family_activities,
            candidate_indices=causal_candidate_indices,
            patterns=causal_patterns,
            family_margin_drops=causal_family_margin_drops,
            baseline_family_margins=causal_baseline_family_margins,
            neuron_gates=causal_routing_neuron_gates_host,
            **causal_effects,
        )
        candidate_records = []
        for candidate_index, (layer_index, neuron_index) in enumerate(
            causal_candidate_indices
        ):
            candidate_records.append(
                {
                    "layer": int(memory_layouts[int(layer_index)].layer),
                    "layer_index": int(layer_index),
                    "neuron": int(neuron_index),
                    "stratum": causal_candidate_strata[candidate_index],
                    "selection_score": candidate_metadata[
                        "candidate_scores"
                    ][candidate_index],
                    "injection_activity_percentile": candidate_metadata[
                        "candidate_injection_percentiles"
                    ][candidate_index],
                    "anchor_activity_percentile": candidate_metadata[
                        "candidate_anchor_percentiles"
                    ][candidate_index],
                    "causal_effect_mean": float(
                        causal_effects["effect_mean"][candidate_index]
                    ),
                    "causal_effect_standard_error": float(
                        causal_effects["standard_error"][candidate_index]
                    ),
                    "causal_effect_lcb": float(
                        causal_effects[
                            "lower_confidence_bound"
                        ][candidate_index]
                    ),
                    "positive_anchor_family_fraction": float(
                        causal_effects[
                            "positive_family_fraction"
                        ][candidate_index]
                    ),
                    "gate": causal_gate_metadata["candidate_gates"][
                        candidate_index
                    ],
                    "protected": causal_gate_metadata["protected_mask"][
                        candidate_index
                    ],
                }
            )
        causal_artifact = {
            "method": method,
            "estimand": (
                "randomized marginal effect of FFN coefficient co-ablation "
                "on worst-view real-anchor gold margin"
            ),
            "reference_source": "real_anchors_only",
            "prompt_views": "frozen_teacher_verified",
            "mask_estimator": "forward_only_causal_intervention",
            "masked_unit": (
                "one coherent gate_proj row, up_proj row, and down_proj column"
            ),
            "non_ffn_updates": "unchanged",
            "unconfirmed_ffn_updates": "unchanged",
            "synthetic_reference": False,
            "cvar": False,
            "real_anchor_gradient_veto": False,
            "mask_ema": False,
            "mastered_set_backpropagation": False,
            "configuration": {
                "cross_view_count": args.cross_view_count,
                "injection_count": args.causal_routing_injection_count,
                "injection_quantile": (
                    args.causal_routing_injection_quantile
                ),
                "candidates_per_layer": (
                    args.causal_routing_candidates_per_layer
                ),
                "free_fraction": args.causal_routing_free_fraction,
                "anchor_quantile": (
                    args.causal_routing_anchor_quantile
                ),
                "pattern_count": args.causal_routing_pattern_count,
                "ablation_strength": (
                    args.causal_routing_ablation_strength
                ),
                "confidence_z": args.causal_routing_confidence_z,
                "min_family_fraction": (
                    args.causal_routing_min_family_fraction
                ),
                "min_effect": args.causal_routing_min_effect,
                "effect_scale_quantile": (
                    args.causal_routing_effect_scale_quantile
                ),
                "min_gate": args.causal_routing_min_gate,
                "strength": args.causal_routing_strength,
            },
            "candidate_selection": candidate_metadata,
            "causal_gate": causal_gate_metadata,
            "build_stats": causal_routing_build_stats,
            "anchor_family_ids": [
                str(group["base_example_id"])
                for group in invariant_anchor_view_groups
            ],
            "candidate_records": candidate_records,
            "arrays_path": str(causal_arrays_path),
        }
        causal_artifact_path = (
            causal_artifact_dir
            / "prompt_invariant_causal_activation_routing.json"
        )
        causal_artifact_path.write_text(
            json.dumps(causal_artifact, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        del (
            injection_activities,
            anchor_family_activities,
            causal_intervention_scales,
        )
        print(
            "Prompt-invariant causal activation routing:",
            f"probes={len(injection_probe_batches)} "
            f"families={len(invariant_anchor_view_groups)} "
            f"candidates={len(causal_candidate_indices)} "
            f"protected="
            f"{causal_gate_metadata['protected_candidate_count']} "
            f"seconds={build_seconds:.1f}",
        )
    real_replay_loss_grad_fn = None
    if use_real_functional_replay:
        real_replay_loss_grad_fn = jax.jit(
            jax.value_and_grad(
                lambda w, batch: frozen_teacher_candidate_kl_loss_for_batch(
                    forward,
                    w,
                    batch,
                    candidate_ids_jax,
                    temperature=args.real_replay_temperature,
                )
            )
        )
    opd_loss_grad_fn = None
    if use_support_then_opd:
        opd_loss_grad_fn = jax.value_and_grad(
            lambda student, teacher, batch, teacher_batch, rewrite_batch, ce_weight: (
                support_then_opd_loss_for_batch(
                    forward,
                    student,
                    teacher,
                    batch,
                    teacher_batch,
                    rewrite_batch,
                    candidate_ids_jax,
                    ce_weight=ce_weight,
                    distill_weight=args.opd_distill_weight,
                    rewrite_ce_weight=args.opd_rewrite_ce_weight,
                    rewrite_js_weight=args.opd_rewrite_js_weight,
                    distill_temperature=args.opd_distill_temperature,
                    rewrite_temperature=args.opd_rewrite_temperature,
                    teacher_mode=args.opd_teacher_mode,
                    answer_conditioned_mix=args.opd_answer_conditioned_mix,
                    gold_tilt_beta=args.opd_gold_tilt_beta,
                )
            ),
            has_aux=True,
        )
    sdft_support_loss_grad_fn = None
    if use_sdft_residual_cnl:
        sdft_support_loss_grad_fn = jax.value_and_grad(
            lambda student, teacher, batch, teacher_batch: (
                sdft_support_loss_for_batch(
                    forward,
                    student,
                    teacher,
                    batch,
                    teacher_batch,
                    candidate_ids_jax,
                    kl_direction=args.sdft_kl_direction,
                    temperature=args.sdft_temperature,
                    answer_conditioned_mix=(
                        args.sdft_answer_conditioned_mix
                    ),
                )
            ),
            has_aux=True,
        )
    ppmt_midtrain_loss_grad_fn = None
    if use_ppmt_residual_cnl:
        ppmt_midtrain_loss_grad_fn = jax.value_and_grad(
            lambda w, midtrain_batch, injection_batch, memory_batch, source: (
                policy_preserving_midtrain_loss_for_batch(
                    forward,
                    w,
                    midtrain_batch,
                    injection_batch,
                    memory_batch,
                    candidate_ids_jax,
                    injection_kl_weight=(
                        args.ppmt_injection_kl_weight
                    ),
                    memory_kl_weight=args.ppmt_memory_kl_weight,
                    temperature=args.ppmt_kl_temperature,
                    reference_is_anchor=source,
                )
            ),
            has_aux=True,
        )
    paem_world_loss_grad_fn = None
    if use_paem_candidate_policy:
        paem_world_loss_grad_fn = jax.value_and_grad(
            lambda w, outcome_batch, injection_batch, memory_batch, source: (
                paem_world_loss_for_batch(
                    forward,
                    w,
                    outcome_batch,
                    injection_batch,
                    memory_batch,
                    candidate_ids_jax,
                    injection_kl_weight=(
                        args.paem_injection_kl_weight
                    ),
                    memory_kl_weight=args.paem_memory_kl_weight,
                    temperature=args.paem_kl_temperature,
                    reference_is_anchor=source,
                )
            ),
            has_aux=True,
        )
    support_gated_loss_grad_fn = None
    if use_support_gated_on_policy:
        support_gated_loss_grad_fn = jax.value_and_grad(
            lambda w, batch, route: (
                support_gated_on_policy_loss_for_batch(
                    forward,
                    w,
                    batch,
                    candidate_ids_jax,
                    use_on_policy=route,
                    probability_power=(
                        args.support_gate_on_policy_power
                    ),
                )
            ),
            has_aux=True,
        )

    dual_circuit: dict[str, jax.Array] = {}
    dual_circuit_host: dict[str, np.ndarray] = {}
    dual_circuit_artifact: dict[str, Any] = {}
    base_circuit_stats: dict[str, float] = {}
    if use_dual_circuit:
        layer_count = len(dual_circuit_layouts)
        mlp_widths = {layout.intermediate_size for layout in dual_circuit_layouts}
        attention_widths = {layout.query_head_count for layout in dual_circuit_layouts}
        if len(mlp_widths) != 1 or len(attention_widths) != 1:
            raise ValueError(
                "stacked circuit attribution requires constant component widths"
            )
        mlp_width = next(iter(mlp_widths))
        attention_width = next(iter(attention_widths))
        mlp_scale_ones = jnp.ones(
            (1, layer_count, mlp_width),
            dtype=jnp.float32,
        )
        attention_scale_ones = jnp.ones(
            (1, layer_count, attention_width),
            dtype=jnp.float32,
        )

        def margin_with_circuit_scales(
            mlp_scales: jax.Array,
            attention_scales: jax.Array,
            current_weights: Any,
            batch: dict[str, jax.Array],
        ) -> jax.Array:
            logits = model.forward_with_circuit_scales(
                batch["tokens"],
                current_weights,
                batch["last_idx"],
                mlp_scales,
                attention_scales,
            )
            last_logits = logits.at[
                jnp.arange(logits.shape[0]), batch["last_idx"], :
            ].get(out_sharding=P("data", "model"))
            candidates = last_logits.astype(jnp.float32).at[
                :, candidate_ids_jax
            ].get(out_sharding=P("data", None))
            target_index = jnp.argmax(
                candidate_ids_jax[None, :] == batch["label_id"][:, None],
                axis=-1,
            )
            return answer_margin(candidates, target_index).mean()

        circuit_margin_fn = jax.jit(margin_with_circuit_scales)
        circuit_attribution_fn = jax.jit(
            jax.value_and_grad(
                margin_with_circuit_scales,
                argnums=(0, 1),
            )
        )
        circuit_activation_fn = jax.jit(
            lambda current_weights, batch: model.forward_with_circuit_components(
                batch["tokens"],
                current_weights,
                batch["attention_mask"],
                batch["last_idx"],
            )[1:]
        )

        synthetic_attribution_batches = (
            crossfit_discovery_batches
            if use_synthetic_prompt_circuit
            else select_circuit_probe_batches(
                correct_ref_batches,
                min(
                    args.circuit_synth_attribution_count,
                    len(correct_ref_batches),
                ),
                args.synthetic_seed + args.tiny_anchor_seed * 1009,
            )
        )
        real_view_count = (
            0
            if use_synthetic_prompt_circuit
            else 1
            if method == SINGLE_PROMPT_DUAL_CIRCUIT_METHOD
            else args.circuit_real_view_count
        )
        synthetic_view_count = (
            1
            if method == SINGLE_PROMPT_DUAL_CIRCUIT_METHOD
            else args.circuit_synth_view_count
        )
        circuit_artifact_dir = Path(args.out_dir) / "artifacts"
        real_view_groups: list[dict[str, Any]] = []
        real_view_stats: dict[str, float] = {
            "base_count": 0.0,
            "requested_view_count": 0.0,
            "retained_view_count": 0.0,
            "rejected_view_count": 0.0,
            "teacher_invariance_rate": 0.0,
            "views_per_example_mean": 0.0,
        }
        if not use_synthetic_prompt_circuit:
            real_view_groups, real_view_stats = build_circuit_prompt_view_groups(
                tiny_anchor_batches,
                model.tokenizer,
                weights,
                predict_logits_fn,
                cand_ids,
                args.max_length,
                view_count=real_view_count,
                seed=args.tiny_anchor_seed,
                source="real",
                artifact_path=circuit_artifact_dir / "real_prompt_views.jsonl",
            )
        synthetic_view_groups, synthetic_view_stats = (
            build_circuit_prompt_view_groups(
                synthetic_attribution_batches,
                model.tokenizer,
                weights,
                predict_logits_fn,
                cand_ids,
                args.max_length,
                view_count=synthetic_view_count,
                seed=args.synthetic_seed + args.tiny_anchor_seed * 1009,
                source="synthetic",
                artifact_path=circuit_artifact_dir / "synthetic_prompt_views.jsonl",
            )
        )
        circuit_replication_view_groups: list[dict[str, Any]] = []
        circuit_replication_view_stats: dict[str, float] = {}
        if circuit_replication_batches:
            (
                circuit_replication_view_groups,
                circuit_replication_view_stats,
            ) = build_circuit_prompt_view_groups(
                circuit_replication_batches,
                model.tokenizer,
                weights,
                predict_logits_fn,
                cand_ids,
                args.max_length,
                view_count=synthetic_view_count,
                seed=args.synthetic_seed + args.tiny_anchor_seed * 1009 + 104729,
                source="synthetic_replication",
                artifact_path=(
                    circuit_artifact_dir
                    / "circuit_replication_prompt_views.jsonl"
                ),
            )
        crossfit_audit_view_groups: list[dict[str, Any]] = []
        crossfit_audit_view_stats: dict[str, float] = {}
        if use_synthetic_prompt_circuit:
            (
                crossfit_audit_view_groups,
                crossfit_audit_view_stats,
            ) = build_circuit_prompt_view_groups(
                crossfit_audit_batches,
                model.tokenizer,
                weights,
                predict_logits_fn,
                cand_ids,
                args.max_length,
                view_count=synthetic_view_count,
                seed=(
                    args.synthetic_seed
                    + args.tiny_anchor_seed * 1009
                    + 2 * 104729
                ),
                source="synthetic_audit",
                artifact_path=(
                    circuit_artifact_dir / "crossfit_audit_prompt_views.jsonl"
                ),
            )
        if not synthetic_view_groups:
            raise ValueError(
                "dual-circuit attribution retained no teacher-invariant synthetic views"
            )
        if use_synthetic_prompt_circuit and not crossfit_audit_view_groups:
            raise ValueError(
                "cross-fit circuit retained no teacher-invariant held-out audit views"
            )
        if circuit_replication_batches and not circuit_replication_view_groups:
            raise ValueError(
                "circuit rediscovery retained no teacher-invariant prompt views"
            )
        if not use_synthetic_prompt_circuit and not real_view_groups:
            raise ValueError("dual-circuit attribution retained no teacher-invariant views")

        cache_config = {
            "model_name": args.model_name,
            "real_fingerprint": (
                ""
                if use_synthetic_prompt_circuit
                else reference_batches_fingerprint(tiny_anchor_batches)
            ),
            "synthetic_fingerprint": reference_batches_fingerprint(
                synthetic_attribution_batches
            ),
            "real_view_count": real_view_count,
            "synthetic_view_count": synthetic_view_count,
            "prompt_consistency_threshold": args.circuit_prompt_consistency_threshold,
            "mlp_top_fraction": args.circuit_mlp_top_fraction,
            "attention_top_fraction": args.circuit_attention_top_fraction,
            "attribution": args.circuit_attribution,
            "attribution_sign": args.circuit_attribution_sign,
        }
        if use_synthetic_prompt_circuit:
            cache_config.update(
                {
                    "circuit_kind": (
                        "crossfit_ffn_value"
                        if use_crossfit_ffn_value
                        else "cached_source_balanced_output_circuit"
                        if use_cached_source_balanced_circuit
                        else "circuit_local_soft_family_screen"
                        if use_circuit_local_soft_projection
                        else "prompt_invariant_circuit_veto"
                    ),
                    "audit_fingerprint": reference_batches_fingerprint(
                        crossfit_audit_batches
                    ),
                    "guard_fingerprint": reference_batches_fingerprint(
                        synthetic_constraint_batches
                    ),
                }
            )
            if circuit_replication_batches:
                cache_config["replication_fingerprint"] = (
                    reference_batches_fingerprint(circuit_replication_batches)
                )
        cache_fingerprint = hashlib.sha256(
            json.dumps(cache_config, sort_keys=True).encode("utf-8")
        ).hexdigest()
        circuit_cache_path = (
            Path(args.circuit_cache_path).expanduser()
            if args.circuit_cache_path
            else circuit_artifact_dir / "dual_circuit_support_cache.npz"
        )
        support_metadata: dict[str, Any]
        if circuit_cache_path.exists() and args.circuit_cache_refresh == "never":
            support_cache, support_metadata = load_dual_circuit_cache(
                circuit_cache_path
            )
            cached_fingerprint = support_metadata.get("summary", {}).get(
                "cache_fingerprint"
            )
            if cached_fingerprint != cache_fingerprint:
                raise ValueError(
                    "dual-circuit cache was built from a different model/probe/view configuration"
                )
            print(f"Dual circuit cache : {circuit_cache_path} (loaded)")
        else:
            synthetic_support, synthetic_support_stats = (
                estimate_prompt_circuit_support(
                    weights,
                    synthetic_view_groups,
                    circuit_attribution_fn,
                    circuit_activation_fn,
                    mlp_scale_ones,
                    attention_scale_ones,
                    mlp_top_fraction=args.circuit_mlp_top_fraction,
                    attention_top_fraction=args.circuit_attention_top_fraction,
                    consistency_threshold=args.circuit_prompt_consistency_threshold,
                    sign_mode=args.circuit_attribution_sign,
                    attribution_mode=args.circuit_attribution,
                    desc="synthetic prompt-consistent circuit attribution",
                )
            )
            replication_support: dict[str, np.ndarray] = {}
            replication_support_stats: dict[str, float] = {}
            if circuit_replication_view_groups:
                (
                    replication_support,
                    replication_support_stats,
                ) = estimate_prompt_circuit_support(
                    weights,
                    circuit_replication_view_groups,
                    circuit_attribution_fn,
                    circuit_activation_fn,
                    mlp_scale_ones,
                    attention_scale_ones,
                    mlp_top_fraction=args.circuit_mlp_top_fraction,
                    attention_top_fraction=args.circuit_attention_top_fraction,
                    consistency_threshold=(
                        args.circuit_prompt_consistency_threshold
                    ),
                    sign_mode=args.circuit_attribution_sign,
                    attribution_mode=args.circuit_attribution,
                    desc="disjoint circuit rediscovery attribution",
                )
            if use_synthetic_prompt_circuit:
                real_support = {
                    name: np.zeros_like(value)
                    for name, value in synthetic_support.items()
                }
                real_support_stats: dict[str, float] = {}
            else:
                real_support, real_support_stats = estimate_prompt_circuit_support(
                    weights,
                    real_view_groups,
                    circuit_attribution_fn,
                    circuit_activation_fn,
                    mlp_scale_ones,
                    attention_scale_ones,
                    mlp_top_fraction=args.circuit_mlp_top_fraction,
                    attention_top_fraction=args.circuit_attention_top_fraction,
                    consistency_threshold=args.circuit_prompt_consistency_threshold,
                    sign_mode=args.circuit_attribution_sign,
                    attribution_mode=args.circuit_attribution,
                    desc="real prompt-consistent circuit attribution",
                )
            support_cache = {
                "synthetic_mlp_support": synthetic_support["mlp_support"],
                "real_mlp_support": real_support["mlp_support"],
                "synthetic_attention_support": synthetic_support[
                    "attention_support"
                ],
                "real_attention_support": real_support["attention_support"],
                "synthetic_mlp_activation": synthetic_support["mlp_activation"],
                "real_mlp_activation": real_support["mlp_activation"],
                "synthetic_attention_activation": synthetic_support[
                    "attention_activation"
                ],
                "real_attention_activation": real_support["attention_activation"],
            }
            if replication_support:
                support_cache.update(
                    {
                        "replication_mlp_support": replication_support[
                            "mlp_support"
                        ],
                        "replication_attention_support": replication_support[
                            "attention_support"
                        ],
                        "replication_mlp_activation": replication_support[
                            "mlp_activation"
                        ],
                        "replication_attention_activation": replication_support[
                            "attention_activation"
                        ],
                    }
                )
            ig_stats: dict[str, Any] = {}
            if args.circuit_ig_audit:
                if not use_synthetic_prompt_circuit:
                    ig_stats["real"] = run_circuit_ig_audit(
                        weights,
                        real_view_groups,
                        circuit_attribution_fn,
                        circuit_margin_fn,
                        mlp_scale_ones,
                        attention_scale_ones,
                        steps=args.circuit_ig_steps,
                        count=min(args.circuit_ig_real_count, len(real_view_groups)),
                        desc="real circuit IG audit",
                    )
                ig_stats["synthetic"] = run_circuit_ig_audit(
                    weights,
                    synthetic_view_groups,
                    circuit_attribution_fn,
                    circuit_margin_fn,
                    mlp_scale_ones,
                    attention_scale_ones,
                    steps=args.circuit_ig_steps,
                    count=min(
                        args.circuit_ig_synth_count,
                        len(synthetic_view_groups),
                    ),
                    desc="synthetic circuit IG audit",
                )
            prompt_view_metadata = {
                "real": real_view_stats,
                "synthetic": synthetic_view_stats,
            }
            if use_synthetic_prompt_circuit:
                prompt_view_metadata["heldout_synthetic_audit"] = (
                    crossfit_audit_view_stats
                )
            if circuit_replication_view_groups:
                prompt_view_metadata["synthetic_replication"] = (
                    circuit_replication_view_stats
                )
            support_metadata = {
                "method": (
                    "frozen cross-fit synthetic FFN value support"
                    if use_crossfit_ffn_value
                    else "frozen prompt-invariant synthetic output circuit support"
                    if (
                        use_cached_source_balanced_circuit
                        or use_circuit_local_soft_projection
                    )
                    else "frozen prompt-invariant synthetic FFN value support"
                    if use_synthetic_prompt_circuit
                    else "frozen prompt-consistent dual-circuit support"
                ),
                "summary": {
                    "cache_fingerprint": cache_fingerprint,
                    **cache_config,
                },
                "prompt_views": prompt_view_metadata,
                "attribution": {
                    "real": real_support_stats,
                    "synthetic": synthetic_support_stats,
                    "replication": replication_support_stats,
                    "gradient_magnitude_note": (
                        "activation-normalized component-scale gradient proxy"
                        if args.circuit_attribution == "gradient_magnitude"
                        else ""
                    ),
                },
                "integrated_gradients_audit": ig_stats,
            }
            save_dual_circuit_cache(
                circuit_cache_path,
                support_cache,
                support_metadata,
            )
            print(f"Dual circuit cache : {circuit_cache_path} (estimated)")

        enable_mlp = method != ATTENTION_CIRCUIT_METHOD
        enable_attention = method != FFN_CIRCUIT_METHOD
        real_completion = method != DUAL_CIRCUIT_NO_REAL_COMPLETION_METHOD
        if use_synthetic_prompt_circuit:
            enable_mlp = (
                use_cached_source_balanced_circuit
                or circuit_local_soft_family == "ffn"
                or not use_circuit_local_soft_projection
            )
            enable_attention = (
                use_cached_source_balanced_circuit
                or circuit_local_soft_family == "attention"
            )
            real_completion = False
            if (
                use_cached_source_balanced_circuit
                or use_circuit_local_soft_projection
            ):
                dual_circuit_host, circuit_map_metadata = (
                    build_prompt_invariant_output_circuit(
                        support_cache["synthetic_mlp_support"],
                        support_cache["synthetic_attention_support"],
                        mlp_threshold=args.circuit_synthetic_threshold,
                        attention_threshold=args.circuit_synthetic_threshold,
                        enable_mlp=enable_mlp,
                        enable_attention=enable_attention,
                    )
                )
            else:
                dual_circuit_host, circuit_map_metadata = (
                    build_crossfit_ffn_value_circuit(
                        support_cache["synthetic_mlp_support"],
                        (layer_count, attention_width),
                        threshold=args.circuit_synthetic_threshold,
                    )
                )
            mlp_activation = support_cache["synthetic_mlp_activation"]
            attention_activation = support_cache[
                "synthetic_attention_activation"
            ]
        else:
            dual_circuit_host, circuit_map_metadata = build_dual_circuit_map(
                support_cache["synthetic_mlp_support"],
                support_cache["real_mlp_support"],
                support_cache["synthetic_attention_support"],
                support_cache["real_attention_support"],
                synthetic_threshold=args.circuit_synthetic_threshold,
                real_threshold=args.circuit_real_threshold,
                core_strength=args.circuit_core_strength,
                synthetic_only_strength=args.circuit_synth_only_strength,
                real_residual_strength=args.circuit_real_residual_strength,
                real_completion=real_completion,
                enable_mlp=enable_mlp,
                enable_attention=enable_attention,
            )
            mlp_activation = 0.5 * (
                support_cache["synthetic_mlp_activation"]
                + support_cache["real_mlp_activation"]
            )
            attention_activation = 0.5 * (
                support_cache["synthetic_attention_activation"]
                + support_cache["real_attention_activation"]
            )
        rediscovery_stats: dict[str, float] = {}
        if circuit_replication_batches:
            for family in ("mlp", "attention"):
                comparison = compare_circuit_support_maps(
                    support_cache[f"synthetic_{family}_support"],
                    support_cache[f"replication_{family}_support"],
                    threshold=args.circuit_synthetic_threshold,
                )
                rediscovery_stats.update(
                    {
                        f"rediscovery_{family}_{key}": float(value)
                        for key, value in comparison.items()
                    }
                )
        causal_stats: dict[str, float] = {}
        if args.circuit_causal_validation:
            causal_groups = (
                crossfit_audit_view_groups
                if use_synthetic_prompt_circuit
                else (
                    real_view_groups[: args.circuit_causal_real_count]
                    + synthetic_view_groups[: args.circuit_causal_synth_count]
                )
            )
            causal_stats = evaluate_circuit_causal_specificity(
                weights,
                causal_groups,
                circuit_margin_fn,
                dual_circuit_host,
                mlp_activation,
                attention_activation,
                mlp_scale_ones,
                attention_scale_ones,
                count=len(causal_groups),
                random_repeats=args.circuit_causal_random_repeats,
                bootstrap_repeats=args.circuit_causal_bootstrap_repeats,
                full_audit=args.circuit_causal_full_audit,
                seed=args.tiny_anchor_seed + args.synthetic_seed * 1009,
                desc=(
                    "held-out cross-fit FFN value causal audit"
                    if use_crossfit_ffn_value
                    else "held-out prompt-invariant output circuit causal audit"
                    if (
                        use_cached_source_balanced_circuit
                        or use_circuit_local_soft_projection
                    )
                    else "held-out prompt-invariant FFN value causal audit"
                    if use_prompt_invariant_circuit_veto
                    else "dual-circuit causal suppression audit"
                ),
                artifact_path=(
                    circuit_artifact_dir / "causal_intervention_records.jsonl"
                ),
            )
            failed_families = []
            if enable_mlp:
                if np.any(dual_circuit_host["mlp_weight"] > 0):
                    if use_synthetic_prompt_circuit and (
                        causal_stats["causal_mlp_top_margin_drop"] <= 0
                    ):
                        failed_families.append("MLP nonpositive held-out effect")
                    if (
                        causal_stats["causal_mlp_specificity_ratio"]
                        < args.circuit_causal_min_ratio
                    ):
                        failed_families.append(
                            "MLP held-out specificity"
                            if use_synthetic_prompt_circuit
                            else "MLP"
                        )
                elif use_synthetic_prompt_circuit:
                    failed_families.append("empty MLP value circuit")
            if enable_attention:
                if np.any(dual_circuit_host["attention_weight"] > 0):
                    if (
                        causal_stats["causal_attention_specificity_ratio"]
                        < args.circuit_causal_min_ratio
                    ):
                        failed_families.append("attention")
                elif use_synthetic_prompt_circuit:
                    failed_families.append("empty attention V/O circuit")
            if failed_families and args.circuit_causal_enforce:
                raise RuntimeError(
                    "circuit causal gate failed for "
                    + ", ".join(failed_families)
                    + f" (required ratio={args.circuit_causal_min_ratio:g}); "
                    "inspect the frozen audit before launching training"
                )

        map_summary = circuit_map_metadata["summary"]
        support_attribution = support_metadata.get("attribution", {})
        synthetic_attribution_stats = support_attribution.get("synthetic", {})
        real_attribution_stats = support_attribution.get("real", {})
        if use_synthetic_prompt_circuit:
            mlp_consistency_mean = (
                synthetic_attribution_stats.get(
                    "mlp_prompt_consistency_mean",
                    0.0,
                )
                if enable_mlp
                else 0.0
            )
            attention_consistency_mean = (
                synthetic_attribution_stats.get(
                    "attention_prompt_consistency_mean",
                    0.0,
                )
                if enable_attention
                else 0.0
            )
            mlp_stable_fraction = (
                synthetic_attribution_stats.get(
                    "mlp_stable_fraction",
                    0.0,
                )
                if enable_mlp
                else 0.0
            )
            attention_stable_fraction = (
                synthetic_attribution_stats.get(
                    "attention_stable_fraction",
                    0.0,
                )
                if enable_attention
                else 0.0
            )
        else:
            mlp_consistency_mean = 0.5 * (
                synthetic_attribution_stats.get(
                    "mlp_prompt_consistency_mean", 0.0
                )
                + real_attribution_stats.get("mlp_prompt_consistency_mean", 0.0)
            )
            attention_consistency_mean = 0.5 * (
                synthetic_attribution_stats.get(
                    "attention_prompt_consistency_mean", 0.0
                )
                + real_attribution_stats.get(
                    "attention_prompt_consistency_mean", 0.0
                )
            )
            mlp_stable_fraction = 0.5 * (
                synthetic_attribution_stats.get("mlp_stable_fraction", 0.0)
                + real_attribution_stats.get("mlp_stable_fraction", 0.0)
            )
            attention_stable_fraction = 0.5 * (
                synthetic_attribution_stats.get(
                    "attention_stable_fraction", 0.0
                )
                + real_attribution_stats.get(
                    "attention_stable_fraction", 0.0
                )
            )
        base_circuit_stats = {
            "circuit/mlp_component_count": float(map_summary["mlp_component_count"]),
            "circuit/attention_component_count": float(
                map_summary["attention_component_count"]
            ),
            "circuit/mlp_prompt_consistency_mean": float(mlp_consistency_mean),
            "circuit/attention_prompt_consistency_mean": float(
                attention_consistency_mean
            ),
            "circuit/mlp_stable_fraction": float(mlp_stable_fraction),
            "circuit/attention_stable_fraction": float(
                attention_stable_fraction
            ),
            "circuit/synthetic_core_fraction": float(
                map_summary["synthetic_core_fraction"]
            ),
            "circuit/synthetic_only_fraction": float(
                map_summary["synthetic_only_fraction"]
            ),
            "circuit/real_residual_fraction": float(
                map_summary["real_residual_fraction"]
            ),
            "circuit/unsupported_fraction": float(
                map_summary["unsupported_fraction"]
            ),
            "circuit/synth_real_component_jaccard": float(
                map_summary["synth_real_component_jaccard"]
            ),
            "circuit/real_completion_count": float(
                map_summary["real_completion_count"]
            ),
            "circuit/teacher_invariance_rate_real": float(
                real_view_stats["teacher_invariance_rate"]
            ),
            "circuit/teacher_invariance_rate_synthetic": float(
                synthetic_view_stats["teacher_invariance_rate"]
            ),
        }
        if use_synthetic_prompt_circuit:
            base_circuit_stats.update(
                {
                    "circuit/mlp_selected_component_count": float(
                        map_summary["mlp_selected_component_count"]
                    ),
                    "circuit/attention_selected_component_count": float(
                        map_summary["attention_selected_component_count"]
                    ),
                    "crossfit/discovery_count": float(
                        len(crossfit_discovery_batches)
                    ),
                    "crossfit/replication_count": float(
                        len(circuit_replication_batches)
                    ),
                    "crossfit/audit_count": float(len(crossfit_audit_batches)),
                    "crossfit/guard_count": float(
                        len(synthetic_constraint_batches)
                    ),
                    "crossfit/audit_teacher_invariance_rate": float(
                        crossfit_audit_view_stats.get(
                            "teacher_invariance_rate", 0.0
                        )
                    ),
                    "crossfit/replication_teacher_invariance_rate": float(
                        circuit_replication_view_stats.get(
                            "teacher_invariance_rate", 0.0
                        )
                    ),
                }
            )
        ig_audit = support_metadata.get("integrated_gradients_audit", {})
        ig_sources = [
            value for value in ig_audit.values() if isinstance(value, dict)
        ]
        if ig_sources:
            for key in (
                "ig_mlp_grad_x_activation_correlation",
                "ig_attention_grad_x_activation_correlation",
                "ig_completeness_relative_error",
                "ig_probe_count",
            ):
                base_circuit_stats[f"circuit/{key}"] = float(
                    np.mean([float(source.get(key, 0.0)) for source in ig_sources])
                )
        base_circuit_stats.update(
            {f"circuit/{key}": float(value) for key, value in causal_stats.items()}
        )
        base_circuit_stats.update(
            {
                f"circuit/{key}": float(value)
                for key, value in rediscovery_stats.items()
            }
        )
        dual_circuit_artifact = {
            "method": method,
            "layout": dual_circuit_layout_artifact,
            "support": support_metadata,
            "circuit_map": circuit_map_metadata,
            "causal_validation": causal_stats,
            "rediscovery_validation": rediscovery_stats,
            "configuration": {
                key: value
                for key, value in vars(args).items()
                if key.startswith("circuit_")
                or (use_synthetic_prompt_circuit and key.startswith("crossfit_"))
            },
        }
        if use_synthetic_prompt_circuit:
            dual_circuit_artifact["crossfit_split"] = crossfit_split_summary
        circuit_map_path = circuit_artifact_dir / (
            "crossfit_ffn_value_map.json"
            if use_crossfit_ffn_value
            else "cached_source_balanced_output_circuit_map.json"
            if use_cached_source_balanced_circuit
            else f"prompt_invariant_{circuit_local_soft_family}_local_soft_map.json"
            if use_circuit_local_soft_projection
            else "prompt_invariant_ffn_value_map.json"
            if use_prompt_invariant_circuit_veto
            else "dual_circuit_map.json"
        )
        save_dual_circuit_cache(
            circuit_map_path.with_suffix(".npz"),
            dual_circuit_host,
            dual_circuit_artifact,
        )
        dual_circuit = shard_dual_circuit_map(
            dual_circuit_host,
            dual_circuit_layouts,
            weights,
        )
        jax.block_until_ready(dual_circuit)
        print(f"Dual circuit map   : {circuit_map_path}")
        if use_synthetic_prompt_circuit:
            print(
                (
                    "Cross-fit FFN values:"
                    if use_crossfit_ffn_value
                    else "Cached source-balanced output circuit:"
                    if use_cached_source_balanced_circuit
                    else f"Circuit-local soft {circuit_local_soft_family}:"
                    if use_circuit_local_soft_projection
                    else "Prompt-invariant FFN values:"
                ),
                f"selected={map_summary['mlp_selected_component_count']} "
                f"of {map_summary['mlp_component_count']} "
                f"attention={map_summary['attention_selected_component_count']} "
                "real-completion=0",
            )
        else:
            print(
                "Circuit tiers       :",
                f"core={map_summary['synthetic_core_fraction']:.4f} "
                f"synthetic-only={map_summary['synthetic_only_fraction']:.4f} "
                f"real-residual={map_summary['real_residual_fraction']:.4f} "
                f"unsupported={map_summary['unsupported_fraction']:.4f}",
            )
        if args.circuit_audit_only:
            audit_summary = {
                "epoch": 0,
                "method": method,
                "method_id": method_id(method),
                "method_variant": method_variant(args),
                "method_variant_id": method_variant_id(args),
                **base_circuit_stats,
            }
            save_final_summary(args.out_dir, audit_summary)
            audit_wandb_run = maybe_init_wandb(
                args,
                len(wrong_batches),
                len(correct_eval_batches),
                len(synthetic_constraint_batches),
                len(tiny_anchor_batches),
            )
            if audit_wandb_run is not None:
                audit_wandb_run.log(audit_summary, step=0)
                update_wandb_summary(audit_wandb_run, audit_summary)
                audit_wandb_run.finish()
            print("Circuit audit complete; --circuit-audit-only stops before training.")
            return

    memory_subspace_bases: tuple[jax.Array, ...] = ()
    memory_subspace_artifact: dict[str, Any] = {}
    memory_subspace_basis_path: Path | None = None
    memory_subspace_basis_source = ""
    if use_subspace_method:
        assert memory_coefficient_fn is not None
        probe_fingerprint = reference_batches_fingerprint(correct_ref_batches)
        memory_subspace_basis_path = (
            Path(args.memory_subspace_basis_path).expanduser()
            if args.memory_subspace_basis_path
            else Path(args.out_dir) / "artifacts" / "ffn_memory_subspace_basis.npz"
        )
        if memory_subspace_basis_path.exists():
            host_bases, memory_subspace_artifact = load_memory_subspace_bases(
                memory_subspace_basis_path,
                memory_layouts,
                args.memory_subspace_rank,
            )
            cached_summary = memory_subspace_artifact.get("summary", {})
            if cached_summary.get("probe_fingerprint") != probe_fingerprint:
                raise ValueError(
                    "memory subspace cache was estimated from a different synthetic probe bank"
                )
            if cached_summary.get("model_name") != args.model_name:
                raise ValueError(
                    "memory subspace cache was estimated from a different model"
                )
            memory_subspace_basis_source = "cache"
        else:
            host_bases, memory_subspace_artifact = estimate_memory_subspace_bases(
                weights,
                correct_ref_batches,
                memory_coefficient_fn,
                memory_layouts,
                rank=args.memory_subspace_rank,
                oversample=args.memory_subspace_oversample,
                power_iterations=args.memory_subspace_power_iterations,
                batch_size=args.memory_subspace_probe_batch_size,
                seed=args.synthetic_seed,
            )
            memory_subspace_artifact["summary"].update(
                {
                    "probe_fingerprint": probe_fingerprint,
                    "model_name": args.model_name,
                }
            )
            save_memory_subspace_bases(
                memory_subspace_basis_path,
                host_bases,
                memory_subspace_artifact,
            )
            memory_subspace_basis_source = "estimated"
        memory_subspace_bases = shard_memory_subspace_bases(
            host_bases,
            memory_layouts,
            weights,
        )
        del host_bases
        subspace_summary = memory_subspace_artifact.get("summary", {})
        print(
            f"FFN subspace basis : {memory_subspace_basis_path} "
            f"({memory_subspace_basis_source})"
        )
        print(f"FFN subspace rank  : {args.memory_subspace_rank}")
        if "synthetic_energy_captured_mean" in subspace_summary:
            print(
                "FFN energy captured:",
                f"{subspace_summary['synthetic_energy_captured_mean']:.4f}",
            )
    subspace_reference_projection_fn = (
        jax.jit(
            lambda synthetic_groups, anchor_groups, bases: (
                project_reference_groups_to_memory_subspaces(
                    tuple(synthetic_groups),
                    memory_layouts,
                    tuple(bases),
                ),
                project_reference_groups_to_memory_subspaces(
                    tuple(anchor_groups),
                    memory_layouts,
                    tuple(bases),
                ),
            )
        )
        if use_subspace_method
        else None
    )

    ffn_value_attribution_selectors: tuple[jax.Array, ...] = ()
    ffn_value_attribution_artifact: dict[str, Any] = {}
    ffn_value_attribution_path: Path | None = None
    ffn_joint_memory_map: dict[str, tuple[jax.Array, ...]] = {}
    ffn_joint_memory_map_artifact: dict[str, Any] = {}
    ffn_joint_memory_map_path: Path | None = None
    if use_ffn_real_value_attribution:
        attribution_fn = jax.jit(
            lambda w, grad: ffn_value_attribution_scores(
                w,
                (grad,),
                memory_layouts,
            )
        )
        assert teacher_reference_loss_grad_fn is not None
        real_attribution_loss_grad_fn = teacher_reference_loss_grad_fn
        real_attribution_scores = estimate_ffn_value_attribution_scores(
            weights,
            tiny_anchor_batches,
            real_attribution_loss_grad_fn,
            attribution_fn,
            memory_layouts,
            desc="real-anchor FFN value attribution",
        )
        host_real_selectors, real_attribution_artifact = (
            select_ffn_value_attribution_slots(
                real_attribution_scores,
                fraction=args.ffn_value_attribution_fraction,
                tail_fraction=args.cnl_cvar_tail,
                probe_label="real anchors",
            )
        )
        del real_attribution_scores
        real_attribution_artifact["summary"].update(
            {
                "model_name": args.model_name,
                "anchor_count": len(tiny_anchor_batches),
                "anchor_seed": args.tiny_anchor_seed,
                "anchor_fingerprint": reference_batches_fingerprint(
                    tiny_anchor_batches
                ),
            }
        )
        if use_ffn_joint_memory_map:
            assert teacher_reference_loss_grad_fn is not None
            synthetic_attribution_scores = estimate_ffn_value_attribution_scores(
                weights,
                correct_ref_batches,
                teacher_reference_loss_grad_fn,
                attribution_fn,
                memory_layouts,
                desc="synthetic-mastered FFN value attribution",
            )
            host_synthetic_selectors, synthetic_attribution_artifact = (
                select_ffn_value_attribution_slots(
                    synthetic_attribution_scores,
                    fraction=args.ffn_value_synthetic_attribution_fraction,
                    tail_fraction=args.cnl_cvar_tail,
                    probe_label="synthetic mastered samples",
                )
            )
            del synthetic_attribution_scores
            synthetic_attribution_artifact["summary"].update(
                {
                    "model_name": args.model_name,
                    "synthetic_probe_count": len(correct_ref_batches),
                    "synthetic_fingerprint": reference_batches_fingerprint(
                        correct_ref_batches
                    ),
                }
            )
            host_memory_map, memory_map_artifact = build_ffn_value_memory_map(
                host_real_selectors,
                host_synthetic_selectors,
            )
            map_summary = dict(memory_map_artifact["summary"])
            map_summary.update(
                {
                    "model_name": args.model_name,
                    "anchor_count": len(tiny_anchor_batches),
                    "synthetic_probe_count": len(correct_ref_batches),
                    "real_attribution_fraction": args.ffn_value_attribution_fraction,
                    "synthetic_attribution_fraction": (
                        args.ffn_value_synthetic_attribution_fraction
                    ),
                    "synthetic_projection_strength": (
                        args.ffn_value_synthetic_projection_strength
                    ),
                    "real_selected_count": real_attribution_artifact["summary"][
                        "selected_count"
                    ],
                    "synthetic_selected_count": synthetic_attribution_artifact[
                        "summary"
                    ]["selected_count"],
                }
            )
            ffn_joint_memory_map_artifact = {
                "method": "joint real/synthetic FFN value attribution map",
                "update_semantics": {
                    "shared": "full alternating synthetic and real CVaR projection",
                    "real_only": "full real CVaR projection",
                    "synthetic_only": "soft synthetic CVaR projection",
                    "free": "unconstrained down-projection value update",
                    "outside_ffn": "combined elementwise synthetic and real CVaR EMA",
                    "ffn_gate_up": "synthetic elementwise CVaR EMA",
                },
                "summary": map_summary,
                "real_attribution": real_attribution_artifact,
                "synthetic_attribution": synthetic_attribution_artifact,
                "memory_map": memory_map_artifact,
            }
            ffn_joint_memory_map_path = (
                Path(args.out_dir) / "artifacts" / "ffn_joint_memory_map.json"
            )
            write_ffn_value_attribution_selection(
                ffn_joint_memory_map_path,
                ffn_joint_memory_map_artifact,
            )
            ffn_joint_memory_map = {
                name: shard_ffn_value_attribution_selectors(
                    selectors,
                    memory_layouts,
                    weights,
                )
                for name, selectors in host_memory_map.items()
            }
            jax.block_until_ready(ffn_joint_memory_map)
            del host_memory_map, host_synthetic_selectors
            print(f"FFN joint memory map: {ffn_joint_memory_map_path}")
            print(
                "FFN map categories :",
                f"shared={map_summary['shared_count']} "
                f"real-only={map_summary['real_only_count']} "
                f"synthetic-only={map_summary['synthetic_only_count']} "
                f"free={map_summary['free_count']}",
            )
        else:
            ffn_value_attribution_artifact = real_attribution_artifact
            ffn_value_attribution_path = (
                Path(args.out_dir)
                / "artifacts"
                / "ffn_value_attribution_selection.json"
            )
            write_ffn_value_attribution_selection(
                ffn_value_attribution_path,
                ffn_value_attribution_artifact,
            )
            ffn_value_attribution_selectors = (
                shard_ffn_value_attribution_selectors(
                    host_real_selectors,
                    memory_layouts,
                    weights,
                )
            )
            jax.block_until_ready(ffn_value_attribution_selectors)
            attribution_summary = ffn_value_attribution_artifact["summary"]
            print(f"FFN value selection : {ffn_value_attribution_path}")
            print(
                "FFN values selected :",
                f"{attribution_summary['selected_count']}/"
                f"{attribution_summary['slot_count_total']} "
                f"({attribution_summary['selected_fraction']:.4f})",
            )
        del host_real_selectors

    entropy_gauge_metrics: dict[str, Any] = {}
    entropy_gauge_low_masks: dict[str, np.ndarray] = {}
    if entropy_gauge_requested:
        assert forward_with_memory_activity is not None
        entropy_gauge_activity_fn = jax.jit(
            lambda current_weights, batch: forward_with_memory_activity(
                batch["tokens"],
                current_weights,
                batch.get("attention_mask"),
            )[1]
        )
        (
            weights,
            entropy_gauge_metrics,
            entropy_gauge_low_masks,
        ) = prepare_jax_entropy_gauge(
            args,
            method,
            weights,
            forward,
            entropy_gauge_activity_fn,
            correct_ref_batches,
            tiny_anchor_batches,
        )
        if args.entropy_gauge_diagnostic_only:
            print("Entropy-gauge diagnostic complete; training was not started.")
            return

    use_mask_ema = method in {
        "cnl_mask_ema",
        REAL_ANCHOR_CANDIDATE_ONLY_METHOD,
    }
    optimizer = make_optimizer(args.optimizer, args.lr, weight_decay=args.weight_decay)
    opt_state = optimizer.init(weights)
    cnl_mask_ema = (
        init_mask_ema_like(weights)
        if (
            use_mask_ema
            or (
                use_teacher_reference
                and not use_cached_source_balanced_circuit
                and method not in NO_MASK_EMA_METHODS
            )
        )
        else None
    )
    quadratic_preview_mask_ema = (
        init_mask_ema_like(weights)
        if use_quadratic_normmatched_control
        else None
    )
    circuit_correction_ema = (
        init_mask_ema_like(weights)
        if use_dual_circuit and not use_synthetic_prompt_circuit
        else None
    )
    control_structured_mask_ema = (
        init_mask_ema_like(weights) if use_normmatched_control else None
    )
    functional_gradient_ema = (
        init_mask_ema_like(weights) if use_any_functional_trust else None
    )
    cnl_mask_ema_count = jnp.asarray(0, dtype=jnp.int32)
    paem_anchor_mask_ema = (
        init_mask_ema_like(weights)
        if use_paem_anchor_mask_ema
        else None
    )
    paem_anchor_mask_ema_count = jnp.asarray(0, dtype=jnp.int32)
    anchor_blend_weight_ema = (
        jnp.zeros((len(layer_blend_group_labels),), dtype=jnp.float32)
        if args.anchor_blend_rule == "layer_bv_shrinkage"
        else jnp.asarray(0.0, dtype=jnp.float32)
    )
    anchor_blend_weight_ema_count = jnp.asarray(0, dtype=jnp.int32)
    quadratic_preview_mask_ema_count = jnp.asarray(
        0,
        dtype=jnp.int32,
    )
    functional_gradient_ema_count = jnp.asarray(0, dtype=jnp.int32)
    margin_budget_spent = jnp.zeros_like(
        margin_budget_budgets,
        dtype=jnp.float32,
    )
    activity_loss_grad_fn = None
    route_loss_grad_fn = None
    activity_probe_fn = None
    old_occupancy = None
    free_distribution = None
    base_memory_stats: dict[str, Any] = {}
    if use_memory_occupancy:
        assert forward_with_memory_activity is not None
        activity_loss_grad_fn = jax.value_and_grad(
            lambda w, batch: loss_and_memory_activity_for_batch(
                forward_with_memory_activity,
                w,
                batch,
            ),
            has_aux=True,
        )
        if use_free_capacity_routing:
            route_loss_grad_fn = jax.value_and_grad(
                lambda w, batch, free: (
                    relevance_weighted_free_route_loss_and_memory_activity_for_batch(
                        forward_with_memory_activity,
                        w,
                        batch,
                        free,
                        args.memory_route_lambda,
                        args.free_capacity_relevance_power,
                    )
                ),
                has_aux=True,
            )
        else:
            route_loss_fn = (
                mean_free_route_loss_and_memory_activity_for_batch
                if use_prompt_invariant_free_route
                else route_loss_and_memory_activity_for_batch
            )
            route_loss_grad_fn = jax.value_and_grad(
                lambda w, batch, free: route_loss_fn(
                    forward_with_memory_activity,
                    w,
                    batch,
                    free,
                    args.memory_route_lambda,
                ),
                has_aux=True,
            )
        activity_probe_fn = jax.jit(
            lambda w, batch: forward_with_memory_activity(
                batch["tokens"],
                w,
                batch.get("attention_mask"),
            )[1]
        )

        def compute_old_memory_occupancy(current_weights: Any, suffix: str) -> jax.Array:
            assert activity_probe_fn is not None
            occupancy_synthetic_batches = (
                cross_view_synthetic_view_batches
                if use_free_capacity_routing
                else correct_ref_batches
            )
            synthetic_activity = mean_memory_activity(
                current_weights,
                occupancy_synthetic_batches,
                activity_probe_fn,
                desc=f"synthetic memory occupancy {suffix}",
                use_reference_weights=use_free_capacity_routing,
            )
            occupancy_anchor_batches = (
                invariant_anchor_batches
                if use_prompt_invariant_free_route or use_free_capacity_routing
                else tiny_anchor_batches
            )
            anchor_activity = mean_memory_activity(
                current_weights,
                occupancy_anchor_batches,
                activity_probe_fn,
                desc=f"anchor memory occupancy {suffix}",
                use_reference_weights=(
                    use_prompt_invariant_free_route
                    or use_free_capacity_routing
                ),
            )
            occupancy = (
                blended_old_occupancy(
                    synthetic_activity,
                    anchor_activity,
                    args.memory_anchor_occupancy_weight,
                )
                if use_prompt_invariant_free_route
                or use_free_capacity_routing
                else robust_old_occupancy(synthetic_activity, anchor_activity)
            )
            return jax.block_until_ready(occupancy)

        old_occupancy = compute_old_memory_occupancy(weights, "init")
        free_distribution = free_memory_distribution(
            old_occupancy,
            args.memory_free_gamma,
            floor=(
                args.memory_free_floor
                if use_prompt_invariant_free_route
                or use_free_capacity_routing
                else 0.0
            ),
        )
        base_memory_stats = memory_occupancy_summary(
            old_occupancy,
            active_threshold=args.memory_occupancy_active_threshold,
        )
        if use_prompt_invariant_free_route or use_free_capacity_routing:
            base_memory_stats.update(
                {
                    "memory/occupancy_anchor_weight": jnp.asarray(
                        args.memory_anchor_occupancy_weight,
                        dtype=jnp.float32,
                    ),
                    "memory/free_floor": jnp.asarray(
                        args.memory_free_floor,
                        dtype=jnp.float32,
                    ),
                }
            )
    teacher_weights = None
    target_exempt_loss_grad_fn = None
    use_target_exempt_teacher = (
        use_normmatched_anchor_veto
        or use_target_exempt_cached_source_balanced_circuit
    )
    use_opd_ema_teacher = (
        use_opd_distillation
        and args.opd_teacher_mode == "answer_conditioned"
    )
    use_sdft_ema_teacher = use_sdft_residual_cnl
    if (
        use_target_exempt_teacher
        or use_opd_ema_teacher
        or use_sdft_ema_teacher
    ):
        teacher_weights = jax.tree.map(lambda x: jnp.array(x, copy=True), weights)
        jax.block_until_ready(teacher_weights)
    elif use_support_then_opd:
        teacher_weights = jnp.asarray(0.0, dtype=jnp.float32)
    if use_target_exempt_teacher:
        target_exempt_loss_grad_fn = jax.jit(
            jax.value_and_grad(
                lambda student, teacher, batch, lam: target_exempt_loss_for_batch(
                    forward,
                    student,
                    teacher,
                    batch,
                    candidate_ids_jax,
                    kl_direction=args.target_exempt_kl_direction,
                    lam=lam,
                    eps=args.target_exempt_eps,
                )
            )
        )

    def train_step(w, state, batch, ref_grads):
        loss, grads = loss_grad_fn(w, batch)
        w, state, _ = cnl_optax_step(
            w,
            grads,
            ref_grads,
            optimizer,
            state,
            mask_stage=args.mask_stage,
            mask_mode=effective_cnl_mask_mode(args),
            margin=args.cnl_margin,
            leak=args.cnl_leak,
        )
        return w, state, loss

    def plain_step(w, state, batch, ref_grads):
        del ref_grads
        loss, grads = loss_grad_fn(w, batch)
        updates, state = optimizer.update(grads, state, w)
        w = optax.apply_updates(w, updates)
        return w, state, loss

    def update_matched_replay_step(
        w,
        state,
        target_batch,
        replay_batch,
        replay_weight,
    ):
        target_loss, target_grads = loss_grad_fn(w, target_batch)
        replay_loss, replay_grads = loss_grad_fn(w, replay_batch)
        grads = jax.tree.map(
            lambda target, replay: (
                (1.0 - replay_weight) * target + replay_weight * replay
            ),
            target_grads,
            replay_grads,
        )
        updates, state = optimizer.update(grads, state, w)
        w = optax.apply_updates(w, updates)
        loss = (1.0 - replay_weight) * target_loss + replay_weight * replay_loss
        return w, state, loss, target_loss, replay_loss

    def train_step_mask_ema(w, state, mask_ema, mask_ema_count, batch, ref_grads):
        loss, grads = loss_grad_fn(w, batch)
        w, state, mask_ema, mask_ema_count, _, mask_stats = cnl_optax_step_mask_ema(
            w,
            grads,
            ref_grads,
            optimizer,
            state,
            mask_ema,
            mask_ema_count,
            mask_stage=args.mask_stage,
            beta=args.cnl_mask_ema_beta,
        )
        return w, state, mask_ema, mask_ema_count, loss, mask_stats

    def train_step_anchor_veto(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        synthetic_group_grads,
        anchor_group_grads,
    ):
        loss, grads = loss_grad_fn(w, batch)
        updates, state = optimizer.update(grads, state, w)
        updates, mask_ema, mask_ema_count, mask_stats = mask_optax_updates_anchor_veto_ema(
            updates,
            synthetic_group_grads,
            anchor_group_grads,
            mask_ema,
            mask_ema_count,
            tail_fraction=args.cnl_cvar_tail,
            beta=args.cnl_mask_ema_beta,
        )
        w = optax.apply_updates(w, updates)
        return w, state, mask_ema, mask_ema_count, loss, mask_stats

    def train_step_fixed_anchor_blend(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        fused_reference_grads,
    ):
        loss, grads = loss_grad_fn(w, batch)
        updates, state = optimizer.update(grads, state, w)
        mask_fn = (
            mask_optax_updates_anchor_certified_ema
            if args.anchor_blend_rule == "anchor_certified"
            else mask_optax_updates_fixed_blend_ema
        )
        (
            updates,
            mask_ema,
            mask_ema_count,
            mask_stats,
        ) = mask_fn(
            updates,
            fused_reference_grads,
            mask_ema,
            mask_ema_count,
            beta=args.cnl_mask_ema_beta,
        )
        w = optax.apply_updates(w, updates)
        return w, state, mask_ema, mask_ema_count, loss, mask_stats

    def train_step_dynamic_anchor_blend(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        synthetic_reference_grads,
        anchor_reference_grads,
    ):
        loss, grads = loss_grad_fn(w, batch)
        updates, state = optimizer.update(grads, state, w)
        if args.anchor_blend_rule == "influence_aligned":
            (
                updates,
                mask_ema,
                mask_ema_count,
                mask_stats,
            ) = mask_optax_updates_influence_blend_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                mask_ema,
                mask_ema_count,
                real_weight=args.anchor_shrinkage_fixed_real_weight,
                max_scale=args.anchor_blend_influence_max_scale,
                eps=args.anchor_shrinkage_eps,
                beta=args.cnl_mask_ema_beta,
            )
        elif args.anchor_blend_rule == "alpha_marginalized":
            (
                updates,
                mask_ema,
                mask_ema_count,
                mask_stats,
            ) = mask_optax_updates_marginalized_blend_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                mask_ema,
                mask_ema_count,
                candidate_real_weights=args.anchor_blend_marginal_weights,
                beta=args.cnl_mask_ema_beta,
            )
        elif args.anchor_blend_rule == "source_vote":
            (
                updates,
                mask_ema,
                mask_ema_count,
                mask_stats,
            ) = mask_optax_updates_source_vote_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                mask_ema,
                mask_ema_count,
                real_weight=args.anchor_shrinkage_fixed_real_weight,
                beta=args.cnl_mask_ema_beta,
            )
        elif args.anchor_blend_rule == "soft_ties":
            (
                updates,
                mask_ema,
                mask_ema_count,
                mask_stats,
            ) = mask_optax_updates_soft_ties_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                mask_ema,
                mask_ema_count,
                real_weight=args.anchor_shrinkage_fixed_real_weight,
                temperature=args.anchor_blend_soft_ties_temperature,
                eps=args.anchor_shrinkage_eps,
                beta=args.cnl_mask_ema_beta,
            )
        elif args.anchor_blend_rule == "trimmed_ties":
            (
                updates,
                mask_ema,
                mask_ema_count,
                mask_stats,
            ) = mask_optax_updates_trimmed_ties_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                mask_ema,
                mask_ema_count,
                trim_threshold=args.anchor_blend_ties_trim_threshold,
                elect_margin=args.anchor_blend_ties_elect_margin,
                eps=args.anchor_shrinkage_eps,
                beta=args.cnl_mask_ema_beta,
            )
        else:
            raise ValueError(
                f"unsupported dynamic anchor blend: {args.anchor_blend_rule}"
            )
        w = optax.apply_updates(w, updates)
        return w, state, mask_ema, mask_ema_count, loss, mask_stats

    def train_step_global_bv_anchor_blend(
        w,
        state,
        mask_ema,
        mask_ema_count,
        blend_weight_ema,
        blend_weight_ema_count,
        batch,
        synthetic_reference_grads,
        anchor_reference_grads,
        synthetic_variance_of_mean,
        anchor_variance_of_mean,
        cross_covariance_of_mean,
    ):
        loss, grads = loss_grad_fn(w, batch)
        updates, state = optimizer.update(grads, state, w)
        if args.anchor_blend_rule == "layer_bv_shrinkage":
            assert layer_blend_group_ids is not None
            (
                updates,
                mask_ema,
                mask_ema_count,
                blend_weight_ema,
                blend_weight_ema_count,
                mask_stats,
            ) = mask_optax_updates_layer_bv_shrinkage_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                synthetic_variance_of_mean,
                anchor_variance_of_mean,
                layer_blend_group_ids,
                layer_blend_group_labels,
                layer_blend_group_parameter_counts,
                mask_ema,
                mask_ema_count,
                blend_weight_ema,
                blend_weight_ema_count,
                baseline_real_weight=(
                    args.anchor_shrinkage_fixed_real_weight
                ),
                max_deviation=args.anchor_blend_layer_bv_max_deviation,
                beta=args.cnl_mask_ema_beta,
                blend_weight_beta=args.anchor_blend_weight_ema_beta,
                eps=args.anchor_shrinkage_eps,
                layer_variance_is_aggregate=True,
            )
        else:
            (
                updates,
                mask_ema,
                mask_ema_count,
                blend_weight_ema,
                blend_weight_ema_count,
                mask_stats,
            ) = mask_optax_updates_global_bv_shrinkage_ema(
                updates,
                synthetic_reference_grads,
                anchor_reference_grads,
                synthetic_variance_of_mean,
                anchor_variance_of_mean,
                mask_ema,
                mask_ema_count,
                blend_weight_ema,
                blend_weight_ema_count,
                beta=args.cnl_mask_ema_beta,
                blend_weight_beta=args.anchor_blend_weight_ema_beta,
                eps=args.anchor_shrinkage_eps,
                cross_covariance_of_mean=cross_covariance_of_mean,
            )
        w = optax.apply_updates(w, updates)
        return (
            w,
            state,
            mask_ema,
            mask_ema_count,
            blend_weight_ema,
            blend_weight_ema_count,
            loss,
            mask_stats,
        )

    def train_step_sdft_support_unmasked(
        w,
        state,
        teacher,
        batch,
        teacher_batch,
    ):
        assert sdft_support_loss_grad_fn is not None
        (loss, objective_stats), grads = sdft_support_loss_grad_fn(
            w,
            teacher,
            batch,
            teacher_batch,
        )
        updates, state = optimizer.update(grads, state, w)
        raw_update_norm = tree_l2_norm(updates)
        w = optax.apply_updates(w, updates)
        teacher = update_ema_teacher(
            teacher,
            w,
            beta=args.sdft_teacher_ema_beta,
        )
        objective_stats.update(
            {
                "sdft/raw_update_norm": raw_update_norm,
                "sdft/applied_update_norm": raw_update_norm,
                "sdft/applied_update_fraction": jnp.asarray(
                    1.0,
                    dtype=jnp.float32,
                ),
            }
        )
        return w, state, teacher, loss, objective_stats

    def train_step_sdft_support_cnl(
        w,
        state,
        teacher,
        mask_ema,
        mask_ema_count,
        batch,
        teacher_batch,
        synthetic_group_grads,
        anchor_group_grads,
    ):
        assert sdft_support_loss_grad_fn is not None
        (loss, objective_stats), grads = sdft_support_loss_grad_fn(
            w,
            teacher,
            batch,
            teacher_batch,
        )
        updates, state = optimizer.update(grads, state, w)
        raw_update_norm = tree_l2_norm(updates)
        (
            updates,
            mask_ema,
            mask_ema_count,
            mask_stats,
        ) = mask_optax_updates_anchor_veto_ema(
            updates,
            synthetic_group_grads,
            anchor_group_grads,
            mask_ema,
            mask_ema_count,
            tail_fraction=args.cnl_cvar_tail,
            beta=args.cnl_mask_ema_beta,
        )
        applied_update_norm = tree_l2_norm(updates)
        w = optax.apply_updates(w, updates)
        teacher = update_ema_teacher(
            teacher,
            w,
            beta=args.sdft_teacher_ema_beta,
        )
        objective_stats.update(
            {
                "sdft/raw_update_norm": raw_update_norm,
                "sdft/applied_update_norm": applied_update_norm,
                "sdft/applied_update_fraction": (
                    applied_update_norm
                    / jnp.maximum(raw_update_norm, 1e-30)
                ),
            }
        )
        mask_stats.update(objective_stats)
        return (
            w,
            state,
            teacher,
            mask_ema,
            mask_ema_count,
            loss,
            mask_stats,
        )

