    def train_step_ppmt_midtrain_soft_cnl(
        w,
        state,
        mask_ema,
        mask_ema_count,
        midtrain_batch,
        injection_policy_batch,
        memory_policy_batch,
        reference_is_anchor,
        synthetic_group_grads,
        anchor_group_grads,
    ):
        assert ppmt_midtrain_loss_grad_fn is not None
        (loss, objective_stats), grads = ppmt_midtrain_loss_grad_fn(
            w,
            midtrain_batch,
            injection_policy_batch,
            memory_policy_batch,
            reference_is_anchor,
        )
        raw_updates, state = optimizer.update(grads, state, w)
        raw_update_norm = tree_l2_norm(raw_updates)
        (
            fully_masked_updates,
            mask_ema,
            mask_ema_count,
            mask_stats,
        ) = mask_optax_updates_anchor_veto_ema(
            raw_updates,
            synthetic_group_grads,
            anchor_group_grads,
            mask_ema,
            mask_ema_count,
            tail_fraction=args.cnl_cvar_tail,
            beta=args.cnl_mask_ema_beta,
        )
        strength = jnp.asarray(
            args.ppmt_cnl_strength,
            dtype=jnp.float32,
        )
        updates = jax.tree_util.tree_map(
            lambda raw, masked: raw
            + strength.astype(raw.dtype) * (masked - raw),
            raw_updates,
            fully_masked_updates,
        )
        fully_masked_update_norm = tree_l2_norm(fully_masked_updates)
        applied_update_norm = tree_l2_norm(updates)
        w = optax.apply_updates(w, updates)
        objective_stats.update(
            {
                "ppmt/raw_update_norm": raw_update_norm,
                "ppmt/fully_masked_update_norm": (
                    fully_masked_update_norm
                ),
                "ppmt/applied_update_norm": applied_update_norm,
                "ppmt/applied_update_fraction": (
                    applied_update_norm
                    / jnp.maximum(raw_update_norm, 1e-30)
                ),
                "ppmt/cnl_strength": strength,
            }
        )
        mask_stats.update(objective_stats)
        return (
            w,
            state,
            mask_ema,
            mask_ema_count,
            loss,
            mask_stats,
        )

