    def train_step_paem_anchor_mask_ema(
        w,
        state,
        mask_ema,
        mask_ema_count,
        injection_batch,
        replay_grad,
    ):
        """Apply a bias-corrected EMA of replay-safe coordinate masks."""
        loss, grads = loss_grad_fn(w, injection_batch)
        updates, state = optimizer.update(grads, state, w)
        raw_update_norm = tree_l2_norm(updates)
        (
            updates,
            mask_ema,
            mask_ema_count,
            ema_stats,
        ) = mask_optax_updates_ema(
            updates,
            replay_grad,
            mask_ema,
            mask_ema_count,
            beta=args.paem_anchor_mask_ema_beta,
        )
        applied_update_norm = tree_l2_norm(updates)
        w = optax.apply_updates(w, updates)
        mask_stats = {
            "paem/world_loss": loss,
            "paem/total_loss": loss,
            "paem/raw_update_norm": raw_update_norm,
            "paem/applied_update_norm": applied_update_norm,
            "paem/applied_update_fraction": (
                applied_update_norm
                / jnp.maximum(raw_update_norm, 1e-30)
            ),
            "paem/anchor_mask_mean": ema_stats["cnl/ema_mask_mean"],
            "paem/anchor_instant_mask_mean": ema_stats[
                "cnl/instant_mask_mean"
            ],
            "paem/anchor_ema_mask_mean": ema_stats["cnl/ema_mask_mean"],
            "paem/anchor_ema_mask_frac_gt_0_5": ema_stats[
                "cnl/ema_mask_frac_gt_0_5"
            ],
            "paem/anchor_mask_ema_count": mask_ema_count.astype(
                jnp.float32
            ),
        }
        return (
            w,
            state,
            mask_ema,
            mask_ema_count,
            loss,
            mask_stats,
        )

