    def causal_group_test_losses(
        w,
        raw_update,
        synthetic_group_grads,
        patterns,
        calibration_batch,
    ):
        proposal = synthetic_structured_probe_update(
            raw_update,
            tuple(synthetic_group_grads),
            dual_circuit_layouts,
            tail_fraction=args.cnl_cvar_tail,
        )
        energies = structured_block_energies(
            proposal,
            dual_circuit_layouts,
        )
        baseline_loss = candidate_ce_loss_for_batch(
            forward,
            w,
            calibration_batch,
            candidate_ids_jax,
        )

        def evaluate(pattern):
            candidate_update = apply_structured_block_gates(
                proposal,
                dual_circuit_layouts,
                pattern,
                zero_outside=True,
            )
            candidate_update = jax.tree_util.tree_map(
                lambda value: value
                * jnp.asarray(
                    args.causal_group_step_scale,
                    dtype=value.dtype,
                ),
                candidate_update,
            )
            candidate_weights = optax.apply_updates(w, candidate_update)
            return candidate_ce_loss_for_batch(
                forward,
                candidate_weights,
                calibration_batch,
                candidate_ids_jax,
            )

        tested_losses = jax.lax.map(evaluate, patterns)
        return baseline_loss, tested_losses, energies

