    def train_step_on_policy_gradient_regularizer(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        rewrite_batch,
        synthetic_group_grads,
        anchor_group_grads,
    ):
        primary_loss, primary_grads = loss_grad_fn(w, batch)
        rewrite_loss, rewrite_grads = loss_grad_fn(w, rewrite_batch)
        combined_grads, regularizer_stats = (
            combine_primary_and_regularizer_gradients(
                primary_grads,
                rewrite_grads,
                strength=args.on_policy_regularizer_strength,
                max_norm_ratio=args.on_policy_regularizer_max_norm_ratio,
            )
        )
        updates, state = optimizer.update(combined_grads, state, w)
        updates, mask_ema, mask_ema_count, mask_stats = (
            mask_optax_updates_anchor_veto_ema(
                updates,
                synthetic_group_grads,
                anchor_group_grads,
                mask_ema,
                mask_ema_count,
                tail_fraction=args.cnl_cvar_tail,
                beta=args.cnl_mask_ema_beta,
            )
        )
        weighted_total_loss = (
            primary_loss
            + regularizer_stats["on_policy_regularizer/applied_strength"]
            * rewrite_loss
        )
        mask_stats.update(regularizer_stats)
        mask_stats.update(
            {
                "on_policy_regularizer/original_loss": primary_loss,
                "on_policy_regularizer/rewrite_loss": rewrite_loss,
                "on_policy_regularizer/weighted_total_loss": weighted_total_loss,
                "current_objective/sft_loss": primary_loss,
                "current_objective/route_loss": jnp.asarray(
                    0.0,
                    dtype=jnp.float32,
                ),
                "current_objective/total_loss": weighted_total_loss,
            }
        )
        w = optax.apply_updates(w, updates)
        return (
            w,
            state,
            mask_ema,
            mask_ema_count,
            primary_loss,
            mask_stats,
        )

    def train_step_on_policy_mask_cpl(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        on_policy_batch,
        synthetic_group_grads,
        anchor_group_grads,
    ):
        loss, original_grads = loss_grad_fn(w, batch)
        on_policy_loss, on_policy_grads = loss_grad_fn(
            w,
            on_policy_batch,
        )
        updates, state = optimizer.update(original_grads, state, w)
        (
            updates,
            mask_ema,
            mask_ema_count,
            mask_stats,
        ) = mask_optax_updates_on_policy_cpl_ema(
            updates,
            original_grads,
            on_policy_grads,
            synthetic_group_grads,
            anchor_group_grads,
            mask_ema,
            mask_ema_count,
            tail_fraction=args.cnl_cvar_tail,
            beta=args.cnl_mask_ema_beta,
            acquisition_floor=args.on_policy_mask_acquisition_floor,
            support_eps=args.on_policy_mask_support_eps,
        )
        mask_stats.update(
            {
                "on_policy_mask/original_loss": loss,
                "on_policy_mask/proxy_loss": on_policy_loss,
                "current_objective/sft_loss": loss,
                "current_objective/route_loss": jnp.asarray(
                    0.0,
                    dtype=jnp.float32,
                ),
                "current_objective/total_loss": loss,
            }
        )
        w = optax.apply_updates(w, updates)
        return (
            w,
            state,
            mask_ema,
            mask_ema_count,
            loss,
            mask_stats,
        )

    def apply_support_then_opd_constraints(
        w,
        updates,
        current_grads,
        mask_ema,
        mask_ema_count,
        quadratic_preview_ema,
        quadratic_preview_ema_count,
        functional_ema,
        functional_ema_count,
        synthetic_group_grads,
        anchor_grad,
        synthetic_fisher,
        real_fisher,
        reference_batch,
        reference_is_anchor,
        apply_mastered_policy,
    ):
        constraint_stats: dict[str, jax.Array] = {}
        if use_opd_first_order_protection:
            (
                updates,
                mask_ema,
                mask_ema_count,
                protection_stats,
            ) = mask_optax_updates_minveto_ema(
                updates,
                current_grads,
                synthetic_group_grads,
                anchor_grad,
                mask_ema,
                mask_ema_count,
                tail_fraction=args.cnl_cvar_tail,
                beta=args.minveto_ema_beta,
                harm_reduction_fraction=args.minveto_harm_reduction_fraction,
                energy_cap=args.minveto_energy_cap,
                weight_eps=args.minveto_weight_eps,
                bisection_iterations=args.minveto_bisection_iterations,
                max_expansions=args.minveto_max_expansions,
                lambda_initial_high=args.minveto_lambda_initial_high,
                bisection_tolerance=args.minveto_bisection_tolerance,
            )
            constraint_stats.update(protection_stats)
        elif use_opd_quadratic_protection:
            (
                updates,
                mask_ema,
                mask_ema_count,
                quadratic_preview_ema,
                quadratic_preview_ema_count,
                protection_stats,
            ) = mask_optax_updates_quadratic_minveto_ema(
                updates,
                current_grads,
                tuple(synthetic_group_grads),
                anchor_grad,
                synthetic_fisher,
                real_fisher,
                mask_ema,
                mask_ema_count,
                quadratic_preview_ema=quadratic_preview_ema,
                quadratic_preview_ema_count=quadratic_preview_ema_count,
                tail_fraction=args.cnl_cvar_tail,
                calibration_enabled=use_quadratic_calibration,
                calibration_min=args.quadratic_calibration_min,
                calibration_max=args.quadratic_calibration_max,
                calibration_strength=args.quadratic_calibration_strength,
                calibration_min_directional_risk=(
                    args.quadratic_calibration_min_directional_risk
                ),
                first_order_enabled=True,
                harm_reduction_fraction=(
                    args.quadratic_harm_reduction_fraction
                ),
                energy_cap=args.quadratic_energy_cap,
                weight_eps=args.quadratic_weight_eps,
                bisection_iterations=args.quadratic_bisection_iterations,
                max_expansions=args.quadratic_max_expansions,
                lambda_initial_high=args.quadratic_lambda_initial_high,
                bisection_tolerance=args.quadratic_bisection_tolerance,
                ema_mode=args.quadratic_ema_mode,
                ema_beta=args.quadratic_ema_beta,
                normmatched_first_order_control=False,
            )
            constraint_stats.update(protection_stats)

        if apply_mastered_policy and use_opd_mastered_policy:
            assert functional_trust_loss_grad_fn is not None
            candidate_weights = optax.apply_updates(w, updates)
            functional_loss, functional_grad = functional_trust_loss_grad_fn(
                candidate_weights,
                reference_batch,
            )
            (
                updates,
                functional_ema,
                functional_ema_count,
                trust_stats,
            ) = project_optax_updates_functional_trust_region_ema(
                updates,
                functional_grad,
                functional_loss,
                functional_ema,
                functional_ema_count,
                radius=args.opd_mastered_policy_radius,
                beta=args.cnl_mask_ema_beta,
                strength=args.opd_mastered_policy_strength,
                max_correction_ratio=(
                    args.opd_mastered_policy_max_correction_ratio
                ),
                eps=args.functional_trust_region_eps,
            )
            trust_stats.update(
                {
                    "functional_trust/reference_is_anchor": jnp.asarray(
                        reference_is_anchor,
                        dtype=jnp.float32,
                    ),
                    "opd/mastered_policy_loss": functional_loss,
                }
            )
            constraint_stats.update(trust_stats)
        return (
            updates,
            mask_ema,
            mask_ema_count,
            quadratic_preview_ema,
            quadratic_preview_ema_count,
            functional_ema,
            functional_ema_count,
            constraint_stats,
        )

    def finish_support_then_opd_updates(
        w,
        state,
        teacher,
        mask_ema,
        mask_ema_count,
        quadratic_preview_ema,
        quadratic_preview_ema_count,
        functional_ema,
        functional_ema_count,
        loss,
        current_grads,
        updates,
        objective_stats,
        synthetic_group_grads,
        anchor_grad,
        synthetic_fisher,
        real_fisher,
        reference_batch,
        reference_is_anchor,
        apply_mastered_policy,
    ):
        (
            updates,
            mask_ema,
            mask_ema_count,
            quadratic_preview_ema,
            quadratic_preview_ema_count,
            functional_ema,
            functional_ema_count,
            constraint_stats,
        ) = apply_support_then_opd_constraints(
            w,
            updates,
            current_grads,
            mask_ema,
            mask_ema_count,
            quadratic_preview_ema,
            quadratic_preview_ema_count,
            functional_ema,
            functional_ema_count,
            synthetic_group_grads,
            anchor_grad,
            synthetic_fisher,
            real_fisher,
            reference_batch,
            reference_is_anchor,
            apply_mastered_policy,
        )
        w = optax.apply_updates(w, updates)
        if (
            use_opd_distillation
            and args.opd_teacher_mode == "answer_conditioned"
        ):
            teacher = update_ema_teacher(
                teacher,
                w,
                beta=args.opd_teacher_ema_beta,
            )
        constraint_stats.update(objective_stats)
        constraint_stats.update(
            {
                "current_objective/sft_loss": objective_stats["opd/ce_loss"],
                "current_objective/route_loss": jnp.asarray(
                    0.0,
                    dtype=jnp.float32,
                ),
                "current_objective/total_loss": loss,
            }
        )
        return (
            w,
            state,
            teacher,
            mask_ema,
            mask_ema_count,
            quadratic_preview_ema,
            quadratic_preview_ema_count,
            functional_ema,
            functional_ema_count,
            loss,
            constraint_stats,
        )

