    def train_step_ffn_vector_cvar(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        synthetic_group_grads,
        anchor_group_grads,
    ):
        loss, grads = loss_grad_fn(w, batch)
        updates, state = optimizer.update(grads, state, w)
        if use_ffn_joint_memory_map:
            updates, mask_ema, mask_ema_count, mask_stats = (
                mask_optax_updates_ffn_joint_memory_map_projection_ema(
                    updates,
                    tuple(synthetic_group_grads),
                    tuple(anchor_group_grads),
                    memory_layouts,
                    ffn_joint_memory_map,
                    mask_ema,
                    mask_ema_count,
                    tail_fraction=args.cnl_cvar_tail,
                    beta=args.cnl_mask_ema_beta,
                    projection_passes=args.ffn_vector_projection_passes,
                    synthetic_projection_strength=(
                        args.ffn_value_synthetic_projection_strength
                    ),
                )
            )
        elif use_ffn_value_attribution_projection:
            updates, mask_ema, mask_ema_count, mask_stats = (
                mask_optax_updates_ffn_value_attribution_projection_ema(
                    updates,
                    tuple(synthetic_group_grads),
                    tuple(anchor_group_grads),
                    memory_layouts,
                    ffn_value_attribution_selectors,
                    mask_ema,
                    mask_ema_count,
                    tail_fraction=args.cnl_cvar_tail,
                    beta=args.cnl_mask_ema_beta,
                    projection_passes=args.ffn_vector_projection_passes,
                )
            )
        elif use_ffn_vector_cvar_projection:
            updates, mask_ema, mask_ema_count, mask_stats = (
                mask_optax_updates_ffn_vector_cvar_projection_ema(
                    updates,
                    tuple(synthetic_group_grads),
                    tuple(anchor_group_grads),
                    memory_layouts,
                    mask_ema,
                    mask_ema_count,
                    tail_fraction=args.cnl_cvar_tail,
                    beta=args.cnl_mask_ema_beta,
                    projection_passes=args.ffn_vector_projection_passes,
                )
            )
        else:
            updates, mask_ema, mask_ema_count, mask_stats = (
                mask_optax_updates_ffn_vector_cvar_veto_ema(
                    updates,
                    tuple(synthetic_group_grads),
                    tuple(anchor_group_grads),
                    memory_layouts,
                    mask_ema,
                    mask_ema_count,
                    tail_fraction=args.cnl_cvar_tail,
                    beta=args.cnl_mask_ema_beta,
                )
            )
        mask_stats.update(
            {
                "current_objective/sft_loss": loss,
                "current_objective/route_loss": jnp.asarray(0.0, dtype=jnp.float32),
                "current_objective/total_loss": loss,
            }
        )
        w = optax.apply_updates(w, updates)
        return w, state, mask_ema, mask_ema_count, loss, mask_stats

