    def train_step_target_exempt_cached_source_balanced_circuit(
        w,
        state,
        batch,
        synthetic_group_grads,
        anchor_group_grads,
        teacher,
        lam,
    ):
        assert target_exempt_loss_grad_fn is not None
        target_loss, target_grads = target_exempt_loss_grad_fn(
            w,
            teacher,
            batch,
            lam,
        )
        target_updates, target_state = optimizer.update(target_grads, state, w)
        target_norm = tree_l2_norm(target_updates)

        sft_loss, sft_grads = loss_grad_fn(w, batch)
        sft_updates, _ = optimizer.update(sft_grads, state, w)
        sft_norm = tree_l2_norm(sft_updates)
        raw_scale = sft_norm / jnp.maximum(target_norm, args.target_exempt_eps)
        scale = jnp.clip(
            raw_scale,
            args.normmatched_scale_min,
            args.normmatched_scale_max,
        )
        updates = scale_tree(target_updates, scale)
        scaled_norm = tree_l2_norm(updates)
        updates, mask_stats = (
            project_optax_updates_cached_source_balanced_circuit(
                updates,
                tuple(synthetic_group_grads),
                tuple(anchor_group_grads),
                dual_circuit_layouts,
                dual_circuit,
                tail_fraction=args.cnl_cvar_tail,
                projection_passes=args.circuit_projection_passes,
                minimum_kept_fraction=args.cached_projector_min_kept_fraction,
            )
        )
        mask_stats.update(
            {
                "current_objective/target_exempt_loss": target_loss,
                "current_objective/target_exempt_lambda": lam,
                "current_objective/sft_loss": sft_loss,
                "current_objective/route_loss": jnp.asarray(
                    0.0,
                    dtype=jnp.float32,
                ),
                "current_objective/total_loss": target_loss,
                "normmatched/target_update_norm": target_norm,
                "normmatched/sft_update_norm_before": sft_norm,
                "normmatched/raw_scale": raw_scale,
                "normmatched/scale": scale,
                "normmatched/sft_update_norm_after": scaled_norm,
            }
        )
        w = optax.apply_updates(w, updates)
        return w, target_state, sft_loss, mask_stats

    def train_step_memory_subspace(
        w,
        state,
        mask_ema,
        mask_ema_count,
        batch,
        synthetic_group_grads,
        anchor_group_grads,
        synthetic_subspace_group_grads,
        anchor_subspace_group_grads,
        subspace_bases,
    ):
        loss, grads = loss_grad_fn(w, batch)
        raw_updates, state = optimizer.update(grads, state, w)
        (
            elementwise_updates,
            mask_ema,
            mask_ema_count,
            mask_stats,
        ) = mask_optax_updates_anchor_veto_ema(
            raw_updates,
            synthetic_group_grads,
            anchor_group_grads,
            mask_ema,
            mask_ema_count,
            tail_fraction=args.cnl_cvar_tail,
            beta=args.cnl_mask_ema_beta,
        )
        updates, subspace_stats = project_optax_updates_memory_subspace_cvar(
            raw_updates,
            elementwise_updates,
            tuple(synthetic_subspace_group_grads),
            tuple(anchor_subspace_group_grads),
            memory_layouts,
            tuple(subspace_bases),
            tail_fraction=args.cnl_cvar_tail,
            projection_passes=args.memory_subspace_projection_passes,
        )
        mask_stats.update(subspace_stats)
        raw_norm = tree_l2_norm(raw_updates)
        final_norm = tree_l2_norm(updates)
        mask_stats.update(
            {
                "update_norm/raw": raw_norm,
                "update_norm/final_structured": final_norm,
                "update_norm/kept_fraction": final_norm
                / jnp.maximum(raw_norm, 1e-30),
                "current_objective/sft_loss": loss,
                "current_objective/route_loss": jnp.asarray(0.0, dtype=jnp.float32),
                "current_objective/total_loss": loss,
            }
        )
        w = optax.apply_updates(w, updates)
        return w, state, mask_ema, mask_ema_count, loss, mask_stats

