    def memory_current_loss_and_grad(w, batch, free):
        if not use_memory_occupancy:
            loss, grads = loss_grad_fn(w, batch)
            activity = None
            sft_loss = loss
            route_loss = jnp.asarray(0.0, dtype=jnp.float32)
        elif args.memory_routing_enabled:
            assert route_loss_grad_fn is not None
            (loss, (activity, sft_loss, route_loss)), grads = route_loss_grad_fn(
                w,
                batch,
                free,
            )
        else:
            assert activity_loss_grad_fn is not None
            (loss, activity), grads = activity_loss_grad_fn(w, batch)
            sft_loss = loss
            route_loss = jnp.asarray(0.0, dtype=jnp.float32)
        return loss, activity, sft_loss, route_loss, grads

